window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["国家新闻出版署"] = {"neibuziliaoxingchubanwuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范内部资料性出版物的管理，根据《印刷业管理条例》和有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"凡从事内部资料性出版物编印和发送活动，必须遵守本办法。 本办法所称内部资料性出版物（以下简称内部资料），是指在本行业、本系统、本单位内部，用于指导工作、交流信息的非卖性单本成册或连续性折页、散页印刷品，不包括机关公文性的简报等信息资料。 内部资料分为一次性内部资料和连续性内部资料。"},{"i":3,"n":"第三条","txt":"对内部资料的编印，实行核发《内部资料性出版物准印证》(以下简称《准印证》)管理。未经批准取得《准印证》,任何单位和个人不得从事内部资料的编印活动。"},{"i":4,"n":"第四条","txt":"编印内部资料，应当向所在地省、自治区、直辖市新闻出版行政部门提出申请，经审核批准，领取《准印证》后，方可从事编印活动。"},{"i":5,"n":"第五条","txt":"申请编印一次性内部资料，须符合以下条件： （一）申请方应为党政机关、企事业、社会团体等单位； （二）编印目的及发送范围符合本办法第二条的规定，编印内容与编印单位的性质和能力相一致； （三）稿件内容符合本办法第十三条的规定； （四）拟委托印刷的单位为出版物印刷企业。"},{"i":6,"n":"第六条","txt":"申请编印一次性内部资料，应当提交申请书和稿件清样。 申请书应当载明一次性内部资料的名称、申请单位、编印目的、内容简介、印数、印张数、开本、发送对象、印刷单位等项目。"},{"i":7,"n":"第七条","txt":"申请编印连续性内部资料，须符合以下条件： （一）申请方应为党政机关、企事业、社会团体等单位； （二）有确定的名称，名称应充分体现编印宗旨及地域、行业或单位特征； （三）有确定的编印目的和固定的发送对象，编印目的应限于与编印单位业务相一致的工作指导、信息交流；编印内容应与编印单位的性质和能力相一致；企业编印散页连续性内部资料，应主要用于指导本企业的生产经营、企业文化和精神文明建设； （四）有适应编印活动需要的人员； （五）有稳定的资金来源和固定的办公场所； （六）拟委托印刷的单位为出版物印刷企业。"},{"i":8,"n":"第八条","txt":"编印连续性内部资料，应当提交下列材料： （一）编印连续性内部资料的申请书，内容包括：连续性内部资料的名称、编印目的、栏目设置、印数、印制周期、开本、发送对象和经费来源等项目; （二）编印单位资质证明材料; （三）编印人员的基本情况及身份证明； （四）拟承印单位的《印刷经营许可证》复印件。"},{"i":9,"n":"第九条","txt":"具有下列情形之一的，不予核发内部资料《准印证》： （一）不符合本办法第二条、第五条或第七条规定的审批条件的； （二）广告印刷品、介绍推广本单位基本情况的宣传资料，或者仅含有历法信息及广告内容的挂历、台历、年历等无需申领《准印证》的一般印刷品； （三）中小学教科书及教辅材料、地图、个人画册、个人文集等应由出版单位出版的作品。"},{"i":10,"n":"第十条","txt":"省、自治区、直辖市新闻出版行政部门自受理申请之日起20日内作出审批决定。决定批准的，核发一次性内部资料或者连续性内部资料《准印证》；不予批准的，应当书面说明理由。"},{"i":11,"n":"第十一条","txt":"《准印证》按一种内部资料一证的原则核发，其中对一次性内部资料，一次性使用有效；连续性内部资料的《准印证》有效期为1年，期满须重新核发。 《准印证》不得转让和出租出借，内部资料停办后《准印证》应及时交回发证部门。"},{"i":12,"n":"第十二条","txt":"内部资料的编印单位应当对所编印的内容和质量负责，并承担法律责任。"},{"i":13,"n":"第十三条","txt":"内部资料不得含有下列内容： （一）反对宪法确定的基本原则的； （二）危害国家统一、主权和领土完整的； （三）泄露国家秘密、危害国家安全或者损害国家荣誉和利益的； （四）煽动民族仇恨、民族歧视，破坏民族团结，或者侵害少数民族风俗、习惯的； （五）宣扬邪教、迷信的； （六）扰乱社会秩序，破坏社会稳定的； （七）宣扬淫秽、赌博、暴力或者教唆犯罪的； （八）侮辱或者诽谤他人，侵害他人合法权益的； （九）危害社会公德或者民族优秀文化传统的； （十）法律、行政法规和国家规定禁止的其他内容的。"},{"i":14,"n":"第十四条","txt":"内部资料必须在封面完整印刷标注《准印证》编号和“内部资料，免费交流”字样，并在明显位置（封面、封底或版权页）标明编印单位、发送对象、印刷单位、印刷日期、印数等，连续性内部资料还须标明期号。 连续性内部资料不得使用“××报”、“××刊”或“××杂志”、“记者××”、“期刊社”、“杂志社”、“刊号”等字样，不得在内文中以“本报”、“本刊”自称。"},{"i":15,"n":"第十五条","txt":"编印内部资料，应严格遵守以下规定： （一）按照批准的名称、开本（开版）、周期印制，不得用《准印证》印制其他内容，一次性内部资料不得一证多期，连续性内部资料不得一期多版； （二）严格限定在本行业、本系统、本单位内部交流，不得标价、销售或征订发行，不得在公共场所摆放，不得向境外传播；不得将服务对象及社会公众作为发送对象，也不得以提供信息为名，将无隶属关系和指导关系的行业、企事业单位作为发送对象； （三）不得以工本费、会员费、版面费、服务费等任何形式收取任何费用，不得刊登广告，不得搞经营性活动；编印单位不得利用登记、年检、办证、办照、评奖、验收、论证等工作之便向服务和管理对象摊派或变相摊派； （四）不得将内部资料承包给其他组织和个人，不得与外单位以“协办”等其他形式进行编印和发送。"},{"i":16,"n":"第十六条","txt":"内部资料必须在编印单位所在地省、自治区、直辖市内的出版物印刷企业印刷。 印刷企业接受委托印刷内部资料，须验证所在地新闻出版行政部门核发的《准印证》原件并收存《准印证》复印件；接受委托印刷宗教内容的内部资料，还须验证省、自治区、直辖市人民政府宗教事务管理部门的批准文件。 编印和承印单位必须严格按照《准印证》核准的项目印制，严禁擅自更改《准印证》核准项目。 《准印证》复印件须保存两年，以备查验。"},{"i":17,"n":"第十七条","txt":"内部资料的印刷质量应符合印刷质量标准。"},{"i":18,"n":"第十八条","txt":"内部资料的编印单位须在印刷完成后10日内向核发《准印证》的新闻出版行政部门送交样本。"},{"i":19,"n":"第十九条","txt":"各级新闻出版行政部门负责本行政区域内部资料的日常监督管理工作。 内部资料实行审读制度和质量检查制度，新闻出版行政部门要配备必要的人员和经费对内部资料进行内容审读和质量监管。"},{"i":20,"n":"第二十条","txt":"连续性内部资料编印单位的有关人员应按照省、自治区、直辖市新闻出版行政部门的要求，参加有关法规、业务培训。"},{"i":21,"n":"第二十一条","txt":"连续性内部资料编印单位需要延续《准印证》有效期的，应当在《准印证》有效期届满30日前向省、自治区、直辖市新闻出版行政部门提出申请。 省、自治区、直辖市新闻出版行政部门负责审核连续性内部资料的内容、质量、是否符合许可条件以及遵守本办法各项规定情况等。审核通过的，重新核发《准印证》；审核未通过或者逾期一个月不办理延期申请的，原《准印证》自动失效，予以注销。 省、自治区、直辖市新闻出版行政部门应于每年3月底前，将本地区上一年度内部资料监督管理情况报告国家新闻出版广电总局。"},{"i":22,"n":"第二十二条","txt":"有下列行为之一的，由县级以上地方人民政府新闻出版行政部门责令改正、停止违法行为，根据情节轻重，给予警告，并处1千元以下的罚款；以营利为目的从事下列行为的，并处3万元以下罚款： （一）未经批准擅自编印内部资料的； （二）编印本办法第十三条规定禁止内容的内部资料的； （三）违反本办法第十四条、第十五条规定，编印、发送内部资料的； （四）委托非出版物印刷企业印刷内部资料或者未按照《准印证》核准的项目印制的； （五）未按照本办法第十八条送交样本的； （六）违反本办法其他规定的。 其中，有前款第（一）项至第（三）项违法行为的，对非法编印的内部资料予以没收，超越发送范围的责令收回。 未取得《准印证》，编印具有内部资料形式，但不符合内部资料内容或发送要求的印刷品，经鉴定为非法出版物的，按照《出版管理条例》第六十一条或第六十二条的规定处罚。"},{"i":23,"n":"第二十三条","txt":"有下列情形的，由县级以上新闻出版行政部门依照《印刷业管理条例》的有关规定，责令停业整顿，没收内部资料和违法所得，违法经营额1万元以上的，并处违法经营额5倍以上10倍以下的罚款；违法经营额不足1万元的，并处1万元以上5万元以下的罚款；情节严重的，由原发证机关吊销许可证： （一）印刷业经营者印刷明知或者应知含有本办法第十三条规定禁止内容的内部资料的； （二）非出版物印刷企业印刷内部资料的。"},{"i":24,"n":"第二十四条","txt":"出版物印刷企业未按本规定承印内部资料的，由县级以上新闻出版行政部门依照《印刷业管理条例》的有关规定，给予警告，没收违法所得，违法经营额1万元以上的，并处违法经营额5倍以上10倍以下的罚款；违法经营额不足1万元的，并处1万元以上5万元以下的罚款；情节严重的，责令停业整顿或者由原发证机关吊销许可证。"},{"i":25,"n":"第二十五条","txt":"省、自治区、直辖市新闻出版行政部门可根据本地区内部资料管理的情况，对本办法规定的内部资料的审批条件和审批程序作出具体规定，也可以规定由副省级以下新闻出版行政部门承担部分审批职责。"},{"i":26,"n":"第二十六条","txt":"各级各类学校学生自行编印仅面向本校发送的内部资料由该校校内有关主管部门负责审批和管理。"},{"i":27,"n":"第二十七条","txt":"《准印证》由省、自治区、直辖市新闻出版行政部门按照新闻出版广电总局统一确定的格式制作。"},{"i":28,"n":"第二十八条","txt":"本办法自2015年4月1日起施行。新闻出版署于1997年12月30日发布施行的《内部资料性出版物管理办法》同时废止，本办法施行前与本办法不一致的其他规定不再执行。"}],"chubanzhuanyejishurenyuanzhiyezigeguanliguiding":[{"i":1,"n":"第一条","txt":"为了规范出版专业职业资格管理，提高出版从业人员的整体素质，加强出版专业技术队伍建设，根据国务院《出版管理条例》、《音像制品管理条例》、《国务院对确需保留的行政审批项目设定行政许可的决定》和国家对职业资格管理的有关制度，制定本规定。"},{"i":2,"n":"第二条","txt":"国家对在报纸、期刊、图书、音像、电子、网络出版单位从事出版专业技术工作的人员实行职业资格制度，对职业资格实行登记注册管理。 本规定所称出版专业技术人员包括在图书、非新闻性期刊、音像、电子、网络出版单位内承担内容加工整理、装帧和版式设计等工作的编辑人员和校对人员，以及在报纸、新闻性期刊出版单位从事校对工作的专业技术人员。"},{"i":3,"n":"第三条","txt":"出版专业技术人员职业资格分为初级、中级和高级。初级、中级职业资格通过全国出版专业技术人员职业资格考试取得，高级职业资格通过考试、按规定评审取得。"},{"i":4,"n":"第四条","txt":"凡在出版单位从事出版专业技术工作的人员，必须在到岗2年内取得出版专业职业资格证书，并按本规定办理登记手续；否则，不得继续从事出版专业技术工作。 在出版单位担任责任编辑的人员必须在到岗前取得中级以上出版专业职业资格，并办理注册手续，领取责任编辑证书。 本规定所称责任编辑是指在出版单位为保证出版物的质量符合出版要求，专门负责对拟出版的作品内容进行全面审核和加工整理并在出版物上署名的编辑人员。"},{"i":5,"n":"第五条","txt":"在出版单位担任社长、总编辑、主编、编辑室主任（均含副职）职务的人员，除应具备国家规定的任职条件外，还必须具有中级以上出版专业职业资格并履行登记、注册手续。"},{"i":6,"n":"第六条","txt":"新闻出版总署负责全国出版单位出版专业技术人员职业资格的监督管理工作和中央在京出版单位出版专业技术人员职业资格登记注册工作。省、自治区、直辖市新闻出版行政部门负责本行政区域内的出版专业技术人员职业资格登记注册及管理工作。"},{"i":7,"n":"第七条","txt":"出版专业技术人员应按照规定参加继续教育。 继续教育的具体内容，由新闻出版总署另行规定。"},{"i":8,"n":"第八条","txt":"已取得出版专业技术人员职业资格证书的人员应当在取得证书后3个月内申请职业资格登记；未能及时登记的，在按规定参加继续教育的情况下，可以保留其5年内申请职业资格登记的资格。"},{"i":9,"n":"第九条","txt":"职业资格首次登记，应提供以下材料： （一）出版专业职业资格证书原件； （二）身份证复印件； （三）职业资格登记申请表。"},{"i":10,"n":"第十条","txt":"职业资格登记材料由申请人所在出版单位统一报送。中央在京出版单位申报材料由新闻出版总署受理，其他出版单位申报材料由所在地省、自治区、直辖市新闻出版行政部门受理。登记部门应在受理后20日内办理职业资格登记手续。"},{"i":11,"n":"第十一条","txt":"职业资格登记有效期3年，每3年续展登记一次。续展登记时，由申请人所在出版单位于有效期满前30日内申请办理续展登记手续；如有特殊情况，登记有效期可适当延长，但最长不超过3个月，逾期仍不办理续展登记手续的，原登记自动失效。 职业资格登记失效后，按规定参加继续教育的，可以保留其5年内申请职业资格续展登记的资格。 已按规定办理责任编辑注册手续并取得责任编辑证书的人员，无需办理续展登记。"},{"i":12,"n":"第十二条","txt":"职业资格续展登记，需提供以下材料： （一）出版专业职业资格证书原件； （二）职业资格续展登记申请表; （三）近3年继续教育证明。"},{"i":13,"n":"第十三条","txt":"已登记的出版专业技术人员变更出版单位或取得高一级职业资格的，应在3个月内按本规定第九条、第十条申请变更登记。"},{"i":14,"n":"第十四条","txt":"在出版单位拟担任责任编辑的人员，应首先进行职业资格登记，然后申请责任编辑注册，取得责任编辑证书后，方可从事责任编辑工作。 责任编辑注册申请可与职业资格登记申请同时提出。"},{"i":15,"n":"第十五条","txt":"申请责任编辑注册的人员应具备与责任编辑岗位相适应的政治素质、业务能力和职业道德；出版单位应对拟申请责任编辑注册人员的上述情况进行审核。"},{"i":16,"n":"第十六条","txt":"责任编辑首次注册应当提交以下材料： （一）中级以上出版专业职业资格证书原件； （二）身份证复印件； （三）责任编辑注册申请表； （四）继续教育证明材料。"},{"i":17,"n":"第十七条","txt":"责任编辑注册材料由申请人所在出版单位统一报送。中央在京出版单位注册材料由新闻出版总署受理，其他出版单位注册材料由所在地省、自治区、直辖市新闻出版行政部门受理。注册部门应在受理后20日内办理责任编辑注册手续，为同意注册者颁发责任编辑证书。"},{"i":18,"n":"第十八条","txt":"责任编辑注册有效期3年，每3年续展注册一次。续展注册时，由申请人所在出版单位于有效期满前30日内申请办理续展注册手续；如有特殊情况，注册有效期可适当延长，但最长不超过3个月，逾期仍不办理续展注册手续的，原注册自动失效。 责任编辑注册失效后，按规定参加继续教育的，可以保留其5年内申请责任编辑续展注册的资格。"},{"i":19,"n":"第十九条","txt":"申请责任编辑续展注册，应提交以下材料： （一）责任编辑证书原件； （二）责任编辑续展注册申请表； （三）近3年继续教育证明材料。"},{"i":20,"n":"第二十条","txt":"有下列情况之一者，不予续展注册，注销责任编辑证书： （一）有本规定第二十五条所列情形之一，情节严重的; （二）连续2次年度考核达不到岗位职责要求的; （三）新闻出版总署认定不予续展注册的其他情形的。"},{"i":21,"n":"第二十一条","txt":"被注销责任编辑证书的人员，3年内不得申请责任编辑注册。"},{"i":22,"n":"第二十二条","txt":"已注册的责任编辑变更出版单位或取得高一级职业资格的，应在3个月内按本规定第十六条、第十七条申请变更注册。"},{"i":23,"n":"第二十三条","txt":"责任编辑调离出版单位并不再从事责任编辑工作的，由原所在的出版单位收回《责任编辑证书》，并交原注册机构统一销毁。"},{"i":24,"n":"第二十四条","txt":"新闻出版总署定期向社会公布取得责任编辑证书的人员姓名、所在单位、证书编号等信息，接受社会监督。"},{"i":25,"n":"第二十五条","txt":"责任编辑有下列情形之一的，由新闻出版总署或者省、自治区、直辖市新闻出版行政部门给予警告；情节严重的，注销其责任编辑证书： （一）有参与买卖书号、刊号、版号等违反出版法规行为的； （二）担任责任编辑的出版物出现内容质量、编校质量等违法问题的。"},{"i":26,"n":"第二十六条","txt":"出版专业技术人员因违反出版法规被追究刑事责任的，由新闻出版总署或者省、自治区、直辖市新闻出版行政部门取消其出版专业职业资格，注销其出版专业职业资格登记和责任编辑注册，不得继续从事出版专业技术工作，并不得申请参加出版专业职业资格考试。"},{"i":27,"n":"第二十七条","txt":"出版单位有下列情形之一的，由新闻出版总署或者省、自治区、直辖市新闻出版行政部门给予警告、可以根据情节并处3万元以下罚款： （一）聘用未取得责任编辑证书的人员从事责任编辑工作的； （二）未按本规定履行出版专业技术人员登记注册手续的。"},{"i":28,"n":"第二十八条","txt":"对出版单位作出行政处罚，新闻出版总署或者省、自治区、直辖市新闻出版行政部门可以告知其主办单位和主管单位，可以向社会公布。"},{"i":29,"n":"第二十九条","txt":"责任编辑证书由新闻出版总署统一印制。"},{"i":30,"n":"第三十条","txt":"中国人民解放军和中国人民武装警察部队系统出版单位出版专业技术人员的职业资格管理工作，由中国人民解放军总政治部宣传部新闻出版局参照本规定执行，并将登记注册信息报新闻出版总署备案。"},{"i":31,"n":"第三十一条","txt":"已取得其他行业高级职称并在出版单位从事出版专业技术工作的人员，可以按照规定申请《专业技术职务资格证书》（编辑专业高级职称证书）的职称转评。"},{"i":32,"n":"第三十二条","txt":"在报纸、新闻性期刊出版单位从事采编工作人员的职业资格管理办法另行制定。 在出版单位从事少数民族语言文字编辑、校对工作的出版专业技术人员职业资格管理办法另行制定。"},{"i":33,"n":"第三十三条","txt":"本规定自2008年6月1日起施行，新闻出版总署2002年6月3日颁布的《出版专业技术人员职业资格管理暂行规定》同时废止。"}],"chubanwushichangguanliguiding":[{"i":1,"n":"第一条","txt":"为规范出版物发行活动及其监督管理，建立全国统一开放、竞争有序的出版物市场体系，满足人民群众精神文化需求，推进社会主义文化强国建设，根据《出版管理条例》和有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于出版物发行活动及其监督管理。本规定所称出版物，是指图书、报纸、期刊、音像制品、电子出版物。 本规定所称发行，包括批发、零售以及出租、展销等活动。 批发是指供货商向其他出版物经营者销售出版物。 零售是指经营者直接向消费者销售出版物。 出租是指经营者以收取租金的形式向消费者提供出版物。 展销是指主办者在一定场所、时间内组织出版物经营者集中展览、销售、订购出版物。"},{"i":3,"n":"第三条","txt":"国家对出版物批发、零售依法实行许可制度。从事出版物批发、零售活动的单位和个人凭出版物经营许可证开展出版物批发、零售活动；未经许可，任何单位和个人不得从事出版物批发、零售活动。 任何单位和个人不得委托非出版物批发、零售单位或者个人销售出版物或者代理出版物销售业务。"},{"i":4,"n":"第四条","txt":"国家新闻出版广电总局负责全国出版物发行活动的监督管理，负责制定全国出版物发行业发展规划。 省、自治区、直辖市人民政府出版行政主管部门负责本行政区域内出版物发行活动的监督管理，制定本省、自治区、直辖市出版物发行业发展规划。省级以下各级人民政府出版行政主管部门负责本行政区域内出版物发行活动的监督管理。 制定出版物发行业发展规划须经科学论证，遵循合法公正、符合实际、促进发展的原则。"},{"i":5,"n":"第五条","txt":"国家保障、促进发行业的发展与转型升级，扶持实体书店、农村发行网点、发行物流体系、发行业信息化建设等，推动网络发行等新兴业态发展，推动发行业与其他相关产业融合发展。对为发行业发展作出重要贡献的单位和个人，按照国家有关规定给予奖励。"},{"i":6,"n":"第六条","txt":"发行行业的社会团体按照其章程，在出版行政主管部门的指导下，实行自律管理。"},{"i":7,"n":"第七条","txt":"单位从事出版物批发业务，应当具备下列条件： （一）已完成工商注册登记，具有法人资格； （二）工商登记经营范围含出版物批发业务； （三）有与出版物批发业务相适应的设备和固定的经营场所，经营场所面积合计不少于50平方米； （四）具备健全的管理制度并具有符合行业标准的信息管理系统。 本规定所称经营场所，是指企业在工商行政主管部门注册登记的住所。"},{"i":8,"n":"第八条","txt":"单位申请从事出版物批发业务，可向所在地地市级人民政府出版行政主管部门提交申请材料，地市级人民政府出版行政主管部门在接受申请材料之日起10个工作日内完成审核，审核后报省、自治区、直辖市人民政府出版行政主管部门审批；申请单位也可直接报所在地省、自治区、直辖市人民政府出版行政主管部门审批。 省、自治区、直辖市人民政府出版行政主管部门自受理申请之日起20个工作日内作出批准或者不予批准的决定。批准的，由省、自治区、直辖市人民政府出版行政主管部门颁发出版物经营许可证，并报国家新闻出版广电总局备案。不予批准的，应当向申请人书面说明理由。 申请材料包括下列书面材料： （一）营业执照正副本复印件； （二）申请书，载明单位基本情况及申请事项； （三）企业章程； （四）注册资本数额、来源及性质证明； （五）经营场所情况及使用权证明； （六）法定代表人及主要负责人的身份证明； （七）企业信息管理系统情况的证明"},{"i":9,"n":"第九条","txt":"单位、个人从事出版物零售业务，应当具备下列条件： （一）已完成工商注册登记； （二）工商登记经营范围含出版物零售业务； （三）有固定的经营场所。"},{"i":10,"n":"第十条","txt":"单位、个人申请从事出版物零售业务，须报所在地县级人民政府出版行政主管部门审批。 县级人民政府出版行政主管部门应当自受理申请之日起20个工作日内作出批准或者不予批准的决定。批准的，由县级人民政府出版行政主管部门颁发出版物经营许可证，并报上一级出版行政主管部门备案；其中门店营业面积在5000平方米以上的应同时报省级人民政府出版行政主管部门备案。不予批准的，应当向申请单位、个人书面说明理由。 申请材料包括下列书面材料： （一）营业执照正副本复印件； （二）申请书，载明单位或者个人基本情况及申请事项； （三）经营场所的使用权证明。"},{"i":11,"n":"第十一条","txt":"单位从事中小学教科书发行业务，应取得国家新闻出版广电总局批准的中小学教科书发行资质，并在批准的区域范围内开展中小学教科书发行活动。单位从事中小学教科书发行业务，应当具备下列条件： （一）以出版物发行为主营业务的公司制法人； （二）有与中小学教科书发行业务相适应的组织机构和发行人员； （三）有能够保证中小学教科书储存质量要求的、与其经营品种和规模相适应的储运能力，在拟申请从事中小学教科书发行业务的省、自治区、直辖市、计划单列市的仓储场所面积在5000平方米以上，并有与中小学教科书发行相适应的自有物流配送体系； （四）有与中小学教科书发行业务相适应的发行网络。在拟申请从事中小学教科书发行业务的省、自治区、直辖市、计划单列市的企业所属出版物发行网点覆盖不少于当地70%的县（市、区），且以出版物零售为主营业务，具备相应的中小学教科书储备、调剂、添货、零售及售后服务能力； （五）具备符合行业标准"},{"i":12,"n":"第十二条","txt":"单位申请从事中小学教科书发行业务，须报国家新闻出版广电总局审批。 国家新闻出版广电总局应当自受理之日起20个工作日内作出批准或者不予批准的决定。批准的，由国家新闻出版广电总局作出书面批复并颁发中小学教科书发行资质证。不予批准的，应当向申请单位书面说明理由。 申请材料包括下列书面材料： （一）申请书，载明单位基本情况及申请事项； （二）企业章程； （三）出版物经营许可证和企业法人营业执照正副本复印件； （四）法定代表人及主要负责人的身份证明，有关发行人员的资质证明； （五）最近三年的企业法人年度财务会计报告及证明企业信誉的有关材料； （六）经营场所、发行网点和储运场所的情况及使用权证明； （七）企业信息管理系统情况的证明材料； （八）企业发行中小学教科书过程中能够提供的服务和相关保障措施； （九）企业法定代表人签署的企业依法经营中小学教科书发行业务的承诺书； （十）拟申请从事中小学教科书"},{"i":13,"n":"第十三条","txt":"单位、个人从事出版物出租业务，应当于取得营业执照后15日内到当地县级人民政府出版行政主管部门备案。 备案材料包括下列书面材料： （一）营业执照正副本复印件； （二）经营场所情况； （三）法定代表人或者主要负责人情况。 相关出版行政主管部门应在10个工作日内向申请备案单位、个人出具备案回执。"},{"i":14,"n":"第十四条","txt":"国家允许外商投资企业从事出版物发行业务。 设立外商投资出版物发行企业或者外商投资企业从事出版物发行业务，申请人应向地方商务主管部门报送拟设立外商投资出版物发行企业的合同、章程，办理外商投资审批手续。地方商务主管部门在征得出版行政主管部门同意后，按照有关法律、法规的规定，作出批准或者不予批准的决定。予以批准的，颁发外商投资企业批准证书，并在经营范围后加注“凭行业经营许可开展”；不予批准的，书面通知申请人并说明理由。 申请人持外商投资企业批准证书到所在地工商行政主管部门办理营业执照或者在营业执照企业经营范围后加注相关内容，并按照本规定第七条至第十条及第十三条的有关规定到所在地出版行政主管部门履行审批或备案手续。"},{"i":15,"n":"第十五条","txt":"单位、个人通过互联网等信息网络从事出版物发行业务的，应当依照本规定第七条至第十条的规定取得出版物经营许可证。 已经取得出版物经营许可证的单位、个人在批准的经营范围内通过互联网等信息网络从事出版物发行业务的，应自开展网络发行业务后15日内到原批准的出版行政主管部门备案。 备案材料包括下列书面材料： （一）出版物经营许可证和营业执照正副本复印件； （二）单位或者个人基本情况； （三）从事出版物网络发行所依托的信息网络的情况。 相关出版行政主管部门应在10个工作日内向备案单位、个人出具备案回执。"},{"i":16,"n":"第十六条","txt":"书友会、读者俱乐部或者其他类似组织申请从事出版物零售业务，按照本规定第九条、第十条的有关规定到所在地出版行政主管部门履行审批手续。"},{"i":17,"n":"第十七条","txt":"从事出版物发行业务的单位、个人可在原发证机关所辖行政区域一定地点设立临时零售点开展其业务范围内的出版物销售活动。设立临时零售点时间不得超过10日，应提前到设点所在地县级人民政府出版行政主管部门备案并取得备案回执，并应遵守所在地其他有关管理规定。 备案材料包括下列书面材料： （一）出版物经营许可证和营业执照正副本复印件； （二）单位、个人基本情况； （三）设立临时零售点的地点、时间、销售出版物品种； （四）其他相关部门批准设立临时零售点的材料。"},{"i":18,"n":"第十八条","txt":"出版物批发单位可以从事出版物零售业务。 出版物批发、零售单位设立不具备法人资格的发行分支机构，或者出版单位设立发行本版出版物的不具备法人资格的发行分支机构，不需单独办理出版物经营许可证，但应依法办理分支机构工商登记，并于领取营业执照后15日内到原发证机关和分支机构所在地出版行政主管部门备案。 备案材料包括下列书面材料： （一）出版物经营许可证或者出版单位的出版许可证及分支机构营业执照正副本复印件； （二）单位基本情况； （三）单位设立不具备法人资格的发行分支机构的经营场所、经营范围等情况。 相关出版行政主管部门应在10个工作日内向备案单位、个人出具备案回执。"},{"i":19,"n":"第十九条","txt":"从事出版物发行业务的单位、个人变更出版物经营许可证登记事项，或者兼并、合并、分立的，应当依照本规定到原批准的出版行政主管部门办理审批手续。出版行政主管部门自受理申请之日起20个工作日内作出批准或者不予批准的决定。批准的，由出版行政主管部门换发出版物经营许可证；不予批准的，应当向申请单位、个人书面说明理由。 申请材料包括下列书面材料： （一）出版物经营许可证和营业执照正副本复印件； （二）申请书，载明单位或者个人基本情况及申请变更事项； （三）其他需要的证明材料。 从事出版物发行业务的单位、个人终止经营活动的，应当于15日内持出版物经营许可证和营业执照向原批准的出版行政主管部门备案，由原批准的出版行政主管部门注销出版物经营许可证。"},{"i":20,"n":"第二十条","txt":"任何单位和个人不得发行下列出版物： （一）含有《出版管理条例》禁止内容的违禁出版物； （二）各种非法出版物，包括：未经批准擅自出版、印刷或者复制的出版物，伪造、假冒出版单位或者报刊名称出版的出版物，非法进口的出版物； （三）侵犯他人著作权或者专有出版权的出版物； （四）出版行政主管部门明令禁止出版、印刷或者复制、发行的出版物。"},{"i":21,"n":"第二十一条","txt":"内部发行的出版物不得公开宣传、陈列、展示、征订、销售或面向社会公众发送。"},{"i":22,"n":"第二十二条","txt":"从事出版物发行业务的单位和个人在发行活动中应当遵循公平、守法、诚实、守信的原则，依法订立供销合同，不得损害消费者的合法权益。 从事出版物发行业务的单位、个人，必须遵守下列规定： （一）从依法取得出版物批发、零售资质的出版发行单位进货；发行进口出版物的，须从依法设立的出版物进口经营单位进货； （二）不得超出出版行政主管部门核准的经营范围经营； （三）不得张贴、散发、登载有法律、法规禁止内容的或者有欺诈性文字、与事实不符的征订单、广告和宣传画； （四）不得擅自更改出版物版权页； （五）出版物经营许可证应在经营场所明显处张挂；利用信息网络从事出版物发行业务的，应在其网站主页面或者从事经营活动的网页醒目位置公开出版物经营许可证和营业执照登载的有关信息或链接标识； （六）不得涂改、变造、出租、出借、出售或者以其他任何形式转让出版物经营许可证和批准文件；"},{"i":23,"n":"第二十三条","txt":"从事出版物发行业务的单位、个人，应查验供货单位的出版物经营许可证并留存复印件或电子文件，并将出版物发行进销货清单等有关非财务票据至少保存两年，以备查验。 进销货清单应包括进销出版物的名称、数量、折扣、金额以及发货方和进货方单位公章（签章）。"},{"i":24,"n":"第二十四条","txt":"出版物发行从业人员应接受出版行政主管部门组织的业务培训。出版物发行单位应建立职业培训制度，积极组织本单位从业人员参加依法批准的职业技能鉴定机构实施的发行员职业技能鉴定。"},{"i":25,"n":"第二十五条","txt":"出版单位可以发行本出版单位出版的出版物。发行非本出版单位出版的出版物的，须按照从事出版物发行业务的有关规定办理审批手续。"},{"i":26,"n":"第二十六条","txt":"为出版物发行业务提供服务的网络交易平台应向注册地省、自治区、直辖市人民政府出版行政主管部门备案，接受出版行政主管部门的指导与监督管理。 备案材料包括下列书面材料： （一）营业执照正副本复印件； （二）单位基本情况； （三）网络交易平台的基本情况。 省、自治区、直辖市人民政府出版行政主管部门应于10个工作日内向备案的网络交易平台出具备案回执。 提供出版物发行网络交易平台服务的经营者，应当对申请通过网络交易平台从事出版物发行业务的经营主体身份进行审查，核实经营主体的营业执照、出版物经营许可证，并留存证照复印件或电子文档备查。不得向无证无照、证照不齐的经营者提供网络交易平台服务。 为出版物发行业务提供服务的网络交易平台经营者应建立交易风险防控机制，保留平台内从事出版物发行业务经营主体的交易记录两年以备查验。对在网络交易平台内从事各类违法出版物发行活动的，应当采取有效措施予以制止，并及时向所在"},{"i":27,"n":"第二十七条","txt":"省、自治区、直辖市出版行政主管部门和全国性出版、发行行业协会，可以主办全国性的出版物展销活动和跨省专业性出版物展销活动。主办单位应提前2个月报国家新闻出版广电总局备案。 市、县级出版行政主管部门和省级出版、发行协会可以主办地方性的出版物展销活动。主办单位应提前2个月报上一级出版行政主管部门备案。 备案材料包括下列书面材料： （一）展销活动主办单位； （二）展销活动时间、地点； （三）展销活动的场地、参展单位、展销出版物品种、活动筹备等情况。"},{"i":28,"n":"第二十八条","txt":"从事中小学教科书发行业务，必须遵守下列规定： （一）从事中小学教科书发行业务的单位必须具备中小学教科书发行资质； （二）纳入政府采购范围的中小学教科书，其发行单位须按照《中华人民共和国政府采购法》的有关规定确定； （三）按照教育行政主管部门和学校选定的中小学教科书，在规定时间内完成发行任务，确保“课前到书，人手一册”。因自然灾害等不可抗力导致中小学教科书发行受到影响的，应及时采取补救措施，并报告所在地出版行政和教育行政主管部门； （四）不得在中小学教科书发行过程中擅自征订、搭售教学用书目录以外的出版物； （五）不得将中小学教科书发行任务向他人转让和分包； （六）不得涂改、倒卖、出租、出借中小学教科书发行资质证书； （七）中小学教科书发行费率按照国家有关规定执行，不得违反规定收取发行费用； （八）做好中小学教科书的调剂、添货、零售和售后服务等相关工作； （九）应于发行任务完成后30个工作"},{"i":29,"n":"第二十九条","txt":"任何单位、个人不得从事本规定第二十条所列出版物的征订、储存、运输、邮寄、投递、散发、附送等活动。 从事出版物储存、运输、投递等活动，应当接受出版行政主管部门的监督检查。"},{"i":30,"n":"第三十条","txt":"从事出版物发行业务的单位、个人应当按照出版行政主管部门的规定接受年度核验，并按照《中华人民共和国统计法》《新闻出版统计管理办法》及有关规定如实报送统计资料，不得以任何借口拒报、迟报、虚报、瞒报以及伪造和篡改统计资料。 出版物发行单位、个人不再具备行政许可的法定条件的，由出版行政主管部门责令限期改正；逾期仍未改正的，由原发证机关撤销出版物经营许可证。 中小学教科书发行单位不再具备中小学教科书发行资质的法定条件的，由出版行政主管部门责令限期改正；逾期仍未改正的，由原发证机关撤销中小学教科书发行资质证。"},{"i":31,"n":"第三十一条","txt":"未经批准，擅自从事出版物发行业务的，依照《出版管理条例》第六十一条处罚。"},{"i":32,"n":"第三十二条","txt":"发行违禁出版物的，依照《出版管理条例》第六十二条处罚。 发行国家新闻出版广电总局禁止进口的出版物，或者发行未从依法批准的出版物进口经营单位进货的进口出版物，依照《出版管理条例》第六十三条处罚。 发行其他非法出版物和出版行政主管部门明令禁止出版、印刷或者复制、发行的出版物的，依照《出版管理条例》第六十五条处罚。 发行违禁出版物或者非法出版物的，当事人对其来源作出说明、指认，经查证属实的，没收出版物和非法所得，可以减轻或免除其他行政处罚。"},{"i":33,"n":"第三十三条","txt":"违反本规定发行侵犯他人著作权或者专有出版权的出版物的，依照《中华人民共和国著作权法》和《中华人民共和国著作权法实施条例》的规定处罚。"},{"i":34,"n":"第三十四条","txt":"在中小学教科书发行过程中违反本规定，有下列行为之一的，依照《出版管理条例》第六十五条处罚： （一）发行未经依法审定的中小学教科书的； （二）不具备中小学教科书发行资质的单位从事中小学教科书发行活动的； （三）未按照《中华人民共和国政府采购法》有关规定确定的单位从事纳入政府采购范围的中小学教科书发行活动的。"},{"i":35,"n":"第三十五条","txt":"出版物发行单位未依照规定办理变更审批手续的，依照《出版管理条例》第六十七条处罚。"},{"i":36,"n":"第三十六条","txt":"单位、个人违反本规定被吊销出版物经营许可证的，其法定代表人或者主要负责人自许可证被吊销之日起10年内不得担任发行单位的法定代表人或者主要负责人。"},{"i":37,"n":"第三十七条","txt":"违反本规定，有下列行为之一的，由出版行政主管部门责令停止违法行为，予以警告，并处3万元以下罚款： （一）未能提供近两年的出版物发行进销货清单等有关非财务票据或者清单、票据未按规定载明有关内容的； （二）超出出版行政主管部门核准的经营范围经营的； （三）张贴、散发、登载有法律、法规禁止内容的或者有欺诈性文字、与事实不符的征订单、广告和宣传画的； （四）擅自更改出版物版权页的； （五）出版物经营许可证未在经营场所明显处张挂或者未在网页醒目位置公开出版物经营许可证和营业执照登载的有关信息或者链接标识的； （六）出售、出借、出租、转让或者擅自涂改、变造出版物经营许可证的； （七）公开宣传、陈列、展示、征订、销售或者面向社会公众发送规定应由内部发行的出版物的； （八）委托无出版物批发、零售资质的单位或者个人销售出版物或者代理出版物销售业务的； （九）未从依法取得出版物批发、零售资质的出版发行单位"},{"i":38,"n":"第三十八条","txt":"在中小学教科书发行过程中违反本规定，有下列行为之一的，由出版行政主管部门责令停止违法行为，予以警告，并处3万元以下罚款： （一）擅自调换已选定的中小学教科书的； （二）擅自征订、搭售教学用书目录以外的出版物的； （三）擅自将中小学教科书发行任务向他人转让和分包的； （四）涂改、倒卖、出租、出借中小学教科书发行资质证书的； （五）未在规定时间内完成中小学教科书发行任务的； （六）违反国家有关规定收取中小学教科书发行费用的； （七）未按规定做好中小学教科书的调剂、添货、零售和售后服务的； （八）未按规定报告中小学教科书发行情况的； （九）出版单位向不具备中小学教科书发行资质的单位供应中小学教科书的； （十）出版单位未在规定时间内向依法确定的中小学教科书发行企业足量供货的； （十一）在中小学教科书发行过程中出现重大失误，或者存在其他干扰中小学教科书发行活动行为的。"},{"i":39,"n":"第三十九条","txt":"征订、储存、运输、邮寄、投递、散发、附送本规定第二十条所列出版物的，按照本规定第三十二条进行处罚。"},{"i":40,"n":"第四十条","txt":"未按本规定第三十条报送统计资料的，按照《新闻出版统计管理办法》有关规定处理。"},{"i":41,"n":"第四十一条","txt":"允许香港、澳门永久性居民中的中国公民依照内地有关法律、法规和行政规章，在内地各省、自治区、直辖市设立从事出版物零售业务的个体工商户，无需经过外资审批。"},{"i":42,"n":"第四十二条","txt":"本规定所称中小学教科书，是指经国务院教育行政主管部门审定和经授权审定的义务教育教学用书（含配套教学图册、音像材料等）。 中小学教科书发行包括中小学教科书的征订、储备、配送、分发、调剂、添货、零售、结算及售后服务等。"},{"i":43,"n":"第四十三条","txt":"出版物经营许可证和中小学教科书发行资质证的设计、印刷、制作与发放等，按照《新闻出版许可证管理办法》有关规定执行。"},{"i":44,"n":"第四十四条","txt":"本规定由国家新闻出版广电总局会同商务部负责解释。"},{"i":45,"n":"第四十五条","txt":"本规定自2016年6月1日起施行，原新闻出版总署、商务部2011年3月25日发布的《出版物市场管理规定》同时废止。本规定施行前与本规定不一致的其他规定不再执行。"}],"chubanwujinkoubeianguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范出版物进口备案行为，加强出版物进口管理，根据《出版管理条例》《音像制品管理条例》等法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事出版物进口活动，适用本办法。 本办法所称出版物，是指进口的图书、报纸、期刊、音像制品（成品）及电子出版物（成品）、数字文献数据库等。 本办法所称出版物进口经营单位，是指依照《出版管理条例》设立的从事出版物进口业务的单位。"},{"i":3,"n":"第三条","txt":"出版物进口经营单位应当按照许可的业务范围从事出版物进口经营活动。"},{"i":4,"n":"第四条","txt":"出版物进口经营单位应当按照《出版管理条例》及本办法的要求，向省级以上出版行政主管部门办理进口出版物备案手续。出版物进口经营单位提供备案材料不齐备或不真实的，不予备案。 负责备案的省、自治区、直辖市出版行政主管部门应将相关备案信息报国家新闻出版广电总局。国家新闻出版广电总局对省、自治区、直辖市出版行政主管部门的备案工作进行检查指导。"},{"i":5,"n":"第五条","txt":"进口图书的，出版物进口经营单位应当于进口前向省级以上出版行政主管部门申请办理进口备案手续。申请备案时，需提交备案申请和出版物进口经营单位出具的审查意见，备案申请包括以下信息： （一）图书名称； （二）出版机构； （三）进口来源国家（地区）； （四）作者； （五）国际标准出版代码（ISBN)； （六）语种； （七）数量； （八）类别； （九）进口口岸； （十）订购方； （十一）需要提交的其他材料。"},{"i":6,"n":"第六条","txt":"省级以上出版行政主管部门在受理出版物进口经营单位进口图书备案申请材料之日起20个工作日内完成图书目录的备案手续。准予备案的，负责备案的出版行政主管部门为出版物进口经营单位出具通关函。出版物进口经营单位应当向海关交验通关函，海关按规定办理报关验放手续，没有通关函海关不予放行。"},{"i":7,"n":"第七条","txt":"进口音像制品（成品）及电子出版物（成品）的，出版物进口经营单位应当按照《音像制品进口管理办法》《电子出版物出版管理规定》的要求，履行相应进口审批手续。出版物进口经营单位应当向海关交验批准文件，海关按规定办理报关验放手续，没有批准文件海关不予放行。"},{"i":8,"n":"第八条","txt":"出版物进口经营单位进口音像制品（成品）及电子出版物（成品）后15个工作日内报国家新闻出版广电总局备案。报送备案时，需按音像制品（成品）及电子出版物（成品）的实际进口情况提交以下信息： （一）名称； （二）出版机构； （三）进口来源国家（地区）； （四）国际标准音像制品编码（ISRC）或电子出版物编码等； （五）语种； （六）数量； （七）类别； （八）进口口岸； （九）载体形式； （十）进口通关放行日期； （十一）进口批准文号； （十二）订购方； （十三）需要提交的其他材料。"},{"i":9,"n":"第九条","txt":"进口后的音像制品（成品）及电子出版物（成品）的使用，应当符合其他法律法规等相关规定。"},{"i":10,"n":"第十条","txt":"进口报纸、期刊的，出版物进口经营单位应当按照《订户订购进口出版物管理办法》的要求，履行相应进口审批手续。出版物进口经营单位应当向海关交验批准文件，海关按规定办理报关验放手续，没有批准文件海关不予放行。"},{"i":11,"n":"第十一条","txt":"出版物进口经营单位进口报纸、期刊后，每季度报国家新闻出版广电总局备案，同时抄送所在地省、自治区、直辖市出版行政主管部门。报送备案时，需按照实际进口情况提交以下信息： （一）报刊名称； （二）出版机构； （三）进口来源国家（地区）； （四）国际标准连续出版物号（ISSN）； （五）语种； （六）数量； （七）类别； （八）进口口岸； （九）刊期； （十）进口通关放行日期； （十一）订户； （十二）需要提交的其他材料。"},{"i":12,"n":"第十二条","txt":"通过信息网络进口到境内的境外数字文献数据库，必须由国务院出版行政主管部门批准的有境外数字文献数据库网络进口资质的出版物进口经营单位进口。出版物进口经营单位办理境外数字文献数据库进口时，应当严格按照《出版管理条例》《音像制品管理条例》《订户订购进口出版物管理办法》等法规规章及相关规定，对其进口的境外数字文献数据库进行内容审查（含进口前内容审查和进口后更新内容审查），分类办理数字文献数据库进口备案、审批手续。"},{"i":13,"n":"第十三条","txt":"出版物进口经营单位进口境外数字文献数据库后，于每个自然年年末报国家新闻出版广电总局备案。报送备案时，需按境外数字文献数据库实际进口信息提供以下材料： （一）名称； （二）境外供应商； （三）进口来源国家（地区）； （四）语种； （五）用户数量； （六）类别； （七）开通时间； （八）当前合同起止年月； （九）进口金额； （十）国内订购单位； （十一）动态监管人员； （十二）监管设施的IP地址； （十三）监管方式； （十四）需要提交的其他材料。"},{"i":14,"n":"第十四条","txt":"出版物进口经营单位应当对实际进口出版物进行内容审查并每月定期向国家新闻出版广电总局提交审读报告。"},{"i":15,"n":"第十五条","txt":"出版物进口经营单位未按本办法要求履行备案手续的，根据《出版管理条例》第六十七条的规定，由省级以上出版行政主管部门责令改正，给予警告；情节严重的，责令限期停业整顿或者由原发证机关吊销许可证。"},{"i":16,"n":"第十六条","txt":"出版物进口经营单位未履行审读责任，进口含有《出版管理条例》第二十五条、第二十六条禁止内容的，根据《出版管理条例》第六十二条的规定，由省级以上出版行政主管部门责令停止违法行为，没收出版物、违法所得，违法经营额1万元以上的，并处违法经营额5倍以上10倍以下的罚款；违法经营额不足1万元的，可以处5万元以下的罚款；情节严重的，责令限期停业整顿或者由原发证机关吊销许可证。"},{"i":17,"n":"第十七条","txt":"出版物进口经营单位备案时提交的材料不齐备、不真实或违反本办法其他规定的，由省级以上出版行政主管部门责令停止进口行为，并给予警告；情节严重的，处3万元以下罚款。"},{"i":18,"n":"第十八条","txt":"本办法由国家新闻出版广电总局会同海关总署负责解释。"},{"i":19,"n":"第十九条","txt":"本办法自2017年3月1日起施行。"}],"chubanguanlixingzhengchufashishibanfa":[{"i":1,"n":"第一条","txt":"为了规范出版管理行政处罚，保障和监督新闻出版行政机关有效实施行政管理，保护公民、法人或者其他组织的合法权益，根据《中华人民共和国行政处罚法》和《出版管理条例》等有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织违反出版管理法规，应当给予行政处罚的，由新闻出版行政机关依照《中华人民共和国行政处罚法》和本办法的规定实施。"},{"i":3,"n":"第三条","txt":"新闻出版行政机关实施行政处罚应当遵循下列原则： （一）必须有法定依据，遵守法定程序，否则行政处罚无效； （二）必须以事实为依据，与违法行为的事实、性质、情节以及社会危害程度相当，违法事实不清的，不得给予行政处罚； （三）对违法行为给予行政处罚的规定必须公布，未经公布的不得作为行政处罚的依据； （四）应当坚持处罚与教育相结合，教育公民、法人或者其他组织自觉守法； （五）在作出行政处罚决定之前，应当向当事人告知给予行政处罚的事实、理由和依据，听取当事人的陈述、申辩，否则行政处罚决定不能成立。"},{"i":4,"n":"第四条","txt":"新闻出版行政机关在法定职权范围内负责对下列违法行为实施行政处罚： （一）《出版管理条例》规定的违法行为； （二）《音像制品管理条例》规定的违法行为； （三）《印刷业管理条例》规定的违法行为； （四）其他有关法律、法规和规章规定的应当由新闻出版行政机关给予行政处罚的违法行为。"},{"i":5,"n":"第五条","txt":"本办法所称新闻出版行政机关是指新闻出版署，省、自治区、直辖市新闻出版局，计划单列市新闻出版局，地市级和县级新闻出版局，或者省、自治区、直辖市人民政府规定的行使新闻出版行政管理职能的行政机关。 法律、法规授权的具有新闻出版管理职能的组织实施出版管理行政处罚，适用本办法。"},{"i":6,"n":"第六条","txt":"新闻出版署负责对下列违法行为实施行政处罚： （一）在全国有重大影响的； （二）法律、法规规定由新闻出版署管辖的； （三）其他应当由自己管辖的。"},{"i":7,"n":"第七条","txt":"省、自治区、直辖市新闻出版局负责对下列违法行为实施行政处罚： （一）在本行政区有重大影响的； （二）涉及外国的； （三）其他依法应当由自己管辖的。 其他地方新闻出版行政机关负责对本行政区域发生的违法行为实施行政处罚。省、自治区、直辖市制定的地方性法规、规章有具体规定的，从其规定。"},{"i":8,"n":"第八条","txt":"行政处罚由主要违法行为发生地的新闻出版行政机关管辖。两个以上地方新闻出版行政机关对同一违法行为都有管辖权的，由先立案的新闻出版行政机关管辖。"},{"i":9,"n":"第九条","txt":"地方新闻出版行政机关就行政处罚管辖发生争议或者管辖不明的，报请共同的上一级新闻出版行政机关指定管辖。该上一级新闻出版行政机关应当指定其中一个地方新闻出版行政机关管辖，或者指定适宜的其他地方新闻出版行政机关管辖。"},{"i":10,"n":"第十条","txt":"上级新闻出版行政机关在必要的时候可以处理下级新闻出版行政机关管辖的行政处罚案件，也可以把自己管辖的行政处罚案件交下级新闻出版行政机关处理。 下级新闻出版行政机关认为其管辖的行政处罚案件重大、复杂，需要由上级新闻出版行政机关处理的，可以报请上一级新闻出版行政机关决定。"},{"i":11,"n":"第十一条","txt":"对出版单位的行政处罚，由新闻出版署或者省级新闻出版行政机关管辖；新闻出版署、省级新闻出版行政机关认为由出版单位所在地的新闻出版行政机关管辖更适宜的，可以指定该地的新闻出版行政机关管辖。"},{"i":12,"n":"第十二条","txt":"吊销许可证的处罚，由原发证机关决定。"},{"i":13,"n":"第十三条","txt":"新闻出版行政机关认为违法行为构成犯罪的，必须将案件移送司法机关。"},{"i":14,"n":"第十四条","txt":"有关著作权的违法行为，由著作权行政管理部门依照有关规定处理。"},{"i":15,"n":"第十五条","txt":"除依照《中华人民共和国行政处罚法》可以当场作出行政处罚决定的以外，新闻出版行政机关发现公民、法人或者其他组织有依法应当给予行政处罚的违法行为的，应当立案查处。"},{"i":16,"n":"第十六条","txt":"新闻出版行政机关应当严格履行职责，对有关公民、法人或者其他组织遵守出版法律、法规和规章的情况进行监督检查。对在检查中发现的违法行为，新闻出版行政机关应当及时立案。 新闻出版行政机关在进行执法检查时，执法人员不得少于两人，并应当向当事人或者有关人员出示新闻出版行政执法证。"},{"i":17,"n":"第十七条","txt":"新闻出版行政机关在执法检查中，发现正在印刷、复制、批发、零售、出租违禁出版物或者非法出版物，情况紧急来不及立案的，执法人员可以采取以下措施： （一）对违法行为予以制止或者纠正； （二）对违禁出版物或者非法出版物、专用于违法行为的工具、设备依法查封或扣押； （三）收集、提取有关证据。"},{"i":18,"n":"第十八条","txt":"新闻出版行政机关应当建立健全违法行为举报制度，接受公民、法人或者其他组织对违法行为的控告、检举。对控告、检举的违法行为经审核基本属实的，应当及时立案。不予立案的，应当及时告知控告人或检举人。"},{"i":19,"n":"第十九条","txt":"新闻出版行政机关对其他行政机关移送的、上级新闻出版行政机关指定或者交办的、当事人主动交待的和通过其他方式发现的违法行为，应当及时立案。"},{"i":20,"n":"第二十条","txt":"行政处罚案件的具体立案工作由新闻出版行政机关的相关职能部门负责。 立案应当制作出版管理行政处罚案件立案审批表，报本机关负责人审查，决定立案或者不予立案。 立案应当自发现或者受理案件之日起七日内完成。情况紧急来不及立案的，应当在调查取证或者依法采取有关行政措施后及时立案。"},{"i":21,"n":"第二十一条","txt":"行政处罚案件立案后，新闻出版行政机关应当及时进行调查取证。 调查取证必须全面、客观、公正，以收集确凿证据，查明违法事实。"},{"i":22,"n":"第二十二条","txt":"调查取证由新闻出版行政机关立案的职能部门或者新闻出版行政机关所属的稽查部门负责。 调查取证时执法人员不得少于两人，并向当事人或有关人员出示有效证件。执法人员与当事人有直接利害关系的，应当回避。"},{"i":23,"n":"第二十三条","txt":"进行调查取证可以采取以下手段： （一）询问当事人、证人、利害关系人等有关人员； （二）查阅、复制与违法行为有关的文件、档案、账簿和其他书面材料； （三）对违法出版物或者其他违法物品抽样取证； （四）对证据先行登记保存； （五）自行或委托其他组织对证据进行鉴定； （六）对与违法行为有关的场所、设备进行勘验、检查。"},{"i":24,"n":"第二十四条","txt":"执法人员进行调查取证应制作询问笔录、勘验或检查等调查笔录，笔录由当事人或有关人员签名或盖章，当事人拒绝签名或盖章的，由执法人员在笔录上注明情况。"},{"i":25,"n":"第二十五条","txt":"进行抽样取证、先行登记保存和勘验、检查，应当有当事人在场，当事人拒绝到场的，执法人员应当邀请有关人员参加见证。执法人员应当在调查笔录上注明情况，并由参加见证的有关人员签名或者盖章。"},{"i":26,"n":"第二十六条","txt":"执法人员对抽样取证、先行登记保存的物品应当开列清单，一式两份，写明物品的名称、数量、规格等项目，由执法人员、当事人签字或者盖章，一份清单交付当事人。当事人拒绝签名或者盖章和接收清单的，由执法人员在清单上注明情况。"},{"i":27,"n":"第二十七条","txt":"在证据可能灭失或者以后难以取得的情况下采取先行登记保存，应当经过本机关负责人批准，并向当事人出具证据先行登记保存通知书，责令当事人或者有关人员在证据保存期间不得转移、毁坏。认为先行登记保存的证据确需移至他处的，可以移至适当的场所保存。 情况紧急来不及办理上款规定程序的，执法人员可以先行采取措施，事后及时补办手续。"},{"i":28,"n":"第二十八条","txt":"新闻出版行政机关对先行登记保存的证据，应当在七日内作出以下处理决定： （一）需要进行检验或者鉴定的，予以检验或者鉴定； （二）对依法应予没收的，予以没收，对依法不予没收的，退还当事人； （三）对依法应当移送有关机关处理的，移交有关机关。 在七日内未作出处理决定的，应当解除保存，并将先行登记保存的证据退还当事人。"},{"i":29,"n":"第二十九条","txt":"非法出版物的鉴定由省级以上新闻出版行政机关指定的鉴定机关和鉴定人员作出，违禁出版物的鉴定由省级以上新闻出版行政机关作出。鉴定书由两名以上鉴定人签名，经机关负责人审核后签发，加盖新闻出版行政机关出版物鉴定专用章。 鉴定中遇有复杂、疑难问题或者鉴定结论有分歧，或者应当事人申请要求重新鉴定的，可以报请上级新闻出版行政机关鉴定。"},{"i":30,"n":"第三十条","txt":"新闻出版行政机关在调查取证有困难的情况下，可以委托其他新闻出版行政机关就某些事项代为调查取证，受委托的新闻出版行政机关应当积极办理，及时将调查取证结果回复委托的机关。 上级新闻出版行政机关对已经立案的案件可以指示下级新闻出版行政机关调查取证。"},{"i":31,"n":"第三十一条","txt":"新闻出版行政机关作出责令停产停业、责令停业整顿、吊销许可证和较大数额罚款等行政处罚决定之前，调查取证部门应当告知当事人有要求听证的权利。 本条所称“较大数额罚款”，由新闻出版署作出处罚决定的，是指对公民2万元以上、对法人或者其他组织10万元以上的罚款；由地方新闻出版行政机关作出处罚决定的，按照地方性法规、规章的规定办理，地方性法规、规章未作规定的，是指对公民1万元以上、对法人或者其他组织5万元以上的罚款。"},{"i":32,"n":"第三十二条","txt":"当事人要求举行听证的，应当在被告知后3日内提出书面申请，说明听证要求和理由。当事人提出书面申请有困难的，可以口头提出申请，调查取证部门应当制作笔录，并由当事人签名或盖章， 当事人在被告知后3日内未提出听证申请的，视为放弃听证要求，由调查取证部门记录在案。"},{"i":33,"n":"第三十三条","txt":"新闻出版行政机关应当从本机关法制工作部门或者其他比较超脱的相关职能部门中指定一名听证主持人、一名书记员。调查取证部门的人员不得作为听证主持人和书记员。"},{"i":34,"n":"第三十四条","txt":"新闻出版行政机关决定举行听证的，应当制作听证通知书，并在听证七日前，将举行听证的时间、地点通知当事人和本案调查人员。"},{"i":35,"n":"第三十五条","txt":"当事人可以亲自参加听证，也可以委托一至二人代理。委托代理人申请和参加听证的，应当提交委托书，委托书应当载明委托权限。"},{"i":36,"n":"第三十六条","txt":"当事人接到听证通知书后，无正当理由不按期参加听证的，视为放弃听证要求。 有下列情况之一的，听证可以延期举行： （一）当事人有正当理由未到场的； （二）当事人提出回避申请理由成立，需要重新确定主持人的； （三）发现有新的重要事实需要重新调查核实的； （四）其他需要延期的情形。"},{"i":37,"n":"第三十七条","txt":"在听证举行过程中，当事人放弃申辩或者退出听证的，终止听证，并记入听证笔录。"},{"i":38,"n":"第三十八条","txt":"听证主持人履行以下职责： （一）决定举行听证的时间和地点； （二）主持进行听证程序； （三）维持听证秩序； （四）决定终止听证； （五）决定听证延期举行； （六）根据听证情况向机关负责人写出报告并就案件的处理提出意见。 听证书记员如实记录听证情况，制作听证笔录，协助听证主持人工作。"},{"i":39,"n":"第三十九条","txt":"当事人认为主持人、书记员与本案有利害关系的，有权申请回避。书记员的回避，由主持人决定；主持人的回避，由其所在部门负责人决定。"},{"i":40,"n":"第四十条","txt":"听证应当按照以下程序进行： （一）听证会开始，介绍主持人、书记员，宣布听证纪律； （二）告知当事人听证中的权利和义务，询问是否有回避申请； （三）核对参加听证的当事人及代理人、本案调查人员、本案直接利害关系人、证人的身份； （四）本案调查人员说明案件事实、证据、适用的法律、法规或者规章，以及拟作出的行政处罚决定的理由； （五）询问当事人或者代理人、本案调查人员、证人和其他有关人员，并要求出示有关证据材料； （六）当事人或者代理人从事实和法律上进行申辩，并对证据材料进行质证； （七）当事人或者其代理人和本案调查人员就本案的事实和法律问题进行辩论； （八）当事人或者其代理人作最后陈述； （九）听证主持人宣布听证会结束。"},{"i":41,"n":"第四十一条","txt":"听证结束，当事人或者其代理人应当将申辩材料及有关证据提交听证主持人。"},{"i":42,"n":"第四十二条","txt":"听证笔录应当在听证后交双方人员审核，经确认无误后，由双方人员在听证笔录上签名。双方人员拒绝签名的，由书记员在笔录上记明。"},{"i":43,"n":"第四十三条","txt":"听证主持人应当根据听证确定的事实、证据，依照本办法第四十五条的规定对原拟作出的处罚决定及其事实、理由和依据加以复核，向本机关负责人提出意见。"},{"i":44,"n":"第四十四条","txt":"违法行为经调查事实清楚、证据确凿的，调查人员应当制作出版管理行政处罚意见书，载明违法事实、理由、法律依据、处罚意见及立案、调查取证情况。 调查人员应当依照《中华人民共和国行政处罚法》第三十一、三十二条的规定，听取当事人的陈述和申辩。 调查人员应当将出版管理行政处罚意见书和当事人的陈述、申辩材料，连同立案审批表和其他有关证据材料，经本部门负责人同意，送本机关法制工作部门复核。 经过听证的案件，按照本办法第四十三条的规定办理。"},{"i":45,"n":"第四十五条","txt":"法制工作部门对出版管理行政处罚意见书等书面材料就以下事项进行复核，签署意见后报本机关负责人审批： （一）认定事实是否清楚； （二）适用法律是否正确； （三）处罚意见是否合法、适当； （四）是否符合法定程序； （五）其他有关事项。"},{"i":46,"n":"第四十六条","txt":"新闻出版行政机关负责人对报送的出版管理行政处罚意见书等材料进行审查，根据不同情况分别作出以下决定： （一）确有应受行政处罚的违法行为，根据情节轻重及具体情况，作出行政处罚决定； （二）违法事实不能成立的和违法行为轻微依法可以不予行政处罚的，不予行政处罚； （三）认为违法行为构成犯罪的，移送司法机关； （四）认为应当吊销营业执照或者其他许可证的，向工商行政管理机关或者公安机关提出建议； （五）认为应当给予当事人或受处罚单位主要负责人行政处分的，向其所在单位或其主管部门提出建议。 经过听证的和其他较重大的行政处罚，由新闻出版行政机关负责人集体讨论决定。"},{"i":47,"n":"第四十七条","txt":"新闻出版行政机关决定给予行政处罚的，应当制作出版管理行政处罚决定书，载明《中华人民共和国行政处罚法》第三十九条和国务院《罚款决定与罚款收缴分离实施办法》第七条规定的事项。 新闻出版行政机关决定不给予行政处罚的，应当制作不予行政处罚通知书，说明不予行政处罚的理由，送达当事人。 新闻出版行政机关决定移送司法机关处理的案件，应当制作建议追究刑事责任意见书，连同有关材料和证据及时移送有管辖权的司法机关。 新闻出版行政机关向工商行政管理机关或者公安机关建议吊销当事人营业执照或者其他许可证的，应当制作建议吊销营业执照或者其他许可证意见书。 新闻出版行政机关建议给予当事人或者其他有关人员行政处分的，应当制作建议给予行政处分意见书，送达当事人或者其他人员所在单位或其主管机关。 本条各款所列法律文书，由调查部门负责制作并送达。"},{"i":48,"n":"第四十八条","txt":"对同一违法行为，其他行政机关已经给予罚款处罚的，新闻出版行政机关不得再予罚款，但仍可以依法给予其他种类的行政处罚。"},{"i":49,"n":"第四十九条","txt":"给予停业整顿行政处罚的，应当明确停业的时限和整顿的事项。"},{"i":50,"n":"第五十条","txt":"新闻出版行政机关对违法行为的行政处罚决定，应当自立案之日起两个月内作出；案件重大、复杂的，经本机关负责人决定，可以延长，但延长的时间最多不得超过两个月。 作出行政处罚决定的日期以行政处罚决定书上的日期为准。"},{"i":51,"n":"第五十一条","txt":"行政处罚决定书应当在宣告后当场交付当事人；当事人不在场的，新闻出版行政机关应当在作出行政处罚决定的七日内依照民事诉讼法的有关规定，将行政处罚决定书送达当事人。"},{"i":52,"n":"第五十二条","txt":"新闻出版行政机关作出的行政处罚决定，可以在有关范围内予以通报或者在报纸、期刊等媒介上公布。"},{"i":53,"n":"第五十三条","txt":"罚款的收缴依照国务院《罚款决定与罚款收缴分离实施办法》执行。"},{"i":54,"n":"第五十四条","txt":"没收的出版物需要销毁的，纸质出版物应当化浆，其他出版物应当以适宜的方式销毁。新闻出版行政机关应当指派专人负责销毁事宜，监督销毁过程，核查销毁结果，防止应当销毁的出版物流失。 没收的出版物不需要销毁的，新闻出版行政机关应当报请上一级新闻出版行政机关决定处理的方式。"},{"i":55,"n":"第五十五条","txt":"对没收的从事非法活动的主要专用工具和设备，新闻出版行政机关依照有关规定处理。"},{"i":56,"n":"第五十六条","txt":"对于给予停业整顿行政处罚的，新闻出版行政机关应当对当事人停业期间的整顿情况进行监督，并在停业期满前进行检查验收，对整顿符合要求的，根据当事人的申请，恢复其业务。"},{"i":57,"n":"第五十七条","txt":"上一级新闻出版行政机关作出的行政处罚决定，可以指示下一级新闻出版行政机关执行。"},{"i":58,"n":"第五十八条","txt":"新闻出版行政机关实施行政处罚时，可以采取下列措施纠正违法行为： （一）对未经批准擅自设立的出版、印刷、复制、发行单位予以公告取缔； （二）责令停止出版、印刷、复制、发行出版物； （三）其他责令当事人纠正违法行为的措施。"},{"i":59,"n":"第五十九条","txt":"当事人逾期不履行行政处罚决定的，新闻出版行政机关可以依照《中华人民共和国行政处罚法》规定的措施处理。 新闻出版行政机关申请人民法院强制执行行政处罚决定，应当自当事人起诉期限届满之日起三个月内提出。"},{"i":60,"n":"第六十条","txt":"当事人申请行政复议或提起行政诉讼期间，行政处罚决定不停止执行，法律、法规另有规定的除外。"},{"i":61,"n":"第六十一条","txt":"出版管理行政处罚案件终结后，调查人员应当将案件材料立卷归档。"},{"i":62,"n":"第六十二条","txt":"新闻出版行政机关应当建立行政处罚统计制度和重大行政处罚备案制度，每半年向上一级新闻出版行政机关提交一次行政处罚统计报告，重大行政处罚报上一级新闻出版行政机关备案。"},{"i":63,"n":"第六十三条","txt":"新闻出版行政机关的法制工作部门负责对本机关实施行政处罚进行监督，负责办理本办法第六十二条规定的事项。"},{"i":64,"n":"第六十四条","txt":"新闻出版行政执法证由新闻出版署统一制作，具体管理办法另行制定。 新闻出版行政执法证未颁发之前，适用当地人民政府颁发的执法证或者其他有效证件。"},{"i":65,"n":"第六十五条","txt":"本办法所称非法出版物，是指违反《出版管理条例》未经批准擅自出版的出版物，伪造、假冒出版单位或者报纸、期刊名称出版的出版物，擅自印刷或者复制的境外出版物，非法进口的出版物。 本办法所称违禁出版物，是指内容违反《出版管理条例》第二十五条、第二十六条规定的出版物。"},{"i":66,"n":"第六十六条","txt":"本办法自1998年1月1日起施行。"}],"yinshuayejingyingzhezigetiaojianzanxingguiding":[{"i":1,"n":"第一条","txt":"为了进一步规范印刷业经营者的设立和审批，促进印刷业经营者提高经营素质和技术水平，根据《印刷业管理条例》的规定和国务院有关整顿和规范印刷市场秩序的精神，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称印刷业经营者，包括从事出版物、包装装潢印刷品印刷经营活动的企业，从事其他印刷品印刷经营活动的企业、单位或者个人，以及专项排版、制版、装订企业或者单位。"},{"i":3,"n":"第三条","txt":"印刷业经营者资格的审批，除应符合本规定外，还应当符合国家有关印刷业总量、结构、布局规划和法律、法规规定的其他条件。"},{"i":4,"n":"第四条","txt":"经营出版物印刷业务的企业，应当具备以下条件： （一）有企业的名称、章程； （二）有确定的业务范围； （三）有适应业务需要的固定生产经营场所； （四）有能够维持正常生产经营的资金； （五）有必要的出版物印刷设备，具备2台以上最近十年生产的且未列入《淘汰落后生产能力、工艺和产品的目录》的自动对开胶印印刷设备； （六）有适应业务范围需要的组织机构和人员，法定代表人及主要生产、经营负责人必须取得省级新闻出版行政部门颁发的《印刷法规培训合格证书》； （七）有健全的承印验证、登记、保管、交付、销毁等经营管理、财务管理制度和质量保证体系。"},{"i":5,"n":"第五条","txt":"经营包装装潢印刷品印刷业务的企业，应当具备以下条件： （一）有企业的名称、章程； （二）有确定的业务范围； （三）有适应业务需要的固定生产经营场所； （四）有能够维持正常生产经营的资金； （五）有必要的包装装潢印刷设备，具备2台以上最近十年生产的且未列入《淘汰落后生产能力、工艺和产品的目录》的胶印、凹印、柔印、丝印等及后序加工设备； （六）有适应业务范围需要的组织机构和人员，企业法定代表人及主要生产、经营负责人必须取得地市级以上人民政府负责出版管理的行政部门（以下简称出版行政部门）颁发的《印刷法规培训合格证书》； （七）有健全的承印验证、登记、保管、交付、销毁等经营管理、财务管理制度和质量保证体系。"},{"i":6,"n":"第六条","txt":"经营其他印刷品印刷业务的企业、单位，应当具备以下条件： （一）有企业或单位的名称、章程； （二）有确定的业务范围； （三）有适应业务需要的固定生产经营场所，且不在有居住用途的场所内； （四）有适应业务需要的生产设备和资金； （五）有适应业务需要的组织机构和人员，企业法定代表人或单位负责人必须取得县级以上出版行政部门颁发的《印刷法规培训合格证书》； （六）有健全的承印验证、登记、保管、交付、销毁等经营管理、财务管理制度和质量保证体系。"},{"i":7,"n":"第七条","txt":"经营专项排版、制版、装订业务的企业、单位，应当具备以下条件： （一）有企业或单位的名称、章程； （二）有确定的业务范围； （三）有适应业务需要的固定生产经营场所； （四）有能够维持正常生产经营的资金； （五）有必要的排版、制版、装订设备，具备2台以上最近十年生产的且未列入《淘汰落后生产能力、工艺和产品的目录》的印前或印后加工设备； （六）有适应业务范围需要的组织机构和人员，企业法定代表人及主要生产、经营负责人和单位负责人必须取得地市级以上出版行政部门颁发的《印刷法规培训合格证书》； （七）有健全的承印验证、登记、保管、交付、销毁等经营管理、财务管理制度和质量保证体系。"},{"i":8,"n":"第八条","txt":"个人从事其他印刷品印刷经营活动的，应当符合本规定第六条的规定。"},{"i":9,"n":"第九条","txt":"印刷业经营者从事其他种类印刷经营活动的，应当同时具备设立该印刷企业或者单位的资格条件。"},{"i":10,"n":"第十条","txt":"出版行政部门必须按照本规定审批印刷业经营者资格，不符合本规定条件的不得批准设立。"},{"i":11,"n":"第十一条","txt":"对印刷业经营者的年度核验，除适用本规定规定的条件外，还要求印刷业经营者无违反印刷管理规定的记录。"},{"i":12,"n":"第十二条","txt":"本规定施行前已设立的印刷业经营者于2002年3月1日前未达到本规定规定条件的，暂不予换发《印刷经营许可证》。"},{"i":13,"n":"第十三条","txt":"本规定自发布之日起施行。"}],"yinshuapinchengyinguanliguiding":[{"i":1,"n":"第一条","txt":"为了规范印刷业经营者的印刷经营行为，健全承接印刷品管理制度，促进印刷业健康发展，根据《印刷业管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"印刷业经营者从事印刷经营活动，应当建立、健全承印验证制度、承印登记制度、印刷品保管制度、印刷品交付制度、印刷活动残次品销毁制度等管理制度。"},{"i":3,"n":"第三条","txt":"印刷业经营者执行承印验证、承印登记、印刷品保管、印刷品交付、印刷活动残次品销毁等各项管理制度，应当指定专人负责，严格把关，建档立卷，以备查验。"},{"i":4,"n":"第四条","txt":"印刷业经营者法定代表人或者主要负责人负责本企业、本单位各项管理制度的组织实施。"},{"i":5,"n":"第五条","txt":"县级以上地方人民政府负责出版管理的行政部门（以下简称出版行政部门）、公安部门指导本行政区域内印刷业经营者建立各项管理制度，并负责监督检查印刷业经营者各项管理制度的实施情况。"},{"i":6,"n":"第六条","txt":"印刷业经营者在印刷经营活动中发现违法犯罪行为，应当及时向所在地公安部门、出版行政部门报告。"},{"i":7,"n":"第七条","txt":"印刷业经营者接受委托印刷各种印刷品时，应当依照《印刷业管理条例》等法规、规章的规定，验证委印单位及委印人的证明文件，并收存相应的复印件备查。 前款所指的证明文件包括印刷委托书或者委托印刷证明、准印证、《出版许可证》、《商标注册证》、注册商标图样、注册商标使用许可合同、广告经营资格证明、营业执照以及委印人的资格证明等。"},{"i":8,"n":"第八条","txt":"印刷企业接受委托印刷图书、期刊的，必须验证并收存由国务院出版行政部门统一格式，由省、自治区、直辖市人民政府出版行政部门统一印制并加盖出版单位公章的《图书、期刊印刷委托书》原件。 《图书、期刊印刷委托书》必须加盖出版单位所在地省、自治区、直辖市人民政府出版行政部门和印刷企业所在地省、自治区、直辖市人民政府出版行政部门的备案专用章。"},{"i":9,"n":"第九条","txt":"印刷企业接受委托印刷报纸的，必须验证由国务院出版行政部门统一制作，由省、自治区、直辖市人民政府出版行政部门核发的《报纸出版许可证》，并收存《报纸出版许可证》复印件。 印刷企业接受委托印刷报纸、期刊的增版、增刊的，还必须验证并收存国务院出版行政部门批准出版增版、增刊的文件。"},{"i":10,"n":"第十条","txt":"出版单位委托印刷出版物的排版、制版、印刷（包括重印、加印）、装订各工序不在同一印刷企业的，必须分别向各接受委托印刷企业开具《图书、期刊印刷委托书》。"},{"i":11,"n":"第十一条","txt":"印刷企业接受委托印刷内部资料性出版物的，必须验证并收存由省、自治区、直辖市人民政府出版行政部门统一印制，并由县级以上地方人民政府出版行政部门核发的《内部资料性出版物准印证》。 印刷企业接受委托印刷宗教内容的内部资料性出版物的，必须验证并收存由省、自治区、直辖市人民政府宗教事务管理部门的批准文件和出版行政部门核发的《内部资料性出版物准印证》。"},{"i":12,"n":"第十二条","txt":"印刷企业接受委托印刷境外出版物的，必须验证并收存省、自治区、直辖市人民政府出版行政部门的批准文件和有关著作权的合法证明文件；印刷的境外出版物必须全部运输出境，不得在境内发行、散发。"},{"i":13,"n":"第十三条","txt":"印刷企业接受委托印刷注册商标标识的，必须验证《商标注册证》或者由商标注册人所在地县级工商行政管理部门签章的《商标注证》复印件，并核查委托人提供的注册商标图样；接受注册商标被许可使用人委托，印刷注册商标标识的，还必须验证注册商标使用许可合同。 印刷企业接受委托印刷广告宣传品、作为产品包装装潢的印刷品的，必须验证委托印刷单位的营业执照及个人的居民身份证；接受广告经营者的委托印刷广告宣传品的，还必须验证广告经营资格证明。"},{"i":14,"n":"第十四条","txt":"印刷企业接受委托印刷境外包装装潢印刷品和其他印刷品的，必须验证并收存委托方的委托印刷证明，并事先向所在地省、自治区、直辖市人民政府出版行政部门备案，经所在地省、自治区、直辖市人民政府出版行政部门加盖备案专用章后，方可承印；印刷的包装装潢印刷品和其他印刷品必须全部运输出境，不得在境内销售。"},{"i":15,"n":"第十五条","txt":"公安部门指定的印刷企业接受委托印刷布告、通告、重大活动工作证、通行证、在社会上流通使用的票证的，必须验证并收存委印单位主管部门的证明和公安部门核发的准印证明。 印刷企业接受委托印刷机关、团体、部队、企业事业单位内部使用的有价票证或者无价票证，印刷有单位名称的介绍信、工作证、会员证、出入证、学位证书、学历证书或者其他学业证书、机动车驾驶证、房屋权属证书等专用证件的，必须验证委印单位的委托印刷证明及个人的居民身份证，并收存委托印刷证明和身份证复印件。"},{"i":16,"n":"第十六条","txt":"印刷业经营者应当妥善留存验证的各种证明文件2年，以备出版行政部门、公安部门查验。 前款所称证明文件包括印刷委托书或者委托印刷证明原件、准印证原件、《出版许可证》复印件、《商标注册证》复印件、注册商标图样原件、注册商标使用许可合同复印件、广告经营资格证明复印件、营业执照复印件、居民身份证复印件等。"},{"i":17,"n":"第十七条","txt":"印刷业经营者应当按承印印刷品的种类在《出版物印刷登记簿》、《包装装潢印刷品印刷登记簿》、《其他印刷品印刷登记簿》、《专项排版、制版、装订业务登记簿》、《复印、打印业务登记簿》（以下统称为《印刷登记簿》）上登记委托印刷单位及委印人的名称、住址，经手人的姓名、身份证号码和联系电话，委托印刷的印刷品的名称、数量、印件原稿（或电子文档）、底片及交货日期、收货人等。 《印刷登记簿》一式三联，由省、自治区、直辖市人民政府出版行政部门或者其授权的地（市）级出版行政部门组织统一印制。"},{"i":18,"n":"第十八条","txt":"印刷业经营者应当在每月月底将《印刷登记簿》登记的内容报所在地县级以上出版行政部门备案。"},{"i":19,"n":"第十九条","txt":"印刷业经营者对承印印件的原稿（或电子文档）、校样、印板、底片、半成品、成品及印刷品的样本应当妥善保管，不得损毁。 印刷企业应当自完成出版物的印刷之日起2年内，保存一份接受委托印刷的出版物样本备查。"},{"i":20,"n":"第二十条","txt":"印刷企业印刷布告、通告、重大活动工作证、通行证、在社会上流通使用的票证，印刷机关、团体、部队、企业事业单位内部使用的有价或者无价票证，印刷有单位名称的介绍信、工作证、会员证、出入证、学位证书、学历证书或者其他学业证书、机动车驾驶证、房屋权属证书等专用证件，不得擅自留存样本、样张；确因业务参考需要保留样本、样张的，应当征得委托印刷单位同意，在所保留印件上加盖“样本”、“样张”戳记，并妥善保管，不得丢失。"},{"i":21,"n":"第二十一条","txt":"印刷业经营者在执行印刷品保管制度时，应当明确保管责任，健全保管制度，严格保管交接手续，做到数字准确，有据可查。"},{"i":22,"n":"第二十二条","txt":"印刷业经营者必须严格按照印刷委托书或者委托印刷证明规定的印数印刷，不得擅自加印。 印刷业经营者每完成一种印刷品的印刷业务后，应当认真清点印刷品数量，登记台账，并根据合同的规定将印刷成品、原稿(或电子文档)、底片、印板、校样等全部交付委托印刷单位或者个人，不得擅自留存。"},{"i":23,"n":"第二十三条","txt":"印刷业经营者应当建立印刷品承印档案，每完成一种印刷品的印刷业务后，应当将印刷合同、承印验证的各种证明文件及相应的复印件、发排单、付印单、样书、样本、样张等相关的资料一并归档留存。"},{"i":24,"n":"第二十四条","txt":"印刷业经营者对印刷活动中产生的残次品，应当按实际数量登记造册，对不能修复并履行交付的，应当予以销毁，并登记销毁印件名称、数量、时间、责任人等。其中，属于国家秘密载体或者特种印刷品的，应当根据国家有关规定及时销毁。"},{"i":25,"n":"第二十五条","txt":"印刷业经营者使用电子方法排版印制或者打印国家秘密载体的，应当严格按照有关法律、法规或者规章的规定办理。"},{"i":26,"n":"第二十六条","txt":"本规定自2003年9月1日起施行。"}],"tushuchubanguanliguiding":[{"i":1,"n":"第一条","txt":"为了规范图书出版，加强对图书出版的监督管理，促进图书出版的发展和繁荣，根据国务院《出版管理条例》及相关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事图书出版，适用本规定。 本规定所称图书，是指书籍、地图、年画、图片、画册，以及含有文字、图画内容的年历、月历、日历，以及由新闻出版总署认定的其他内容载体形式。"},{"i":3,"n":"第三条","txt":"图书出版必须坚持为人民服务、为社会主义服务的方向，坚持马克思列宁主义、毛泽东思想、邓小平理论和“三个代表”重要思想，坚持科学发展观，坚持正确的舆论导向和出版方向，坚持把社会效益放在首位、社会效益和经济效益相统一的原则，传播和积累有益于提高民族素质、推动经济发展、促进社会和谐与进步的科学技术和文化知识，弘扬民族优秀文化，促进国际文化交流，丰富人民群众的精神文化生活。"},{"i":4,"n":"第四条","txt":"新闻出版总署负责全国图书出版的监督管理工作，建立健全监督管理制度，制定并实施全国图书出版总量、结构、布局的规划。 省、自治区、直辖市新闻出版行政部门负责本行政区域内图书出版的监督管理工作。"},{"i":5,"n":"第五条","txt":"图书出版单位依法从事图书的编辑、出版等活动。 图书出版单位合法的出版活动受法律保护，任何组织和个人不得非法干扰、阻止、破坏。"},{"i":6,"n":"第六条","txt":"新闻出版总署对为发展、繁荣我国图书出版事业作出重要贡献的图书出版单位及个人给予奖励，并评选奖励优秀图书。"},{"i":7,"n":"第七条","txt":"图书出版行业的社会团体按照其章程，在新闻出版行政部门的指导下，实行自律管理。"},{"i":8,"n":"第八条","txt":"图书由依法设立的图书出版单位出版。设立图书出版单位须经新闻出版总署批准，取得图书出版许可证。 本规定所称图书出版单位，是指依照国家有关法规设立，经新闻出版总署批准并履行登记注册手续的图书出版法人实体。"},{"i":9,"n":"第九条","txt":"设立图书出版单位，应当具备下列条件： （一）有图书出版单位的名称、章程； （二）有符合新闻出版总署认定条件的主办单位、主管单位； （三）有确定的图书出版业务范围； （四）有30万元以上的注册资本； （五）有适应图书出版需要的组织机构和符合国家规定资格条件的编辑出版专业人员； （六）有确定的法定代表人或者主要负责人，该法定代表人或者主要负责人必须是在境内长久居住的具有完全行为能力的中国公民； （七）有与主办单位在同一省级行政区域的固定工作场所； （八）法律、行政法规规定的其他条件。 设立图书出版单位，除前款所列条件外，还应当符合国家关于图书出版单位总量、结构、布局的规划。"},{"i":10,"n":"第十条","txt":"中央在京单位设立图书出版单位，由主办单位提出申请，经主管单位审核同意后，由主办单位报新闻出版总署审批。 中国人民解放军和中国人民武装警察部队系统设立图书出版单位，由主办单位提出申请，经中国人民解放军总政治部宣传部新闻出版局审核同意后，报新闻出版总署审批。 其他单位设立图书出版单位，经主管单位审核同意后，由主办单位向所在地省、自治区、直辖市新闻出版行政部门提出申请，省、自治区、直辖市新闻出版行政部门审核同意后，报新闻出版总署审批。"},{"i":11,"n":"第十一条","txt":"申请设立图书出版单位，须提交以下材料： （一）按要求填写的设立图书出版单位申请表； （二）主管单位、主办单位的有关资质证明材料； （三）拟任图书出版单位法定代表人或者主要负责人简历、身份证明文件； （四）编辑出版人员的出版专业职业资格证书； （五）注册资本数额、来源及性质证明； （六）图书出版单位的章程； （七）工作场所使用证明； （八）设立图书出版单位的可行性论证报告。"},{"i":12,"n":"第十二条","txt":"新闻出版总署应当自收到设立图书出版单位申请之日起90日内，作出批准或者不批准的决定，并直接或者由省、自治区、直辖市新闻出版行政部门书面通知主办单位；不批准的，应当说明理由。"},{"i":13,"n":"第十三条","txt":"申请设立图书出版单位的主办单位应当自收到新闻出版总署批准文件之日起60日内办理如下注册登记手续： （一）持批准文件到所在地省、自治区、直辖市新闻出版行政部门领取图书出版单位登记表，经主管单位审核签章后，报所在地省、自治区、直辖市新闻出版行政部门； （二）图书出版单位登记表一式五份，图书出版单位、主办单位、主管单位及省、自治区、直辖市新闻出版行政部门各存一份，另一份由省、自治区、直辖市新闻出版行政部门在收到之日起15日内，报送新闻出版总署备案； （三）新闻出版总署对图书出版单位登记表审核后，在10日内通过中国标准书号中心分配其出版者号并通知省、自治区、直辖市新闻出版行政部门； （四）省、自治区、直辖市新闻出版行政部门对图书出版单位登记表审核后，在10日内向主办单位发放图书出版许可证； （五）图书出版单位持图书出版许可证到工商行政管理部门办理登记手续，依法领取营业执照。"},{"i":14,"n":"第十四条","txt":"图书出版单位的主办单位自收到新闻出版总署批准文件之日起60日内未办理注册登记手续，批准文件自行失效，登记机关不再受理登记，图书出版单位的主办单位须将有关批准文件缴回新闻出版总署。 图书出版单位自登记之日起满180日未从事图书出版的，由原登记的新闻出版行政部门注销登记，收回图书出版许可证，并报新闻出版总署备案。 因不可抗力或者其他正当理由发生前款所列情形的，图书出版单位可以向原登记的新闻出版行政部门申请延期。"},{"i":15,"n":"第十五条","txt":"图书出版单位应当具备法人条件，经核准登记后，取得法人资格，以其全部法人财产独立承担民事责任。"},{"i":16,"n":"第十六条","txt":"图书出版单位变更名称、主办单位或者主管单位、业务范围，合并或者分立，改变资本结构，依照本规定第九条至第十三条的规定办理审批、登记手续。 图书出版单位除前款所列变更事项外的其他事项的变更，应当经其主办单位和主管单位审查同意后，向所在地省、自治区、直辖市新闻出版行政部门申请变更登记，由省、自治区、直辖市新闻出版行政部门报新闻出版总署备案。"},{"i":17,"n":"第十七条","txt":"图书出版单位终止图书出版的，由主办单位提出申请并经主管单位同意后，由主办单位向所在地省、自治区、直辖市新闻出版行政部门办理注销登记，并由省、自治区、直辖市新闻出版行政部门报新闻出版总署备案。"},{"i":18,"n":"第十八条","txt":"组建图书出版集团，参照本规定第十条办理。"},{"i":19,"n":"第十九条","txt":"任何图书不得含有《出版管理条例》和其他有关法律、法规以及国家规定禁止的内容。"},{"i":20,"n":"第二十条","txt":"图书出版实行编辑责任制度，保障图书内容符合国家法律规定。"},{"i":21,"n":"第二十一条","txt":"出版辞书、地图、中小学教科书等类别的图书，实行资格准入制度，出版单位须按照新闻出版总署批准的业务范围出版。具体办法由新闻出版总署另行规定。"},{"i":22,"n":"第二十二条","txt":"图书出版实行重大选题备案制度。涉及国家安全、社会安定等方面的重大选题，涉及重大革命题材和重大历史题材的选题，应当按照新闻出版总署有关选题备案管理的规定办理备案手续。未经备案的重大选题，不得出版。"},{"i":23,"n":"第二十三条","txt":"图书出版实行年度出版计划备案制度。图书出版单位的年度出版计划，须经省、自治区、直辖市新闻出版行政部门审核后报新闻出版总署备案。"},{"i":24,"n":"第二十四条","txt":"图书出版单位实行选题论证制度、图书稿件三审责任制度、责任编辑制度、责任校对制度、图书重版前审读制度、稿件及图书资料归档制度等管理制度，保障图书出版质量。"},{"i":25,"n":"第二十五条","txt":"图书使用语言文字须符合国家语言文字法律规定。 图书出版质量须符合国家标准、行业标准和新闻出版总署关于图书出版质量的管理规定。"},{"i":26,"n":"第二十六条","txt":"图书使用中国标准书号或者全国统一书号、图书条码以及图书在版编目数据须符合有关标准和规定。"},{"i":27,"n":"第二十七条","txt":"图书出版单位不得向任何单位或者个人出售或者以其他形式转让本单位的名称、中国标准书号或者全国统一书号。"},{"i":28,"n":"第二十八条","txt":"图书出版单位不得以一个中国标准书号或者全国统一书号出版多种图书，不得以中国标准书号或者全国统一书号出版期刊。中国标准书号使用管理办法由新闻出版总署另行规定。"},{"i":29,"n":"第二十九条","txt":"图书出版单位租型出版图书、合作出版图书、出版自费图书须按照新闻出版总署的有关规定执行。"},{"i":30,"n":"第三十条","txt":"图书出版单位与境外出版机构在境内开展合作出版，在合作出版的图书上双方共同署名，须经新闻出版总署批准。"},{"i":31,"n":"第三十一条","txt":"图书出版单位须按照国家有关规定在其出版的图书上载明图书版本记录事项。"},{"i":32,"n":"第三十二条","txt":"图书出版单位应当委托依法设立的出版物印刷单位印刷图书，并按照国家规定使用印刷委托书。"},{"i":33,"n":"第三十三条","txt":"图书出版单位须遵守国家统计规定，依法向新闻出版行政部门报送统计资料。"},{"i":34,"n":"第三十四条","txt":"图书出版单位在图书出版30日内，应当按照国家有关规定向国家图书馆、中国版本图书馆、新闻出版总署免费送交样书。"},{"i":35,"n":"第三十五条","txt":"图书出版的监督管理实行属地原则。 省、自治区、直辖市新闻出版行政部门依法对本行政区域内的图书出版进行监督管理，负责本行政区域内图书出版单位的审核登记、年度核验及其出版图书的审读、质量评估等管理工作。"},{"i":36,"n":"第三十六条","txt":"图书出版管理实行审读制度、质量保障管理制度、出版单位分级管理制度、出版单位年度核验制度和出版从业人员职业资格管理制度。"},{"i":37,"n":"第三十七条","txt":"新闻出版总署负责全国图书审读工作。省、自治区、直辖市新闻出版行政部门负责对本行政区域内出版的图书进行审读，并定期向新闻出版总署提交审读报告。"},{"i":38,"n":"第三十八条","txt":"新闻出版行政部门可以根据新闻出版总署《图书质量管理规定》等规定，对图书质量进行检查，并予以奖惩。"},{"i":39,"n":"第三十九条","txt":"新闻出版总署制定图书出版单位等级评估办法，对图书出版单位进行评估，并实行分级管理。"},{"i":40,"n":"第四十条","txt":"图书出版单位实行年度核验制度，年度核验每两年进行一次。 年度核验按照以下程序进行： （一）图书出版单位提出年度自查报告，填写由新闻出版总署统一印制的图书出版年度核验表，经图书出版单位的主办单位、主管单位审核盖章后，在规定时间内报所在地省、自治区、直辖市新闻出版行政部门； （二）省、自治区、直辖市新闻出版行政部门在收到图书出版单位自查报告、图书出版年度核验表等年度核验材料30日内予以审核查验、出具审核意见，报送新闻出版总署； （三）新闻出版总署在收到省、自治区、直辖市新闻出版行政部门报送的图书出版单位年度核验材料和审核意见60日内作出是否予以通过年度核验的批复； （四）图书出版单位持新闻出版总署予以通过年度核验的批复文件、图书出版许可证副本等相关材料，到所在地省、自治区、直辖市新闻出版行政部门办理登记手续。"},{"i":41,"n":"第四十一条","txt":"图书出版单位有下列情形之一的，暂缓年度核验： （一）正在限期停业整顿的； （二）经审核发现有违法情况应予处罚的； （三）主管单位、主办单位未认真履行管理责任，导致图书出版管理混乱的； （四）所报年度核验自查报告内容严重失实的； （五）存在其他违法嫌疑需要进一步核查的。 暂缓年度核验的期限为6个月。在暂缓年度核验期间，图书出版单位除教科书、在印图书可继续出版外，其他图书出版一律停止。缓验期满，按照本规定重新办理年度核验手续。"},{"i":42,"n":"第四十二条","txt":"图书出版单位有下列情形之一的，不予通过年度核验： （一）出版导向严重违反管理规定并未及时纠正的； （二）违法行为被查处后拒不改正或者在整改期满后没有明显效果的； （三）图书出版质量长期达不到规定标准的； （四）经营恶化已经资不抵债的； （五）已经不具备本规定第九条规定条件的； （六）暂缓登记期满，仍未符合年度核验基本条件的； （七）不按规定参加年度核验，经催告仍未参加的； （八）存在其他严重违法行为的。 对不予通过年度核验的图书出版单位，由新闻出版总署撤销图书出版许可证，所在地省、自治区、直辖市新闻出版行政部门注销登记。"},{"i":43,"n":"第四十三条","txt":"年度核验结果，新闻出版总署和省、自治区、直辖市新闻出版行政部门可以向社会公布。"},{"i":44,"n":"第四十四条","txt":"图书出版从业人员，应具备国家规定的出版职业资格条件。"},{"i":45,"n":"第四十五条","txt":"图书出版单位的社长、总编辑须符合国家规定的任职资格和条件。 图书出版单位的社长、总编辑须参加新闻出版行政部门组织的岗位培训，取得岗位培训合格证书后才能上岗。"},{"i":46,"n":"第四十六条","txt":"图书出版单位违反本规定的，新闻出版总署或者省、自治区、直辖市新闻出版行政部门可以采取下列行政措施： （一）下达警示通知书； （二）通报批评； （三）责令公开检讨； （四）责令改正； （五）核减中国标准书号数量； （六）责令停止印制、发行图书； （七）责令收回图书； （八）责成主办单位、主管单位监督图书出版单位整改。 警示通知书由新闻出版总署制定统一格式，由新闻出版总署或者省、自治区、直辖市新闻出版行政部门下达给违法的图书出版单位，并抄送违法图书出版单位的主办单位及其主管单位。 本条所列行政措施可以并用。"},{"i":47,"n":"第四十七条","txt":"未经批准，擅自设立图书出版单位，或者擅自从事图书出版业务，假冒、伪造图书出版单位名称出版图书的，依照《出版管理条例》第五十五条处罚。"},{"i":48,"n":"第四十八条","txt":"图书出版单位出版含有《出版管理条例》和其他有关法律、法规以及国家规定禁止内容图书的，由新闻出版总署或者省、自治区、直辖市新闻出版行政部门依照《出版管理条例》第五十六条处罚。"},{"i":49,"n":"第四十九条","txt":"图书出版单位违反本规定第二十七条的，由新闻出版总署或者省、自治区、直辖市新闻出版行政部门依照《出版管理条例》第六十条处罚。"},{"i":50,"n":"第五十条","txt":"图书出版单位有下列行为之一的，由新闻出版总署或者省、自治区、直辖市新闻出版行政部门依照《出版管理条例》第六十一条处罚： （一）变更名称、主办单位或者其主管单位、业务范围 、合并或分立、改变资本结构，未依法办理审批手续的； （二）未按规定将其年度出版计划备案的； （三）未按规定履行重大选题备案的； （四）未按规定送交样书的。"},{"i":51,"n":"第五十一条","txt":"图书出版单位有下列行为之一的，由新闻出版总署或者省、自治区、直辖市新闻出版行政部门给予警告，并处3万元以下罚款： （一）未按规定使用中国标准书号或者全国统一书号、图书条码、图书在版编目数据的； （二）图书出版单位违反本规定第二十八条的； （三）图书出版单位擅自在境内与境外出版机构开展合作出版，在合作出版的图书上双方共同署名的； （四）未按规定载明图书版本记录事项的； （五）图书出版单位委托非依法设立的出版物印刷单位印刷图书的，或者未按照国家规定使用印刷委托书的。"},{"i":52,"n":"第五十二条","txt":"图书出版单位租型出版图书、合作出版图书、出版自费图书，违反新闻出版总署有关规定的，由新闻出版总署或者省、自治区、直辖市新闻出版行政部门给予警告，并处3万元以下罚款。"},{"i":53,"n":"第五十三条","txt":"图书出版单位出版质量不合格的图书，依据新闻出版总署《图书质量管理规定》处罚。"},{"i":54,"n":"第五十四条","txt":"图书出版单位未依法向新闻出版行政部门报送统计资料的，依据新闻出版总署、国家统计局联合颁布的《新闻出版统计管理办法》处罚。"},{"i":55,"n":"第五十五条","txt":"对图书出版单位作出行政处罚，新闻出版行政部门应告知其主办单位和主管单位，可以通过媒体向社会公布。 对图书出版单位作出行政处罚，新闻出版行政部门可以建议其主办单位或者主管单位对直接责任人和主要负责人予以行政处分或者调离岗位。"},{"i":56,"n":"第五十六条","txt":"本规定自2008年5月1日起施行。 自本规定施行起，此前新闻出版行政部门对图书出版的其他规定，凡与本规定不一致的，以本规定为准。"}],"tushuzhiliangbaozhangtixi":[{"i":1,"n":"第一条","txt":"依据国务院颁布的《出版管理条例》，建立和实施严格、有效、可操作的图书质量保障体系，是实现图书出版从扩大规模数量为主向提高质量效益为主的转变，提高图书出版整体水平，繁荣社会主义出版事业的重要措施。"},{"i":2,"n":"第二条","txt":"建立和实施图书质量保障体系的指导思想：以马克思列宁主义、毛泽东思想和邓小平建设有中国特色社会主义理论为指导，坚持党的基本路线和基本方针，以建立适应社会主义市场经济体制，符合社会主义精神文明建设要求，体现出版工作自身规律的出版体制为目的，坚持为人民服务、为社会主义服务的方向，坚持百花齐放、百家争鸣的方针，坚持精神文明重在建设，繁荣出版重在质量的思想，把能否提高图书质量当作衡量出版工作是否健康发展、检验出版改革成功与否的重要标志。提高认识，强化管理，使出版事业朝着健康、有序、优质、高效的方向发展。"},{"i":3,"n":"第三条","txt":"实施图书质量保障体系的基本原则：图书质量保障体系是一项系统工程，要有严密的组织，需要各出版社、出版社的主管部门、各级出版行政部门以及社会各界的共同参与，形成网络；要有科学、严格、有效的机制，根据图书生产、销售和管理的规律，分部门、分阶段、分层次组织实施，分清任务，明确责任，提高管理和运行水平；要有称职的队伍，各单位要制定计划，对各级、各类的出版从业人员，特别是从事编辑工作和出版行政管理工作人员，进行考核和培训，提高思想、政策、职业道德、专业技术水平。"},{"i":4,"n":"第四条","txt":"加强图书出版法制建设。加强图书出版的法制建设，是图书质量保障体系正常、有效实施的根本保证。国务院颁布的《出版管理条例》是出版行业的重要法规，也是图书质量保障体系依法实施的保证。各级出版行政部门要依据《出版管理条例》，做到依法管理，对违反《出版管理条例》和《图书质量保障体系》的行为，要依据相应的法规和规定，坚决予以查处，以维护社会主义出版法规和规定的权威性和严肃性。各省、自治区、直辖市新闻出版局、出版社主管部门和出版社在认真执行《出版管理条例》和《图书质量保障体系》的同时，还可根据这些法规和规定，制定本地区、本部门和出版社内部的管理规定、制度，提高图书出版管理水平。"},{"i":5,"n":"第五条","txt":"坚持按专业分工出书制度。按专业分工出书对于发挥出版社的专业人才，资源优势和特点，为本行业、本部门、本地区服务，提高图书质量，形成出版特色，具有重要作用。各出版社必须严格按照新闻出版署核定的出书范围和有关规定执行。"},{"i":6,"n":"第六条","txt":"加强选题策划工作。 （一）图书质量的提高，首先取决于选题的优化，优化的第一步要搞好选题的策划工作。 （二）策划是出版工作的重要环节，出版社的全体编辑人员应认真履行编辑职责，积极参与选题的策划工作。 （三）出版社编辑人员在策划选题时，要注意广泛收集、积累、研究与本社出书范围有关的信息，注意加强与有关学术、科研、教学、创作等部门和专家、学者的联系，倾听他们的意见，提高策划水平。"},{"i":7,"n":"第七条","txt":"坚持选题论证制度。选题质量的优劣，直接影响图书质量，也影响出版社的整体出版水平。出版社要对选题进行多方面的考察，既要从微观上论证选题的可行性，又要从宏观上考虑各类选题的合理结构，为此要注意以下三点： （一）选题论证应当坚持以马克思列宁主义、毛泽东思想、邓小平同志建设有中国特色社会主义理论为指导，坚持党的基本路线，贯彻“为人民服务、为社会主义服务、为全党全国工作大局服务”和“百花齐放、百家争鸣”的方针，始终以社会效益为最高准则，在此前提下，注意经济效益，力争做到“两个效益”的最佳结合。使选题论证结果符合质量第一的原则，符合控制总量、优化结构、提高质量、增进效益的总体要求。 （二）要加强调研工作，充分运用各方面的信息资源和群体的知识资源，进行深入的调查研究，研究有关的学术、学科发展状况，了解读者的需求，掌握图书市场的供求情况，使选题的确定建立在准确、可靠、科学的基础上。 （三）坚持民主和集"},{"i":8,"n":"第八条","txt":"坚持稿件三审责任制度。审稿是编辑工作的中心环节，是一种从出版专业角度，对书稿进行科学分析判断的理性活动。因此，在选题获得批准后，要做好编前准备工作，加强与作者的联系。稿件交来后，要切实做好初审、复审和终审工作，三个环节缺一不可。三审环节中，任何两个环节的审稿工作不能同时由一人担任。在三审过程中，始终要注意政治性和政策性问题，同时切实检查稿件的科学性、艺术性和知识性问题。 （一）初审，应由具有编辑职称或具备一定条件的助理编辑人员担任（一般为责任编辑），在审读全部稿件的基础上，主要负责从专业的角度对稿件的社会价值和文化学术价值进行审查，把好政治关、知识关、文字关。要写出初审报告，并对稿件提出取舍意见和修改建议。 （二）复审，应由具有正、副编审职称的编辑室主任一级的人员担任。复审应审读全部稿件，并对稿件质量及初审报告提出复审意见，作出总的评价，并解决初审中提出的问题。 （三）终审，应由具有正"},{"i":9,"n":"第九条","txt":"坚持责任编辑制度。图书的责任编辑由出版社指定，一般由初审者担任。除负责初审工作外，还要负责稿件的编辑加工整理和付印样的通读工作，使稿件的内容更完善，体例更严谨，材料更准确，语言文字更通达，逻辑更严密，消除一般技术性差错，防止出现原则性错误；并负责对编辑、设计、排版、校对、印刷等出版环节的质量进行监督。为保证图书质量，也可根据稿件情况，适当增加责任编辑人数。"},{"i":10,"n":"第十条","txt":"坚持责任设计编辑制度和设计方案三级审核制度。图书的整体设计，包括图书外部装帧设计和内文版式设计。设计质量是图书整体质量的重要组成部分。提高图书的整体设计质量，是提高图书质量的重要方面。出版社每出一种书，都要指定一名具有相应专业职称的编辑为责任设计编辑，主要负责提出图书的整体设计方案、具体设计或对委托他人设计的方案和设计的成品质量进行把关。图书的整体设计也要严格执行责任设计编辑、编辑室主任、社长或总编辑（副社长或副总编辑）三级审核制度。"},{"i":11,"n":"第十一条","txt":"坚持责任校对制度和“三校一读”制度。专业校对是出版流程中不可缺少的环节，直接影响图书的质量。出版社应配备足够的具有专业技术职称的专职校对人员，负责专业校对工作。出版社每出一种书，都要指定一名具有专业技术职称的专职校对人员为责任校对，负责校样的文字技术整理工作，监督检查各校次的质量，并负责付印样的通读工作。一般图书的专业校对应不低于三个校次，重点图书、工具书等，应相应增加校次。终校必须由本社有中级以上专业技术职称的专职校对人员担任。聘请的社外校对人员，必须具有相应的专业技术职称和丰富的校对经验。对采用现代排版技术的图书，还要通读付印软片或软片样。"},{"i":12,"n":"第十二条","txt":"坚持印刷质量标准和《委托书》制度。出版社印制图书必须到有“书报刊印刷许可证”的印装厂印制。印装厂承接图书印制业务时，必须查验出版社开具的全国统一的由新闻出版署监制的《委托书》，否则，不得承印。印制时必须严格按照国家技术监督部门和出版行政部门制定的有关书刊印刷标准和书刊印刷产品质量监督管理规定执行。"},{"i":13,"n":"第十三条","txt":"坚持图书书名页使用标准。图书书名页是图书正文之前载有完整书名信息的书页，包括主书名页和附书名页。主书名页应载有完整的书名、著作责任说明、版权说明、图书在版编目数据、版本记录等内容；附书名页应载有多卷书、丛书、翻译书等有关书名信息。图书书名页是图书不可缺少的部分，具有重要信息价值。出版社出版的图书必须严格按照国家的有关标准执行。"},{"i":14,"n":"第十四条","txt":"坚持中国标准书号和图书条码使用标准。中国标准书号是目前国际通用的一种科学合理的图书编码系统。条码技术是国际上通行的一种主要的信息标识技术，图书使用条码技术，有利于图书信息在销售中的广泛、快捷地传播、使用。出版社必须严格按照国家标准和有关规定，正确使用中国标准书号和条码技术。"},{"i":15,"n":"第十五条","txt":"坚持图书成批装订前的样书检查制度。印装厂在每种书封面和内文印刷完毕、未成批装订前，必须先装订10本样书，送出版社查验。出版社负责联系印制的业务人员、责任编辑、责任校对及主管社领导，应从总体上对装订样书的质量进行审核，如发现问题，立即通知印装厂，封存待装订的印成品并进行处理；如无问题，要正式具文通知印装厂开始装订。出版社应在接到样书后3日内通知印装厂。印装厂在未接到出版社的通知前，不得擅自将待装订的印成品装订出厂。"},{"i":16,"n":"第十六条","txt":"坚持出书后的评审制度。出版社要成立图书质量评审委员会。评审委员会由具有高级职称的在职或离职的编辑以及社会上的专家学者组成，定期对本社新出版的图书的质量进行认真的审读、评议。出版社根据评议结果，奖优罚劣，并对质量有问题的图书，根据有关规定，进行相应处理。"},{"i":17,"n":"第十七条","txt":"坚持图书征订广告审核制度。出版社法人代表应对本版图书的广告质量负全部责任。出版、发行单位为推销图书印制的征订单和广告，必须事先报出版社审核，经出版社法人指定的部门负责人和责任编辑审核同意并出具书面意见后，才可印制、散发。"},{"i":18,"n":"第十八条","txt":"坚持图书样本缴送制度。出版社每新出一种图书，应在出书后一个月内，按规定分别向新闻出版署、中宣部出版局、中国版本图书馆、北京图书馆缴送样书一册（套）备查。"},{"i":19,"n":"第十九条","txt":"坚持图书重版前审读制度。图书重版有利于扩大图书的社会效益和经济效益，因此，更需要对图书内容质量严格把关。出版社出版的新书首次重版前，必须组织具有高级职称的编辑人员（含具有高级职称的离退休者）对图书内容和质量重新进行审读，写出书面审读意见，由社长或总编辑核定。"},{"i":20,"n":"第二十条","txt":"坚持稿件及图书质量资料归档制度。出版社应将稿件连同图书出版合同、稿件审读意见、稿费通知单、印刷委托书、排印单、样书等一起归档。同时，还必须把图书出版过程中每一环节的质量情况以及读者和学术界对图书质量的意见，书评和各种奖励或处罚情况，采取表格形式记录在案并归档，便于对图书质量整体情况进行分析研究，提高图书出版质量的管理水平。"},{"i":21,"n":"第二十一条","txt":"坚持出版社与作者和读者联系制度。出版社要保持同作者和读者长期、紧密的联系，依靠作者，并在可能的条件下为作者的创作、研究提供必要条件；同时，倾听作者和读者对图书质量的意见，及时改进工作。"},{"i":22,"n":"第二十二条","txt":"坚持年度选题计划审批和备案制度。各省、自治区、直辖市新闻出版局和出版社的主管部门负有对所辖、所属出版社选题计划的审批责任，必须按有关法律、规定严格把关；同时要送交本省（自治区、直辖市）党委宣传部门备案。经省（自治区、直辖市）新闻出版局和出版社主管部门批准的各出版社的选题计划，必须报新闻出版署备案。新闻出版署可对导向、总量、结构和趋势等问题提出指导性意见，对不符合国家法规、规定的选题进行调整或通知撤销。"},{"i":23,"n":"第二十三条","txt":"坚持重大选题备案制度。对涉及政治、军事、安全、外交、宗教、民族等敏感问题的重大选题和其他需宏观调控的重大选题，必须按照国务院《出版管理条例》和国务院出版行政部门的有关规定履行备案手续。凡列入备案范围内的重大选题，出版社在出版之前，必须报新闻出版署备案，未申报备案或报来后未得到备案答复的，一律不得出版。重大选题备案的一般程序是：先由出版社写出申请报告和对稿件的审读意见（写明没有把握要请示的问题），连同稿件一并报主管部门；主管部门经审读稿件后如认为有出版价值，再正式向新闻出版署申报备案，申报时，应当填写备案登记登记表并提交下列材料： （一）备案的报告； （二）稿件； （三）出版社的上级主管部门的具体审读意见。 上述备案材料不齐备时，新闻出版署负责备案的部门不予受理。新闻出版署受理备案之后，按照有关规定予以答复。"},{"i":24,"n":"第二十四条","txt":"坚持对全国发排新书目的审核制度。《全国发排新书半月报》是国家出版行政部门及时了解出版信息，掌握出版动态的重要资料。各出版社要按时、认真报送发排新书目，以便于国家出版行政部门审核研究，对倾向性问题，及时发现，及时解决。"},{"i":25,"n":"第二十五条","txt":"坚持出版通气会制度。由中宣部和新闻出版署主持的出版通气会，定期召开，由有关部委、省委宣传部、省（自治区、直辖市）新闻出版局负责同志参加，主要贯彻中央和国务院的新精神，通报出版工作的新情况、新问题，及时对全国的出版工作提出指导意见。"},{"i":26,"n":"第二十六条","txt":"坚持出版法规强化培训制度。针对出版工作中发生的值得注意的新问题，中宣部、新闻出版署召集有关出版社及其党政主管部门的负责人，举办强化培训班，学习出版法规，分析研究问题，制定整改措施。"},{"i":27,"n":"第二十七条","txt":"坚持舆论引导制度。出版行政部门应充分发挥各种新闻传播媒体的宣传引导作用，围绕提高图书质量，通报政策、沟通信息、交流经验、评荐好书、批评坏书。"},{"i":28,"n":"第二十八条","txt":"坚持制定和实施中长期出版规划制度，加强对制定年度选题计划的指导。制订规划的目的是抓导向、抓质量，促进图书出版整体质量的提高，推动出版事业长期、稳定地发展。新闻出版署主要做好国家五年重点图书出版规划，重要门类的选题出版规划以及国家重点出版工程的制定工作。各省、自治区、直辖市新闻出版局和出版社的主管部门也要根据地区、部门的特点和需要，制订好地方和部门出版规划。规划务求精当、突出重点、体现导向。搞好年度选题计划对于提高图书质量十分关键。新闻出版署一般于本年度末对下一年度制定选题计划的指导思想和重点内容提出原则意见。各省、自治区、直辖市新闻出版局和出版社主管部门可结合本地区、本部门实际提出具体实施意见。"},{"i":29,"n":"第二十九条","txt":"坚持出版基金保障制度。在社会主义市场经济条件下，各省、自治区、直辖市新闻出版局和出版社的主管部门以及各出版社要创造条件，面向社会，多渠道筹集资金，建立多层次、多形式的出版基金，发挥经济政策的引导和调控作用，扶持优秀图书的出版。同时要制定科学、可行的基金管理和使用办法。"},{"i":30,"n":"第三十条","txt":"坚持出版社年检登记制度。出版社年检实行“一年一自检，两年一统检”，即每年出版社结合总结工作，自我检查；每两年由新闻出版署组织全国出版社统一检查。统一年检是在学习和总结的基础上，先由出版社进行自查，提出改进工作的措施，写出总结报告，经主管部门审核并提出意见后，报新闻出版署核验批准。经新闻出版署批准合格者，可以办理换证登记手续。不合格者，给予暂缓登记处分，停止其出版业务。暂缓登记期自发文之日起六个月。六个月内，经整改仍达不到年检登记基本条件者，取消其出版社登记资格及出版者前缀号。"},{"i":31,"n":"第三十一条","txt":"坚持书号使用总量宏观调控制度。合理控制书号使用总量，有利于优化选题、调整结构、提高质量，保证重点图书、学术著作的出版，也有利于出版资源的合理配置。各省、自治区、直辖市新闻出版局、出版社主管部门和出版社必须严格执行新闻出版署制定的有关对书号使用总量进行宏观调控的规定。"},{"i":32,"n":"第三十二条","txt":"坚持图书跨省印制审批制度。凡跨省印制的图书，由出版社持印制《委托书》到所在地省、自治区、直辖市新闻出版局办理出省印制手续，再到承印厂所在省（自治区、直辖市）新闻出版局办理进省印制手续。《委托书》必须由两省（自治区、直辖市）新闻出版局分别审核批准，否则承印厂不得承接。"},{"i":33,"n":"第三十三条","txt":"坚持图书售前送审制度。加强对批发、零售样书的售前审核，是有效控制图书负面影响的重要手段之一。图书市场管理部门要严格按照有关规定加强对批发、零售样书的售前审核，不论是批发市场还是零售市场（摊点），凡进场（摊点）销售的图书必须报经当地图书市场管理部门审核，未经报审批准，不得批发、零售；擅自批发、进货销售者，应根据有关规定，给予行政处罚。同时，图书市场管理部门，要严格依法办事，提高工作效率。"},{"i":34,"n":"第三十四条","txt":"坚持随机抽样审读制度。各级出版行政部门要有重点、有目的、有针对性地组织有经验、有水平的审读人员，对所辖地区出版社出版的和市场上销售的图书内容进行随机抽样审读，对优秀图书要向读者大力推荐；对有问题的图书要及时处理并向上报告；对倾向性问题要及时向上汇报，向下打招呼。"},{"i":35,"n":"第三十五条","txt":"坚持图书出版定期综合分析制度。各省、自治区、直辖市新闻出版局要对本地区各出版社出版的图书进行跟踪了解，每半年对已出版的图书做一次综合性分析（包括重点书审读情况，出书结构、特点、趋势、问题等），写出书面报告，报新闻出版署。"},{"i":36,"n":"第三十六条","txt":"坚持图书编校、印装质量检查制度。编校、印装质量是图书整体质量的重要组成部分，对图书的社会效益和经济效益产生重要影响。坚持经常性地对图书编校、印装质量进行检查，有利于提高图书的整体质量。各出版社和主管部门要根据国家制定的图书质量管理规定，每年至少分别进行两次图书编校、印装质量检查。新闻出版署也将每年不定期对部分图书进行抽样检查。对不合格的图书或不合格图书的比例超过规定标准的出版社，按有关规定进行处罚。"},{"i":37,"n":"第三十七条","txt":"坚持图书市场的动态监测制度。巩固和完善图书市场动态监测网络，有利于图书市场朝着健康、有序的方向发展，各地图书市场管理部门要密切配合，做到信息准确，反应灵敏，措施有力。"},{"i":38,"n":"第三十八条","txt":"坚持优秀图书奖励制度。奖励优秀图书，有利于调动广大出版工作者的积极性，有利于向广大读者推荐优秀图书，从而促进图书质量的提高。各级出版行政部门和出版社，应严格执行中央和国务院有关图书评奖的规定，并认真做好优秀图书评奖工作。特别是中央宣传部精神文明建设“五个一工程”的“一本好书奖”和新闻出版署主办的国家级政府奖“国家图书奖”及中国出版工作者协会组织的“中国图书奖”的评选工作。同时，各省、自治区、直辖市新闻出版局和有关部门也可根据有关规定开展地区和部门内的优秀图书评奖活动，并使之制度化。"},{"i":39,"n":"第三十九条","txt":"坚持优秀编辑出版人员表彰制度。编辑队伍是提高图书质量的主力军。新闻出版署、人事部每五年评选一次“出版系统先进集体、先进工作者（劳动模范）”；中国出版工作者协会每两年评选一次“百佳出版工作者”、每两年评选一次“韬奋奖”。各级出版行政部门要分层次、分门类定期做好编辑出版人员的表彰工作，充分调动编辑出版人员的积极性，鼓励他们不断提高自身的思想和业务水平。"},{"i":40,"n":"第四十条","txt":"坚持优秀和良好出版社表彰制度。在全国出版社年检的基础上，评选出优秀出版社和良好出版社，予以表彰，对鼓励出版社坚持正确出版方向，提高图书质量，办出特色具有重要意义。每次全国统一年检结束后，评选出良好出版社，然后在良好出版社中，评选出优秀出版社。对受到表彰后出现问题的出版社，一经查实，立即取消其荣誉称号。"},{"i":41,"n":"第四十一条","txt":"坚持对违规出版社和责任人的处罚制度。本着依法管理，有法必依，违法必究的原则，对出版违反国家法律、法规和出版行政管理规定的图书的出版社和责任人要严肃处理。各级出版行政部门要切实负起责任，除对违规图书根据定性作出处理外，对出版社则根据所犯错误的性质，依据有关法规和规定作出行政处罚，处罚包括：批评、警告、没收利润、罚款、停止某一编辑室业务、停止某一类图书出版权、全社停业整顿、吊销社号；对因渎职导致出版坏书、出版社被停业整顿或被吊销社号的，出版社有关责任人必须调离出版业务岗位，有关领导者不得再担任出版社领导职务。对构成犯罪的，要依法追究刑事责任。"},{"i":42,"n":"第四十二条","txt":"坚持分级管理责任制度。各级出版行政部门，肩负着党和政府赋予的重要管理职责，应尽职尽责，做好管理工作。一旦出现问题，涉及哪一级，就追究哪一级部门的领导责任。坚决杜绝那种日常管理不负责任，出了问题推卸责任的现象。"},{"i":43,"n":"第四十三条","txt":"坚持主管、主办单位负责制。主管、主办单位对所属出版社负有直接领导责任，必须切实承担起管理的职责。要指定部门，并配备合格的管理人员，既要指导、监督所属出版社自觉按照党和国家的方针、政策，多出好书，同时也要为出版社出好书提供必要的条件。"},{"i":44,"n":"第四十四条","txt":"坚持出版社业务人员持证上岗制度。出版行政部门应根据国家制定的有关出版从业人员（包括出版社负责人、编辑、校对等）资格认定标准和业绩考核办法，定期、分层次、分类别对出版社的业务人员进行资格认定和业绩考核，考核前先培训，合格者，持证上岗；不合格者，要下岗再培训，经再培训考核仍不合格者，调离业务岗位。"},{"i":45,"n":"第四十五条","txt":"坚持出版行业协会监督制度。出版行业协会是出版行政部门的有力补充。中国出版工作者协会、中国编辑学会、中国书刊业发行协会、中国印刷技术协会以及其他专业协会和各地相应的团体，都应根据各自的特点建立和完善行规行约，从保护会员合法权益和履行应尽义务的角度，在图书质量保障方面，做好自我约束和调研、咨询、协调、监督工作，形成网络。"},{"i":46,"n":"第四十六条","txt":"坚持社会团体监督制度。各种群众团体，学术组织集中了社会各方面的人才，代表着社会上广大群众的利益，反映各阶层群众的呼声。出版行政部门、出版社主管部门和出版社要紧紧依靠他们，同他们建立固定的联系渠道，主动征求、随时听取他们对提高图书质量的意见、建议，不断改进工作。"},{"i":47,"n":"第四十七条","txt":"坚持读者投诉反馈制度。广大读者既是对图书质量进行社会监督的主要力量，也是出版行政部门搞好宏观调控的社会基础。出版行政部门要充分重视和发挥读者的监督作用，认真对待读者对图书质量问题的投诉，本着实事求是、真诚负责的态度，对质量不合格的图书，要按有关规定坚决处理。出版社有义务解决读者投诉提出的问题并予以回复，使读者满意。"},{"i":48,"n":"第四十八条","txt":"坚持社会舆论监督制度。出版行政部门和出版社对社会各界人士通过各种媒介对图书质量发表的意见要予以高度重视，充分发挥社会舆论的监督作用，对维护良好的出版秩序，依法进行出版行政管理具有重要意义。特别是在社会主义市场经济条件下，有利于抵制部门和地方保护主义对图书质量保障体系的干扰，防止出版行政部门在行使管理职权时，有法不依、滥用职权、甚至执法犯法。"},{"i":49,"n":"第四十九条","txt":"本《体系》由新闻出版署制定并负责解释。各省、自治区、直辖市新闻出版局、出版社的主管部门和出版社可根据本《体系》的有关原则，制定本地区、本部门和本社的具体实施细则，并报新闻出版署备案。"},{"i":50,"n":"第五十条","txt":"本《体系》自发布之日起生效。"}],"tushuzhiliangguanliguiding":[{"i":1,"n":"第一条","txt":"为建立健全图书质量管理机制，规范图书出版秩序，促进图书出版业的繁荣和发展，保护消费者的合法权益，根据《中华人民共和国产品质量法》和国务院《出版管理条例》制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于依法设立的图书出版单位出版的图书的质量管理。 出版时间超过十年且无再版或者重印的图书，不适用本规定。"},{"i":3,"n":"第三条","txt":"图书质量包括内容、编校、设计、印制四项，分为合格、不合格两个等级。 内容、编校、设计、印制四项均合格的图书，其质量属合格。内容、编校、设计、印制四项中有一项不合格的图书，其质量属不合格。"},{"i":4,"n":"第四条","txt":"符合《出版管理条例》第二十六、二十七条规定的图书，其内容质量属合格。 不符合《出版管理条例》第二十六、二十七条规定的图书，其内容质量属不合格。"},{"i":5,"n":"第五条","txt":"差错率不超过万分之一的图书，其编校质量属合格。 差错率超过万分之一的图书，其编校质量属不合格。 图书编校质量差错的判定以国家正式颁布的法律法规、国家标准和相关行业制定的行业标准为依据。图书编校质量差错率的计算按照本规定附件《图书编校质量差错率计算方法》执行。"},{"i":6,"n":"第六条","txt":"图书的整体设计和封面（包括封一、封二、封三、封底、勒口、护封、封套、书脊）、扉页、插图等设计均符合国家有关技术标准和规定的，其设计质量属合格。 图书的整体设计和封面（包括封一、封二、封三、封底、勒口、护封、封套、书脊）、扉页、插图等设计中有一项不符合国家有关技术标准和规定的，其设计质量不合格。"},{"i":7,"n":"第七条","txt":"符合中华人民共和国出版行业标准《印刷产品质量评价和分等导则》（CY/T　2-1999）规定的图书，其印制质量属合格。 不符合中华人民共和国出版行业标准《印刷产品质量评价和分等导则》（CY/T　2-1999）规定的图书，其印制质量属不合格。"},{"i":8,"n":"第八条","txt":"新闻出版总署负责全国图书质量管理工作，依照本规定实施图书质量检查，并向社会及时公布检查结果。"},{"i":9,"n":"第九条","txt":"各省、自治区、直辖市新闻出版行政部门负责本行政区域内的图书质量管理工作，依照本规定实施图书质量检查，并向社会及时公布检查结果。"},{"i":10,"n":"第十条","txt":"图书出版单位的主办单位和主管机关应当履行其主办、主管职能，尽其责任，协助新闻出版行政部门实施图书质量管理，对不合格图书提出处理意见。"},{"i":11,"n":"第十一条","txt":"图书出版单位应当设立图书质量管理机构，制定图书质量管理制度，保证图书质量合格。"},{"i":12,"n":"第十二条","txt":"新闻出版行政部门对图书质量实施的检查包括：图书的正文、封面（包括封一、封二、封三、封底、勒口、护封、封套、书脊）、扉页、版权页、前言（或序）、后记（或跋）、目录、插图及其文字说明等。正文部分的抽查必须内容（或页码）连续且不少于10万字，全书字数不足10万字的必须检查全书。"},{"i":13,"n":"第十三条","txt":"新闻出版行政部门实施图书质量检查，须将审读记录和检查结果书面通知出版单位。出版单位如有异议，可以在接到通知后15日内提出申辩意见，请求复检。对复检结论仍有异议的，可以向上一级新闻出版行政部门请求裁定。"},{"i":14,"n":"第十四条","txt":"对在图书质量检查中被认定为成绩突出的出版单位和个人，新闻出版行政部门给予表扬或者奖励。"},{"i":15,"n":"第十五条","txt":"对图书内容违反《出版管理条例》第二十六、二十七条规定的，根据《出版管理条例》第五十六条实施处罚。"},{"i":16,"n":"第十六条","txt":"对出版编校质量不合格图书的出版单位，由省级以上新闻出版行政部门予以警告，可以根据情节并处3万元以下罚款。"},{"i":17,"n":"第十七条","txt":"经检查属编校质量不合格的图书，差错率在万分之一以上万分之五以下的，出版单位必须自检查结果公布之日起30天内全部收回，改正重印后可以继续发行；差错率在万分之五以上的，出版单位必须自检查结果公布之日起30天内全部收回。 出版单位违反本规定继续发行编校质量不合格图书的，由省级以上新闻出版行政部门按照《中华人民共和国产品质量法》第五十条的规定处理。"},{"i":18,"n":"第十八条","txt":"对于印制质量不合格的图书，出版单位必须及时予以收回、调换。 出版单位违反本规定继续发行印制质量不合格图书的，由省级以上新闻出版行政部门按照《中华人民共和国产品质量法》第五十条的规定处理。"},{"i":19,"n":"第十九条","txt":"一年内造成三种以上图书不合格或者连续两年造成图书不合格的直接责任者，由省、自治区、直辖市新闻出版行政部门注销其出版专业技术人员职业资格，三年之内不得从事出版编辑工作。"},{"i":20,"n":"第二十条","txt":"本规定自2005年3月1日起实施。新闻出版署于1997年3月3日公布的《图书质量管理规定》同时停止执行。 附件 图书编校质量差错率计算方法 一、图书编校差错率 图书编校差错率，是指一本图书的编校差错数占全书总字数的比率，用万分比表示。实际鉴定时，可以依据抽查结果对全书进行认定。如检查的总字数为10万，检查后发现两个差错，则其差错率为0.2/10000。 二、图书总字数的计算方法 图书总字数的计算方法，一律以该书的版面字数为准，即：总字数=每行字数×每面行数×总面数。 1．除环衬等空白面不计字数外，凡连续编排页码的正文、目录、辅文等，不论是否排字，均按一面满版计算字数。分栏排版的图书，各栏之间的空白也计算版面字数。 2．书眉（或中缝）和单排的页码、边码作为行数或每行字数计入正文，一并计算字数。 3．索引、附录等字号有变化时，分别按实际版面计算字数。 4．用小号字排版的脚注文字超过5行不足"}],"fuzhiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强管理，促进我国复制业健康发展，根据《出版管理条例》和《音像制品管理条例》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于光盘、磁带磁盘以及新闻出版总署认定的其他存储介质形态（以下简称其他介质）的复制经营活动。 本办法所称光盘包括只读类光盘和可录类光盘。其中，只读类光盘是指存储有内容的光盘；可录类光盘是指空白光盘。 本办法所称复制经营活动，包括经营性的光盘复制生产和存储有内容的磁带磁盘复制等活动。 本办法所称复制单位是指从事光盘、磁带磁盘和其他介质复制经营活动的单位。"},{"i":3,"n":"第三条","txt":"任何单位和个人禁止复制含有以下内容的复制品： （一）反对宪法确定的基本原则的； （二）危害国家统一、主权和领土完整的； （三）泄露国家秘密、危害国家安全或者损害国家荣誉和利益的； （四）煽动民族仇恨、民族歧视，破坏民族团结，或者侵害民族风俗、习惯的； （五）宣扬邪教、迷信的； （六）扰乱社会秩序，破坏社会稳定的； （七）宣扬淫秽、赌博、暴力或者教唆犯罪的； （八）侮辱或者诽谤他人，侵害他人合法权益的； （九）危害社会公德或者民族优秀文化传统的； （十）有法律、行政法规和国家规定禁止的其他内容的。"},{"i":4,"n":"第四条","txt":"新闻出版总署主管全国光盘、磁带磁盘以及其他介质复制经营活动的监督管理工作，负责只读类光盘设立的审批。 县级以上地方新闻出版行政部门负责本行政区域内光盘、磁带磁盘以及其他介质复制经营活动的监督管理工作。其中，省级新闻出版行政部门负责可录类光盘生产单位和磁带磁盘复制单位设立的审批。"},{"i":5,"n":"第五条","txt":"新闻出版行政部门根据已经取得的违法嫌疑证据或者举报，对涉嫌违法从事复制经营活动的行为进行查处时，可以检查与违法活动有关的物品；对有证据证明是与违法活动有关的物品，可以查封或者扣押。"},{"i":6,"n":"第六条","txt":"复制单位应当建立质量保障体系，健全各项管理制度。"},{"i":7,"n":"第七条","txt":"复制行业的社会团体按照其章程，在新闻出版行政部门的指导下，实行自律管理。"},{"i":8,"n":"第八条","txt":"国家对复制经营活动实行许可制度；未经许可，任何单位和个人不得从事复制经营活动。 设立复制单位须由新闻出版行政部门审批，核发复制经营许可证，并经工商行政部门登记注册后方可进行生产。设立外商投资复制单位，除由新闻出版行政部门批准外，还须报商务部审批并颁发外商投资企业批准证书。"},{"i":9,"n":"第九条","txt":"设立复制单位应当具备下列条件： （一）有复制单位的名称、章程； （二）有确定的业务范围； （三）有适应业务范围需要的生产经营场所和必要的资金、设备等生产经营条件； （四）有适应业务范围需要的组织机构和人员； （五）有关法律、行政法规规定的其他条件。 审批设立复制单位，除依照前款规定外，还应当符合国家有关复制单位总量、结构和布局的规划。"},{"i":10,"n":"第十条","txt":"设立复制单位，应当向所在地省级新闻出版行政部门提出申请，并提交下列申请文件： （一）按要求填写的申请表； （二）企业章程； （三）可行性研究报告； （四）法定代表人或者主要负责人的身份证明和履历证明； （五）注册资本数额、来源及性质证明； （六）经营场所和必备的生产条件证明； （七）新设立企业的，须提交工商部门核发的企业名称预先核准通知书。"},{"i":11,"n":"第十一条","txt":"申请设立只读类光盘复制单位的，由所在地省级新闻出版行政部门审核同意后，报新闻出版总署审批，并提交省级新闻出版行政部门的初审文件和本办法第十条规定的申请文件。新闻出版总署应自受理之日起60日内作出批准或不批准的决定，并由省级新闻出版行政部门通知申请人；不批准的，应当说明理由。 申请设立可录类光盘生产单位和磁带磁盘复制单位的，省级新闻出版行政部门应自受理之日起20日内作出批准或不批准的决定，并通知申请人；不批准的，应当说明理由。"},{"i":12,"n":"第十二条","txt":"国家允许设立外商投资可录类光盘生产单位，允许设立中外合资经营、中外合作经营只读类光盘和磁带磁盘复制单位，但中方必须控股或占主导地位。国家禁止设立外商独资只读类光盘和磁带磁盘复制单位。"},{"i":13,"n":"第十三条","txt":"经新闻出版行政部门批准设立的复制单位，其复制生产设备安装调试完毕，经所在地省级新闻出版行政部门验收合格并发给复制经营许可证后，方可投产。 复制单位应当在60日内持新闻出版行政部门有关批准文件或复制经营许可证到所在地工商行政部门办理登记手续。"},{"i":14,"n":"第十四条","txt":"复制单位申请兼营或者变更业务范围，或者兼并其他复制单位，或者因合并、分立而设立新的复制单位，应当依照本办法第九条至第十一条的规定办理审批登记手续。 复制单位变更名称、地址、法定代表人或者主要负责人或者终止复制经营活动的，应当到原登记的工商行政部门办理变更登记或者注销登记。由省级新闻出版行政部门批准设立的复制单位，应在工商机关登记后30日内直接向省级新闻出版行政部门备案；由新闻出版总署批准设立的复制单位，应在工商机关登记后20日内向省级新闻出版行政部门提交备案申请，省级新闻出版行政部门在接到申请之日起20日内向新闻出版总署备案；备案机关进行备案后变更或者注销复制经营许可证。"},{"i":15,"n":"第十五条","txt":"国家对光盘复制生产设备实行审批管理。 本办法所称的光盘复制生产设备是指从事光盘母盘刻录生产和子盘复制生产的设备。包括下列主要部分：用于光盘生产的金属母盘生产设备、精密注塑机、真空金属溅镀机、粘合机、保护胶涂覆机、染料层旋涂机、专用模具、盘面印刷机和光盘质量在线检测仪、离线检测仪等。 增加、进口、购买、变更光盘复制生产设备，须由新闻出版行政部门审批。其中增加、进口、购买、变更只读类光盘复制生产设备，由新闻出版总署审批；增加、进口、购买、变更可录类光盘生产设备，由所在地省级新闻出版行政部门审批，报新闻出版总署备案。"},{"i":16,"n":"第十六条","txt":"光盘复制生产设备进口管理流程依据新闻出版总署、商务部、海关总署有关规定执行。 禁止进口旧（二手）光盘复制生产设备，禁止旧（二手）光盘复制生产设备进入出口加工区、保税区等海关监管特殊区域。"},{"i":17,"n":"第十七条","txt":"被查处关闭光盘复制单位和被查缴的光盘复制生产设备的处理，由所在地省级新闻出版行政部门在本辖区内定向审批。需要跨省处理的，所在地省级新闻出版行政部门可报新闻出版总署在省际之间调剂，由同意接收或收购的光盘复制单位所在地省级新闻出版行政部门审批。接收或收购上述光盘复制生产设备的单位，必须是现有的合法光盘复制单位在许可经营的范围内接收或收购对应的生产设备，超出原许可经营范围的，应按本办法第十四条的规定办理审批手续。 被查处关闭光盘复制单位的光盘复制生产设备的价格，由买卖双方协商解决；被查缴的光盘复制生产设备的价格，由有关部门评估定价。 省级新闻出版行政部门应在审批后20日内向新闻出版总署备案。 申请单位向所在地省级新闻出版行政部门提出申请，经批准后，凭新闻出版行政部门的批准文件按上述程序办理有关设备的交接手续。"},{"i":18,"n":"第十八条","txt":"进口用于国产设备制造或者其他科研用途的光盘复制生产设备的，依照本办法第十五条、第十六条的规定办理相关手续。"},{"i":19,"n":"第十九条","txt":"国家对国产光盘复制生产设备的生产和销售实行备案管理。国产光盘复制生产设备生产和销售后，应分别在30日内向所在地省级新闻出版行政部门备案。备案内容包括生产和销售国产光盘复制生产设备的时间、设备名称、设备编号、设备数量和销售对象等。"},{"i":20,"n":"第二十条","txt":"从事只读类光盘复制，必须使用蚀刻有新闻出版总署核发的光盘来源识别码（SID码）的注塑模具。 光盘复制单位蚀刻SID码，应当向所在地省级新闻出版行政部门提出申请，由所在地省级新闻出版部门报新闻出版总署核发SID码；复制单位应于收到核发文件之日起20日内到指定刻码单位进行蚀刻，并在刻码后按有关规定向光盘生产源鉴定机构报送样盘。 刻码单位应将蚀刻SID码的情况通报新闻出版总署，光盘生产源鉴定机构应将样盘报送情况通报新闻出版总署。"},{"i":21,"n":"第二十一条","txt":"复制生产设备的技术、质量指标应当符合国家或者行业标准。"},{"i":22,"n":"第二十二条","txt":"复制单位必须严格按所批准的经营范围进行复制经营，不得超范围复制经营。"},{"i":23,"n":"第二十三条","txt":"国家对复制经营活动实行复制委托书制度。 复制单位接受委托复制音像制品或者电子出版物的，应当验证委托的出版单位盖章的复制委托书及其他法定文书。 接受委托复制属于非卖品或计算机软件的，应当验证经省级新闻出版行政部门核发并由委托单位盖章的复制委托书。"},{"i":24,"n":"第二十四条","txt":"复制单位接受委托复制境外产品的，应当事先将该样品及有关证明文件报经所在地省级新闻出版行政部门审核同意；复制的产品除样品外应当全部出境。 加工贸易项下只读类光盘的进出口管理，依照国家有关规定执行。"},{"i":25,"n":"第二十五条","txt":"复制单位不得接受非音像出版单位、电子出版物出版单位或者个人的委托复制经营性的音像制品、电子出版物；不得擅自复制音像制品、电子出版物、计算机软件、音像非卖品、电子出版物非卖品等。"},{"i":26,"n":"第二十六条","txt":"复制单位应该建立和保存完整清晰的复制业务档案，包括委托方按本办法有关规定所提交的复制委托书和其他法定文书以及复制样品、生产单据、发货记录等。保存期为2年，以备查验。"},{"i":27,"n":"第二十七条","txt":"复制单位对委托加工的产品除样品外必须全部交付委托单位，不得擅自加制，不得将委托单位提供的母盘、母带、样品等以任何方式转让或出售、复制给任何单位和个人。"},{"i":28,"n":"第二十八条","txt":"复制单位所复制的产品质量应符合国家或者行业标准。"},{"i":29,"n":"第二十九条","txt":"复制单位必须依照国家有关统计法规和规定按时填报有关统计报表，并由省级新闻出版行政部门审核汇总后上报新闻出版总署。"},{"i":30,"n":"第三十条","txt":"复制单位在复制生产过程中，如发现所复制的产品涉及本办法第三条内容或与委托证明文件所规定的内容不符，或复制的产品被新闻出版行政部门明令查禁、停止复制的，应立即停止复制，及时报告新闻出版行政部门，并按要求上缴或封存，不得拖延或隐匿。"},{"i":31,"n":"第三十一条","txt":"复制单位的法定代表人或者主要负责人应当接受所在地省级新闻出版行政部门组织的岗位培训。"},{"i":32,"n":"第三十二条","txt":"复制单位实行年度核验制度，年度核验每两年逢单数年进行一次。新闻出版总署负责指导年度核验，省级新闻出版行政部门负责对本行政区域内的复制单位实施年度核验。核验内容包括复制单位的登记项目、设立条件、经营状况、资产变化、技术设备、产品质量、人员培训、遵纪守法情况等。"},{"i":33,"n":"第三十三条","txt":"复制单位进行年度核验，应提交以下材料： （一）复制单位年度核验登记表； （二）复制单位按照年度核验要求提交的自检报告； （三）复制经营许可证、营业执照等有关企业证明文件的复印件。"},{"i":34,"n":"第三十四条","txt":"复制单位年度核验程序： （一）复制单位应于核验年度1月15日前向所在地省级新闻出版行政部门提交年度核验材料； （二）各省级新闻出版行政部门对本行政区域内复制单位情况进行全面审核，并于该年度2月底前完成年度核验工作。对符合要求的单位予以通过年度核验；对不符合要求的单位暂缓年度核验； （三）各省级新闻出版行政部门应于该年度3月底前将年度核验情况报送新闻出版总署备案。"},{"i":35,"n":"第三十五条","txt":"复制单位有下列情形之一的，暂缓年度核验： （一）不具备本办法第九条规定条件的； （二）因违反规定正在限期停业整顿的； （三）发现有违法行为应予处罚的； （四）经营恶化不能正常开展复制经营活动的； （五）存在其他违法嫌疑活动需要进一步核查的。 暂缓年度核验的期限由省级新闻出版行政部门确定，最长不得超过3个月。期间，省级新闻出版行政部门应当督促、指导暂缓年度核验的复制单位进行整改。暂缓年度核验期满，达到要求的复制单位予以通过年度核验；仍未达到要求的复制单位，所在地省级新闻出版行政部门提出注销登记意见，由原发证机关撤销复制经营许可证。"},{"i":36,"n":"第三十六条","txt":"不按规定参加年度核验的复制单位，经书面催告仍未参加年度核验的，所在地省级新闻出版行政部门提出注销登记意见，由原发证机关撤销复制经营许可证。"},{"i":37,"n":"第三十七条","txt":"对非法干扰、阻止和破坏复制经营活动的，县级以上新闻出版行政部门及其他有关部门，应当及时采取措施，予以制止。"},{"i":38,"n":"第三十八条","txt":"未经批准，擅自设立复制单位或擅自从事复制业务的，由新闻出版行政部门、工商行政部门依照法定职权予以取缔；触犯刑律的，依照刑法有关规定，依法追究刑事责任；尚不够刑事处罚的，没收违法经营的复制产品和违法所得以及进行违法活动的专用工具、设备；违法经营额1万元以上的，并处违法经营额5倍以上10倍以下的罚款；违法经营额不足1万元的，并处5万元以下的罚款。"},{"i":39,"n":"第三十九条","txt":"复制明知或者应知含有本办法第三条所列内容产品或其他非法出版物的，依照刑法有关规定，依法追究刑事责任；尚不够刑事处罚的，由新闻出版行政部门责令限期停业整顿，没收违法所得，违法经营额1万元以上的，并处违法经营额5倍以上10倍以下的罚款；违法经营额不足1万元的，可以并处5万元以下罚款；情节严重的，由批准设立的新闻出版行政部门吊销其复制经营许可证。如果当事人对所复制产品的来源作出说明、指认，经查证属实的，没收出版物、违法所得，可以减轻或者免除其他行政处罚。"},{"i":40,"n":"第四十条","txt":"有下列行为之一的，由新闻出版行政部门责令停止违法行为，给予警告，没收违法经营的产品和违法所得；违法经营额1万元以上的，并处违法经营额5倍以上10倍以下的罚款；违法经营额不足1万元的，并处1万元以上5万元以下罚款；情节严重的，并责令停业整顿或者由新闻出版总署吊销其复制经营许可证： （一）复制单位未依照本办法的规定验证复制委托书及其他法定文书的； （二）复制单位擅自复制他人的只读类光盘和磁带磁盘的； （三）复制单位接受非音像出版单位、电子出版物单位或者个人委托复制经营性的音像制品、电子出版物或者自行复制音像制品、电子出版物的； （四）复制单位未履行法定手续复制境外产品的，或者复制的境外产品没有全部运输出境的。"},{"i":41,"n":"第四十一条","txt":"有下列行为之一的，由新闻出版行政部门责令改正，给予警告；情节严重的，并责令停业整顿或者由新闻出版总署吊销其复制经营许可证： （一）复制单位变更名称、地址、法定代表人或者主要负责人、业务范围等，未依照本办法规定办理审批、备案手续的； （二）复制单位未依照本办法的规定留存备查的材料的； （三）光盘复制单位使用未蚀刻或者未按本办法规定蚀刻SID码的注塑模具复制只读类光盘的。"},{"i":42,"n":"第四十二条","txt":"有下列行为之一的，由新闻出版行政部门责令停止违法行为，给予警告，并处3万元以下的罚款： （一）光盘复制单位违反本办法第十五条的规定，未经审批，擅自增加、进口、购买、变更光盘复制生产设备的； （二）国产光盘复制生产设备的生产商未按本办法第十九条的要求报送备案的； （三）光盘复制单位未按本办法第二十条规定报送样盘的； （四）复制生产设备或复制产品不符合国家或行业标准的； （五）复制单位的有关人员未按本办法第三十一条参加岗位培训的； （六）违反本办法的其他行为。"},{"i":43,"n":"第四十三条","txt":"复制单位违反本办法被处以吊销许可证行政处罚的，其法定代表人或者主要负责人自许可证被吊销之日起10年内不得担任复制单位法定代表人或者主要负责人。"},{"i":44,"n":"第四十四条","txt":"本办法自2009年8月1日起施行。1996年2月1日新闻出版署发布的《音像制品复制管理办法》同时废止。其他有关复制管理规定，凡与本办法相抵触的，以本办法为准。"}],"baozhichubanguanliguiding":[{"i":1,"n":"第一条","txt":"为促进我国报业的发展与繁荣，规范报纸出版活动，加强报纸出版管理，根据国务院《出版管理条例》及相关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事报纸出版活动，适用本规定。 报纸由依法设立的报纸出版单位出版。报纸出版单位出版报纸，必须经新闻出版总署批准，持有国内统一连续出版物号，领取《报纸出版许可证》。 本规定所称报纸，是指有固定名称、刊期、开版，以新闻与时事评论为主要内容，每周至少出版一期的散页连续出版物。 本规定所称报纸出版单位，是指依照国家有关规定设立，经新闻出版总署批准并履行登记注册手续的报社。法人出版报纸不设立报社的，其设立的报纸编辑部视为报纸出版单位。"},{"i":3,"n":"第三条","txt":"报纸出版必须坚持马克思列宁主义、毛泽东思想、邓小平理论和“三个代表”重要思想，坚持正确的舆论导向和出版方向，坚持把社会效益放在首位、社会效益和经济效益相统一和贴近实际、贴近群众、贴近生活的原则，为建设中国特色社会主义营造良好氛围，丰富广大人民群众的精神文化生活。"},{"i":4,"n":"第四条","txt":"新闻出版总署负责全国报纸出版活动的监督管理工作，制定并实施全国报纸出版的总量、结构、布局的规划，建立健全报纸出版质量综合评估制度、报纸年度核验制度以及报纸出版退出机制等监督管理制度。 地方各级新闻出版行政部门负责本行政区域内的报纸出版活动的监督管理工作。"},{"i":5,"n":"第五条","txt":"报纸出版单位负责报纸的编辑、出版等报纸出版活动。 报纸出版单位合法的出版活动受法律保护。任何组织和个人不得非法干扰、阻止、破坏报纸的出版。"},{"i":6,"n":"第六条","txt":"新闻出版总署对为我国报业繁荣和发展做出突出贡献的报纸出版单位及个人实施奖励。"},{"i":7,"n":"第七条","txt":"报纸出版行业的社会团体按照其章程，在新闻出版行政部门的指导下，实行自律管理。"},{"i":8,"n":"第八条","txt":"创办报纸、设立报纸出版单位，应当具备下列条件： （一）有确定的、不与已有报纸重复的名称； （二）有报纸出版单位的名称、章程； （三）有符合新闻出版总署认定条件的主管、主办单位； （四）有确定的报纸出版业务范围； （五）有30万元以上的注册资本； （六）有适应业务范围需要的组织机构和符合国家规定资格条件的新闻采编专业人员； （七）有与主办单位在同一行政区域的固定的工作场所； （八）有符合规定的法定代表人或者主要负责人，该法定代表人或者主要负责人必须是在境内长久居住的中国公民； （九）法律、行政法规规定的其他条件。 除前款所列条件外，还须符合国家对报纸及报纸出版单位总量、结构、布局的规划。"},{"i":9,"n":"第九条","txt":"中央在京单位创办报纸并设立报纸出版单位，经主管单位同意后，由主办单位报新闻出版总署审批。 中国人民解放军和中国人民武装警察部队系统创办报纸并设立报纸出版单位，由中国人民解放军总政治部宣传部新闻出版局审核同意后报新闻出版总署审批。 其他单位创办报纸并设立报纸出版单位，经主管单位同意后，由主办单位向所在地省、自治区、直辖市新闻出版行政部门提出申请，省、自治区、直辖市新闻出版行政部门审核同意后，报新闻出版总署审批。"},{"i":10,"n":"第十条","txt":"两个以上主办单位合办报纸，须确定一个主要主办单位，并由主要主办单位提出申请。 报纸的主要主办单位应为其主管单位的隶属单位。报纸出版单位和主要主办单位须在同一行政区域。"},{"i":11,"n":"第十一条","txt":"创办报纸、设立报纸出版单位，由报纸出版单位的主办单位提出申请，并提交以下材料： （一）按要求填写的《报纸出版申请表》； （二）主办单位、主管单位的有关资质证明材料； （三）拟任报纸出版单位法定代表人或者主要负责人的简历、身份证明文件及国家有关部门颁发的职业资格证书； （四）新闻采编人员的职业资格证书； （五）报纸出版单位办报资金来源及数额的相关证明文件； （六）报纸出版单位的章程； （七）工作场所使用证明； （八）报纸出版可行性论证报告。"},{"i":12,"n":"第十二条","txt":"新闻出版总署自收到创办报纸、设立报纸出版单位申请之日起90日内，作出批准或者不批准的决定，并直接或者由省、自治区、直辖市新闻出版行政部门书面通知主办单位；不批准的，应当说明理由。"},{"i":13,"n":"第十三条","txt":"报纸主办单位应当自收到新闻出版总署批准决定之日起60日内办理注册登记手续： （一）持批准文件到所在地省、自治区、直辖市新闻出版行政部门领取并填写《报纸出版登记表》，经主管单位审核签章后，报所在地省、自治区、直辖市新闻出版行政部门； （二）《报纸出版登记表》一式五份，由报纸出版单位、主办单位、主管单位及省、自治区、直辖市新闻出版行政部门各存一份，另一份由省、自治区、直辖市新闻出版行政部门在15日内报送新闻出版总署备案； （三）省、自治区、直辖市新闻出版行政部门对《报纸出版登记表》审核无误后，在10日内向主办单位发放《报纸出版许可证》，并编入国内统一连续出版物号； （四）报纸出版单位持《报纸出版许可证》到工商行政管理部门办理登记手续，依法领取营业执照。"},{"i":14,"n":"第十四条","txt":"报纸主办单位自收到新闻出版总署的批准文件之日起60日内未办理注册登记手续，批准文件自行失效，登记机关不再受理登记，报纸主办单位须把有关批准文件缴回新闻出版总署。 报纸出版单位自登记之日起满90日未出版报纸的，由新闻出版总署撤销《报纸出版许可证》，并由原登记的新闻出版行政部门注销登记。 因不可抗力或者其他正当理由发生前款所列情形的，报纸出版单位的主办单位可以向原登记的新闻出版行政部门申请延期。"},{"i":15,"n":"第十五条","txt":"报社应当具备法人条件，经核准登记后，取得法人资格，以其全部法人财产独立承担民事责任。 报纸编辑部不具有法人资格，其民事责任由其主办单位承担。"},{"i":16,"n":"第十六条","txt":"报纸出版单位变更名称、合并或者分立，改变资本结构，出版新的报纸，依照本规定第九条至第十三条的规定办理审批、登记手续。"},{"i":17,"n":"第十七条","txt":"报纸变更名称、主办单位、主管单位、刊期、业务范围，依照本规定第九条至第十三条的规定办理审批、登记手续。 报纸变更刊期，新闻出版总署可以委托省、自治区、直辖市新闻出版行政部门审批。 本规定所称业务范围包括办报宗旨、文种。"},{"i":18,"n":"第十八条","txt":"报纸变更开版，经主办单位审核同意后，由报纸出版单位报所在地省、自治区、直辖市新闻出版行政部门批准。"},{"i":19,"n":"第十九条","txt":"报纸出版单位变更单位地址、法定代表人或者主要负责人、报纸承印单位，经其主办单位审核同意后，由报纸出版单位在15日内向所在地省、自治区、直辖市新闻出版行政部门备案。"},{"i":20,"n":"第二十条","txt":"报纸休刊连续超过10日的，报纸出版单位须向所在地省、自治区、直辖市新闻出版行政部门办理休刊备案手续，说明休刊理由和休刊期限。 报纸休刊时间不得超过180日。报纸休刊超过180日仍不能正常出版的，由新闻出版总署撤销《报纸出版许可证》，并由所在地省、自治区、直辖市新闻出版行政部门注销登记。"},{"i":21,"n":"第二十一条","txt":"报纸出版单位终止出版活动的，经主管单位同意后，由主办单位向所在地省、自治区、直辖市新闻出版行政部门办理注销登记，并由省、自治区、直辖市新闻出版行政部门报新闻出版总署备案。"},{"i":22,"n":"第二十二条","txt":"报纸注销登记，以同一名称设立的报纸出版单位须与报纸同时注销，并到原登记的工商行政管理部门办理注销登记。 注销登记的报纸和报纸出版单位不得再以该名称从事出版、经营活动。"},{"i":23,"n":"第二十三条","txt":"中央报纸出版单位组建报业集团，由新闻出版总署批准；地方报纸出版单位组建报业集团，向所在地省、自治区、直辖市新闻出版行政部门提出申请，经审核同意后，报新闻出版总署批准。"},{"i":24,"n":"第二十四条","txt":"报纸出版实行编辑责任制度，保障报纸刊载内容符合国家法律、法规的规定。"},{"i":25,"n":"第二十五条","txt":"报纸不得刊载《出版管理条例》和其他有关法律、法规以及国家规定的禁止内容。"},{"i":26,"n":"第二十六条","txt":"报纸开展新闻报道必须坚持真实、全面、客观、公正的原则，不得刊载虚假、失实报道。 报纸刊载虚假、失实报道，致使公民、法人或者其他组织的合法权益受到侵害的，其出版单位应当公开更正，消除影响，并依法承担相应民事责任。 报纸刊载虚假、失实报道，致使公民、法人或者其他组织的合法权益受到侵害的，当事人有权要求更正或者答辩，报纸应当予以发表；拒绝发表的，当事人可以向人民法院提出诉讼。 报纸因刊载虚假、失实报道而发表的更正或者答辩应自虚假、失实报道发现或者当事人要求之日起，在其最近出版的一期报纸的相同版位上发表。 报纸刊载虚假或者失实报道，损害公共利益的，新闻出版总署或者省、自治区、直辖市新闻出版行政部门可以责令该报纸出版单位更正。"},{"i":27,"n":"第二十七条","txt":"报纸发表或者摘转涉及国家重大政策、民族宗教、外交、军事、保密等内容，应严格遵守有关规定。 报纸转载、摘编互联网上的内容，必须按照有关规定对其内容进行核实，并在刊发的明显位置标明下载文件网址、下载日期等。"},{"i":28,"n":"第二十八条","txt":"报纸发表新闻报道，必须刊载作者的真实姓名。"},{"i":29,"n":"第二十九条","txt":"报纸出版质量须符合国家标准和行业标准。报纸使用语言文字须符合国家有关规定。"},{"i":30,"n":"第三十条","txt":"报纸出版须与《报纸出版许可证》的登记项目相符，变更登记项目须按本规定办理审批或者备案手续。"},{"i":31,"n":"第三十一条","txt":"报纸出版时须在每期固定位置标示以下版本记录： （一）报纸名称； （二）报纸出版单位、主办单位、主管单位名称； （三）国内统一连续出版物号； （四）总编辑（社长）姓名； （五）出版日期、总期号、版数、版序； （六）报纸出版单位地址、电话、邮政编码； （七）报纸定价（号外须注明“免费赠阅”字样）； （八）印刷单位名称、地址； （九）广告经营许可证号； （十）国家规定的涉及公共利益或者行业标准的其他标识。"},{"i":32,"n":"第三十二条","txt":"一个国内统一连续出版物号只能对应出版一种报纸，不得用同一国内统一连续出版物号出版不同版本的报纸。 出版报纸地方版、少数民族文字版、外文版等不同版本（文种）的报纸，须按创办新报纸办理审批手续。"},{"i":33,"n":"第三十三条","txt":"同一种报纸不得以不同开版出版。 报纸所有版页须作为一个整体出版发行，各版页不得单独发行。"},{"i":34,"n":"第三十四条","txt":"报纸专版、专刊的内容应与报纸的宗旨、业务范围相一致，专版、专刊的刊头字样不得明显于报纸名称。"},{"i":35,"n":"第三十五条","txt":"报纸在正常刊期之外可出版增期。出版增期应按变更刊期办理审批手续。 增期的内容应与报纸的业务范围相一致；增期的开版、文种、发行范围、印数应与主报一致，并随主报发行。"},{"i":36,"n":"第三十六条","txt":"报纸出版单位因重大事件可出版号外；出版号外须在报头注明“号外”字样，号外连续出版不得超过3天。 报纸出版单位须在号外出版后15日内向所在地省、自治区、直辖市新闻出版行政部门备案，并提交所有号外样报。"},{"i":37,"n":"第三十七条","txt":"报纸出版单位不得出卖、出租、转让本单位名称及所出版报纸的刊号、名称、版面，不得转借、转让、出租和出卖《报纸出版许可证》。"},{"i":38,"n":"第三十八条","txt":"报纸刊登广告须在报纸明显位置注明“广告”字样，不得以新闻形式刊登广告。 报纸出版单位发布广告应依据法律、行政法规查验有关证明文件，核实广告内容，不得刊登有害的、虚假的等违法广告。 报纸的广告经营者限于在合法授权范围内开展广告经营、代理业务，不得参与报纸的采访、编辑等出版活动。"},{"i":39,"n":"第三十九条","txt":"报纸出版单位不得在报纸上刊登任何形式的有偿新闻。 报纸出版单位及其工作人员不得利用新闻报道牟取不正当利益，不得索取、接受采访报道对象及其利害关系人的财物或者其他利益。"},{"i":40,"n":"第四十条","txt":"报纸采编业务和经营业务必须严格分开。 新闻采编业务部门及其工作人员不得从事报纸发行、广告等经营活动；经营部门及其工作人员不得介入新闻采编业务。"},{"i":41,"n":"第四十一条","txt":"报纸出版单位的新闻采编人员从事新闻采访活动，必须持有新闻出版总署统一核发的新闻记者证，并遵守新闻出版总署《新闻记者证管理办法》的有关规定。"},{"i":42,"n":"第四十二条","txt":"报纸出版单位根据新闻采访工作的需要，可以依照新闻出版总署《报社记者站管理办法》设立记者站，开展新闻业务活动。"},{"i":43,"n":"第四十三条","txt":"报纸出版单位不得以不正当竞争行为或者方式开展经营活动，不得利用权力摊派发行报纸。"},{"i":44,"n":"第四十四条","txt":"报纸出版单位须遵守国家统计法规，依法向新闻出版行政部门报送统计资料。 报纸出版单位应配合国家认定的出版物发行数据调查机构进行报纸发行量数据调查，提供真实的报纸发行数据。"},{"i":45,"n":"第四十五条","txt":"报纸出版单位须按照国家有关规定向国家图书馆、中国版本图书馆和新闻出版总署以及所在地省、自治区、直辖市新闻出版行政部门缴送报纸样本。"},{"i":46,"n":"第四十六条","txt":"报纸出版活动的监督管理实行属地原则。 省、自治区、直辖市新闻出版行政部门依法负责本行政区域报纸和报纸出版单位的登记、年度核验、质量评估、行政处罚等工作，对本行政区域的报纸出版活动进行监督管理。 其他地方新闻出版行政部门依法对本行政区域内报纸出版单位及其报纸出版活动进行监督管理。"},{"i":47,"n":"第四十七条","txt":"报纸出版管理实施报纸出版事后审读制度、报纸出版质量评估制度、报纸出版年度核验制度和报纸出版从业人员资格管理制度。 报纸出版单位应当按照新闻出版总署的规定，将从事报纸出版活动的情况向新闻出版行政部门提出书面报告。"},{"i":48,"n":"第四十八条","txt":"新闻出版总署负责全国报纸审读工作。地方各级新闻出版行政部门负责对本行政区域内出版的报纸进行审读。下级新闻出版行政部门要定期向上一级新闻出版行政部门提交审读报告。 主管单位须对其主管的报纸进行审读，定期向所在地新闻出版行政部门报送审读报告。 报纸出版单位应建立报纸阅评制度，定期写出阅评报告。新闻出版行政部门根据管理工作需要，可以随时调阅、检查报纸出版单位的阅评报告。"},{"i":49,"n":"第四十九条","txt":"新闻出版总署制定报纸出版质量综合评估标准体系，对报纸出版质量进行全面评估。 经报纸出版质量综合评估，报纸出版质量未达到规定标准或者不能维持正常出版活动的，由新闻出版总署撤销《报纸出版许可证》，所在地省、自治区、直辖市新闻出版行政部门注销登记。"},{"i":50,"n":"第五十条","txt":"省、自治区、直辖市新闻出版行政部门负责对本行政区域的报纸出版单位实施年度核验。年度核验内容包括报纸出版单位及其所出版报纸登记项目、出版质量、遵纪守法情况、新闻记者证和记者站管理等。"},{"i":51,"n":"第五十一条","txt":"年度核验按照以下程序进行： （一）报纸出版单位提出年度自检报告，填写由新闻出版总署统一印制的《报纸出版年度核验表》，经报纸主办单位、主管单位审核盖章后，连同核验之日前连续出版的30期样报，在规定时间内报所在地省、自治区、直辖市新闻出版行政部门； （二）省、自治区、直辖市新闻出版行政部门对报纸出版单位自检报告、《报纸出版年度核验表》等送检材料审核查验； （三）经核验符合规定标准的，省、自治区、直辖市新闻出版行政部门在其《报纸出版许可证》上加盖年度核验章；《报纸出版许可证》上加盖年度核验章即为通过年度核验，报纸出版单位可以继续从事报纸出版活动； （四）省、自治区、直辖市新闻出版行政部门自完成报纸出版年度核验工作后的30日内，向新闻出版总署提交报纸年度核验工作报告。"},{"i":52,"n":"第五十二条","txt":"有下列情形之一的，暂缓年度核验： （一）正在限期停刊整顿的； （二）经审核发现有违法情况应予处罚的； （三）主管单位、主办单位未履行管理责任，导致报纸出版管理混乱的； （四）存在其他违法嫌疑需要进一步核查的。 暂缓年度核验的期限由省、自治区、直辖市新闻出版行政部门确定，报新闻出版总署备案。缓验期满，按照本规定第五十条、第五十一条重新办理年度核验。"},{"i":53,"n":"第五十三条","txt":"有下列情形之一的，不予通过年度核验： （一）违法行为被查处后拒不改正或者没有明显整改效果的； （二）报纸出版质量长期达不到规定标准的； （三）经营恶化已经资不抵债的； （四）已经不具备本规定第八条规定条件的。 不予通过年度核验的，由新闻出版总署撤销《报纸出版许可证》，所在地省、自治区、直辖市新闻出版行政部门注销登记。 未通过年度核验的，报纸出版单位自第二年起停止出版该报纸。"},{"i":54,"n":"第五十四条","txt":"《报纸出版许可证》加盖年度核验章后方可继续使用。有关部门在办理报纸出版、印刷、发行等手续时，对未加盖年度核验章的《报纸出版许可证》不予采用。 不按规定参加年度核验的报纸出版单位，经催告仍未参加年度核验的，由新闻出版总署撤销《报纸出版许可证》，所在地省、自治区、直辖市新闻出版行政部门注销登记。"},{"i":55,"n":"第五十五条","txt":"年度核验结果，核验机关可以向社会公布。"},{"i":56,"n":"第五十六条","txt":"报纸出版从业人员，应具备国家规定的新闻出版职业资格条件。"},{"i":57,"n":"第五十七条","txt":"报纸出版单位的社长、总编辑须符合国家规定的任职资格和条件。 报纸出版单位的社长、总编辑须参加新闻出版行政部门组织的岗位培训。 报纸出版单位的新任社长、总编辑须经过岗位培训合格后才能上岗。"},{"i":58,"n":"第五十八条","txt":"报纸出版单位违反本规定的，新闻出版行政部门视其情节轻重，可采取下列行政措施： （一）下达警示通知书； （二）通报批评； （三）责令公开检讨； （四）责令改正； （五）责令停止印制、发行报纸； （六）责令收回报纸； （七）责成主办单位、主管单位监督报纸出版单位整改。 警示通知书由新闻出版总署制定统一格式，由新闻出版总署或者省、自治区、直辖市新闻出版行政部门下达给违法的报纸出版单位，并抄送违法报纸出版单位的主办单位及其主管单位。 本条所列行政措施可以并用。"},{"i":59,"n":"第五十九条","txt":"未经批准，擅自设立报纸出版单位，或者擅自从事报纸出版业务，假冒报纸出版单位名称或者伪造、假冒报纸名称出版报纸的，依照《出版管理条例》第五十五条处罚。"},{"i":60,"n":"第六十条","txt":"出版含有《出版管理条例》和其他有关法律、法规以及国家规定禁载内容报纸的，依照《出版管理条例》第五十六条处罚。"},{"i":61,"n":"第六十一条","txt":"报纸出版单位违反本规定第三十七条的，依照《出版管理条例》第六十条处罚。 报纸出版单位允许或者默认广告经营者参与报纸的采访、编辑等出版活动，按前款处罚。"},{"i":62,"n":"第六十二条","txt":"报纸出版单位有下列行为之一的，依照《出版管理条例》第六十一条处罚： （一）报纸出版单位变更名称、合并或者分立，改变资本结构，出版新的报纸，未依照本规定办理审批手续的； （二）报纸变更名称、主办单位、主管单位、刊期、业务范围、开版，未依照本规定办理审批手续的； （三）报纸出版单位未依照本规定缴送报纸样本的。"},{"i":63,"n":"第六十三条","txt":"报纸出版单位有下列行为之一的，由新闻出版总署或者省、自治区、直辖市新闻出版行政部门给予警告，并处3万元以下罚款： （一）报纸出版单位变更单位地址、法定代表人或者主要负责人、承印单位，未按照本规定第十九条报送备案的； （二）报纸休刊，未按照本规定第二十条报送备案的； （三）刊载损害公共利益的虚假或者失实报道，拒不执行新闻出版行政部门更正命令的； （四）在其报纸上发表新闻报道未登载作者真实姓名的； （五）违反本规定第二十七条发表或者摘转有关文章的； （六）未按照本规定第三十一条刊登报纸版本记录的； （七）违反本规定第三十二条，“一号多版”的； （八）违反本规定第三十三条，出版不同开版的报纸或者部分版页单独发行的； （九）违反本规定关于出版报纸专版、专刊、增期、号外的规定的； （十）报纸刊登广告未在明显位置注明“广告”字样，或者以新闻形式刊登广告的； （十一）刊登有偿新闻或者违反本规定第三十"},{"i":64,"n":"第六十四条","txt":"报纸出版单位新闻采编人员违反新闻记者证的有关规定，依照新闻出版总署《新闻记者证管理办法》的规定处罚。"},{"i":65,"n":"第六十五条","txt":"报纸出版单位违反报社记者站的有关规定，依照新闻出版总署《报社记者站管理办法》的规定处罚。"},{"i":66,"n":"第六十六条","txt":"对报纸出版单位做出行政处罚，应告知其主办单位和主管单位，可以通过媒体向社会公布。 对报纸出版单位做出行政处罚，新闻出版行政部门可以建议其主办单位或者主管单位对直接责任人和主要负责人予以行政处分或者调离岗位。"},{"i":67,"n":"第六十七条","txt":"以非新闻性内容为主或者出版周期超过一周，持有国内统一连续出版物号的其他散页连续出版物，也适用本规定。"},{"i":68,"n":"第六十八条","txt":"本规定施行后，新闻出版署《报纸管理暂行规定》同时废止，此前新闻出版行政部门对报纸出版活动的其他规定，凡与本规定不一致的，以本规定为准。"},{"i":69,"n":"第六十九条","txt":"本规定自2005年12月1日起施行。"}],"xinwenchubantongjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为科学、有效、规范地组织新闻出版统计工作，保障新闻出版（版权）统计资料的真实性、准确性、完整性和及时性，充分发挥统计工作在服务新闻出版行业发展中的重要作用，根据《中华人民共和国统计法》（以下简称《统计法》）及其实施细则的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"新闻出版统计是指各级新闻出版行政主管部门为满足新闻出版行业管理工作需要，依法对新闻出版统计调查对象组织实施的各项统计活动。 新闻出版统计调查对象包括各级新闻出版行政主管部门、从事新闻出版（版权）活动的企业事业单位、其他组织以及个体工商户等。"},{"i":3,"n":"第三条","txt":"新闻出版统计的基本任务是对新闻出版（版权）活动的相关情况进行统计调查和统计分析，提供统计资料和统计咨询意见，实行统计监督。"},{"i":4,"n":"第四条","txt":"新闻出版统计调查对象必须依照有关统计法律法规和本办法的规定，提供新闻出版统计调查所需的统计资料，不得提供不真实或者不完整的统计资料，不得迟报、拒报统计资料。"},{"i":5,"n":"第五条","txt":"新闻出版统计工作实行统一管理、分级负责。 国家新闻出版广电总局是新闻出版统计工作的主管部门，在国家统计局的业务指导下，对新闻出版统计工作实行统一管理和组织协调。 地方各级新闻出版行政主管部门，在上级新闻出版行政主管部门和同级人民政府统计机构的业务指导下，负责本行政区域内的新闻出版统计工作。"},{"i":6,"n":"第六条","txt":"各级新闻出版行政主管部门应加强对新闻出版统计工作的领导，健全统计机构，充实专职统计人员，建立统计工作责任机制，定期检查并监督统计法律法规的执行情况。"},{"i":7,"n":"第七条","txt":"各级新闻出版行政主管部门应将必要的统计工作经费列入单位相应年度财政预算。"},{"i":8,"n":"第八条","txt":"各级新闻出版行政主管部门应重视统计信息化建设，为新闻出版统计工作提供必要的技术装备和其他各项条件，推进统计信息搜集、处理、传输、共享、存储技术和统计数据库体系的现代化。"},{"i":9,"n":"第九条","txt":"国家新闻出版广电总局制定全国新闻出版统计调查项目，并依法定程序报国家统计局审批或备案。"},{"i":10,"n":"第十条","txt":"地方新闻出版行政主管部门可以制定补充性地方新闻出版统计调查项目，经上级新闻出版行政主管部门同意后，报同级人民政府统计机构审批。 补充性地方新闻出版统计调查项目，不得与国家统计调查项目和上级新闻出版统计调查项目重复、矛盾。"},{"i":11,"n":"第十一条","txt":"各级新闻出版行政主管部门制定统计调查项目，应当同时制定该项目的统计调查制度，并依照本办法第九条、第十条的有关规定一并报经审批或者备案。 统计调查制度应当对调查目的、调查内容、调查方法、调查对象、调查组织方式、调查表式、统计资料的报送和公布等作出规定。"},{"i":12,"n":"第十二条","txt":"各级新闻出版行政主管部门制发的统计调查表应由本部门统计机构统一编号，并标明表号、制定机关、批准或备案文号、有效期限等法定标识。"},{"i":13,"n":"第十三条","txt":"新闻出版统计调查对象应当根据依法制定的新闻出版统计调查制度，设置原始记录、统计台账，建立健全统计资料的审核、签署、交接、归档等管理制度。"},{"i":14,"n":"第十四条","txt":"各级新闻出版行政主管部门应当结合年度核验、行政记录等方式，开展新闻出版统计调查，做好数据搜集、审核、汇总、报送工作；建立健全新闻出版统计调查质量控制体系，保证统计资料的完整性和准确性。"},{"i":15,"n":"第十五条","txt":"地方新闻出版行政主管部门向上级主管部门报送统计数据，须经本部门主管领导审核、签署，并对基层数据上报情况及本期数据中异常变动情况予以说明。省级新闻出版行政主管部门每年报送年度统计资料后，应向国家新闻出版广电总局报送本地区年度统计分析报告。"},{"i":16,"n":"第十六条","txt":"统计数据报出后，如发现内容有误，报送单位应按照国家有关规定及时进行更正并书面说明理由。"},{"i":17,"n":"第十七条","txt":"新闻出版（版权）统计资料实行分级管理。全国新闻出版（版权）统计资料由国家新闻出版广电总局统一管理；地方新闻出版（版权）统计资料由各地新闻出版行政主管部门统一管理。"},{"i":18,"n":"第十八条","txt":"新闻出版行政主管部门应严格按照国家档案管理制度和保密制度的有关要求，建立健全新闻出版（版权）统计资料档案制度，加强保密管理，妥善保管、调用和移交统计资料。"},{"i":19,"n":"第十九条","txt":"新闻出版行政主管部门应当依法建立健全统计资料公布制度，按照法律法规和国家有关规定以及依法制定的统计调查制度公布新闻出版（版权）统计资料。 全国新闻出版（版权）统计资料，由国家新闻出版广电总局负责审核、公布；各地新闻出版（版权）统计资料，由地方新闻出版行政主管部门负责审核、公布。"},{"i":20,"n":"第二十条","txt":"尚未公布的新闻出版（版权）统计资料，不得擅自对外提供，不得公开使用。"},{"i":21,"n":"第二十一条","txt":"新闻出版行政主管部门根据统计工作的需要，设立承担综合统计职能的机构，指定统计负责人和统计人员，统一管理新闻出版统计工作；从事新闻出版（版权）活动的企业事业单位和其他组织等新闻出版统计调查对象，根据需要设立统计机构或者指定统计人员，完成新闻出版统计工作。"},{"i":22,"n":"第二十二条","txt":"国家新闻出版广电总局承担新闻出版综合统计职能的机构履行以下职责： （一）拟定全国新闻出版统计工作规划、统计调查制度、调查任务、调查方案和相关统计标准，并组织实施； （二）负责与同级有关部门的统计业务合作；组织、指导、协调本部门内非综合统计职能机构的统计工作，审核本部门内非综合统计职能机构拟定的统计调查方案；组织、指导、协调地方各级新闻出版行政主管部门的新闻出版统计工作，审核地方各级新闻出版行政主管部门拟定的补充性新闻出版统计调查制度； （三）组织指导新闻出版统计调查方法和统计管理制度改革的研究、试点和推广； （四）开展全国新闻出版行业情况的统计分析、监测评价； （五）统一管理、审定、公布全国新闻出版（版权）统计资料； （六）会同相关部门，组织、指导全国新闻出版（版权）统计人员的业务培训和科学研究交流； （七）统一规划全国新闻出版统计网络信息系统建设，管理、开发和利用全国新闻出版统计数据"},{"i":23,"n":"第二十三条","txt":"地方新闻出版行政主管部门承担综合统计职能的机构履行以下职责： （一）完成上级新闻出版行政主管部门部署的统计调查任务；组织、实施补充性新闻出版统计调查项目；审核并按时向上级新闻出版行政主管部门报送本地区的统计数据、统计报告和其他统计资料； （二）负责与本地区同级有关部门的统计业务合作；组织、指导、协调本部门内非综合统计职能机构的统计工作，审核本部门内非综合统计职能机构拟定的统计调查方案；组织、指导、协调下级新闻出版行政主管部门的统计工作； （三）贯彻执行统计法律、法规、规章，实施国家统计标准和补充性的新闻出版统计标准； （四）开展本地区的新闻出版行业情况的统计分析、监督评价； （五）统一管理、审定、公布本地区的新闻出版（版权）统计资料； （六）会同相关部门，组织本地区新闻出版（版权）统计人员的业务培训； （七）按照上级新闻出版行政主管部门的统一规划,组织本地区新闻出版统计网络信息系统建设"},{"i":24,"n":"第二十四条","txt":"中国新闻出版研究院在国家新闻出版广电总局的领导下，根据有关统计制度和调查计划、方案，履行以下职责： （一）统计数据的搜集、审核、汇总、报送； （二）新闻出版（版权）统计资料汇编和产业分析报告等统计资料的编制、撰写； （三）新闻出版统计网络信息系统的建设和应用； （四）面向社会的统计信息咨询服务； （五）境外新闻出版信息的搜集； （六）有关统计档案的管理。"},{"i":25,"n":"第二十五条","txt":"新闻出版统计机构和统计人员依法独立行使以下职权： （一）统计调查权：调查、搜集有关资料，召开有关调查会议，检查与统计资料有关的各种原始记录和统计台账，要求更正不实的统计数据。 （二）统计报告权：将统计调查所得资料和情况进行整理、分析，及时如实地向上级机关和统计部门提出统计报告。任何单位或个人不得阻挠、扣压统计报告，不得伪造和篡改统计资料。 （三）统计监督权：根据统计调查和统计分析，对新闻出版工作进行统计监督，指出存在的问题，提出改进的建议。有关部门对统计机构、统计人员指出的问题和提出的建议，应当及时予以研究处理。"},{"i":26,"n":"第二十六条","txt":"新闻出版统计机构和统计人员应坚持实事求是，恪守职业道德，依法履行职责，如实搜集、录入、审核、报送统计资料，不得伪造、篡改统计资料，不得以任何方式要求任何单位和个人提供不真实的统计资料，有权拒绝、抵制有关强令或者授意篡改统计资料、编造虚假数据的行为，对其负责搜集、审核、录入的统计资料与统计调查对象报送的统计资料的一致性负责。"},{"i":27,"n":"第二十七条","txt":"新闻出版行政主管部门、从事新闻出版（版权）活动的单位负责人负有督促统计机构和统计人员执行《统计法》以及各种规章制度的职责；不得自行修改统计机构和统计人员提供的新闻出版（版权）统计资料，不得以任何方式要求统计机构、统计人员及其他机构、人员伪造、篡改统计资料；不得对依法履行职责或者拒绝、抵制统计违法行为的统计人员打击报复。"},{"i":28,"n":"第二十八条","txt":"新闻出版行政主管部门、新闻出版统计机构和统计人员对在统计工作中知悉的国家秘密、商业秘密和个人信息，应当予以保密，对统计调查中获得的能够识别和推断单个统计调查对象身份的资料应当保密，不得对外提供泄露。"},{"i":29,"n":"第二十九条","txt":"各级新闻出版行政主管部门的统计人员应保持相对稳定。统计人员因工作需要调离统计岗位时，应选派有能力承担规定职责的人员接替，先补后调，办清交接手续，并及时告知上级新闻出版行政主管部门。对不称职、不合格的统计人员应及时进行调整。"},{"i":30,"n":"第三十条","txt":"各级新闻出版行政主管部门统计机构依法对下级新闻出版行政主管部门、统计调查对象的统计工作进行监督、检查和考核。 新闻出版统计检查的内容包括：统计法律法规和规章制度的执行情况，统计机构和统计人员的配置情况，统计资料搜集和报送的真实、准确、及时、完整程度等，统计资料的公布情况，统计信息化建设情况，对下级单位和统计调查对象统计工作监督、检查和考核的执行情况，以及其他与统计工作相关的情况。"},{"i":31,"n":"第三十一条","txt":"各级新闻出版行政主管部门、统计调查对象应配合上级新闻出版行政主管部门的检查工作。任何单位、个人不得干扰和妨碍统计人员执法检查和作出检查结论。"},{"i":32,"n":"第三十二条","txt":"新闻出版行政主管部门对有下列情形之一的统计机构或统计人员，按照有关规定给予表彰或奖励： （一）忠于职守，执行统计法律、法规和规章表现突出的； （二）在改进和完善新闻出版统计制度、统计调查方法等方面有重要贡献的； （三）在完成规定的新闻出版统计调查任务，保障新闻出版（版权）统计资料准确性、及时性方面作出显著成绩的； （四）在进行新闻出版统计分析、监督方面取得突出成绩的； （五）在新闻出版统计工作中运用和推广现代信息技术有显著效果的； （六）在新闻出版统计科学研究方面有所创新、作出重要贡献的。"},{"i":33,"n":"第三十三条","txt":"各级新闻出版行政主管部门或者有关部门、单位的负责人有下列行为之一的，由上级新闻出版行政主管部门予以通报，建议任免机关或监察机关等有关部门依法给予处分；并由统计机构依照《统计法》第三十七条予以处理： （一）自行修改统计资料、编造虚假统计数据的； （二）要求统计机构、统计人员或者其他机构、人员伪造、篡改统计资料的； （三）对依法履行职责或者拒绝、抵制统计违法行为的统计人员打击报复的； （四）对本部门、本单位发生的严重统计违法行为失察的。"},{"i":34,"n":"第三十四条","txt":"各级新闻出版行政主管部门在组织实施统计调查活动中有下列行为之一的，由上级新闻出版行政主管部门责令改正，予以通报，对直接负责的主管人员和其他直接责任人员，建议任免机关或监察机关等有关部门依法给予处分；并由统计机构依照《统计法》第三十八条予以处理： （一）未经批准擅自组织实施统计调查的； （二）未经批准擅自变更统计调查制度的内容的； （三）伪造、篡改统计资料的； （四）要求统计调查对象或者其他机构、人员提供不真实的统计资料的； （五）未按照统计调查制度的规定报送有关资料的。"},{"i":35,"n":"第三十五条","txt":"各级新闻出版行政主管部门有下列行为之一的，由上级新闻出版行政主管部门予以通报，对直接负责的主管人员和其他直接责任人员，建议任免机关或监察机关等有关部门依法给予处分；并由统计机构依照《统计法》第三十九条予以处理： （一）违法公布统计资料的； （二）泄露统计调查对象的商业秘密、个人信息或者提供、泄露在统计调查中获得的能够识别或者推断单个统计调查对象身份的资料的； （三）违反国家有关规定，造成统计资料毁损、灭失的。"},{"i":36,"n":"第三十六条","txt":"各级新闻出版行政主管部门、统计人员泄露国家秘密的，依法追究法律责任。"},{"i":37,"n":"第三十七条","txt":"新闻出版统计调查对象有下列行为之一的，由新闻出版行政主管部门责令改正，给予警告，可以予以通报，对其直接负责的主管人员和其他直接责任人员属于国家工作人员的，建议任免机关或监察机关等有关部门依法给予处分；并由统计机构依照《统计法》第四十一条予以处理： （一）拒绝提供统计资料或者经催报后仍未按时提供统计资料的； （二）提供不真实或者不完整的统计资料的； （三）拒绝、阻碍统计调查、统计检查的； （四）转移、隐匿、篡改、毁弃或者拒绝提供原始记录和凭证、统计台账、统计调查表及其他相关证明和资料的。"},{"i":38,"n":"第三十八条","txt":"作为新闻出版统计调查对象的国家机关、企业事业单位或者其他组织迟报统计资料，或者未按照国家有关规定设置原始记录、统计台账的，由上级或本级新闻出版行政主管部门责令改正，给予警告，可以予以通报；并由统计机构依照《统计法》第四十二条予以处理。"},{"i":39,"n":"第三十九条","txt":"违反本办法，利用虚假统计资料骗取荣誉称号、物质利益或者职务晋升的，依照《统计法》第四十五条予以处理。"},{"i":40,"n":"第四十条","txt":"违反本办法，构成犯罪的，依法追究刑事责任。"},{"i":41,"n":"第四十一条","txt":"本办法自2016年7月1日起施行。原新闻出版总署、国家统计局于2005年2月7日颁布的《新闻出版统计管理办法》同时废止。"}],"xinwenchubanhangyebiaozhunhuaguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强新闻出版行业标准化工作的管理，促进新闻出版业技术创新与发展，根据《中华人民共和国标准化法》等相关法律法规，结合新闻出版行业的实际情况，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事新闻出版行业标准化活动，适用本办法。"},{"i":3,"n":"第三条","txt":"新闻出版行业标准化工作全面落实国家标准化战略，以推动新闻出版技术进步，促进新闻出版业健康、有序发展为宗旨，贯彻协调统一、广泛参与、鼓励创新、国际接轨、支撑发展的标准化工作方针，坚持依法办事、科学公正、公开透明和协调推进的原则。"},{"i":4,"n":"第四条","txt":"新闻出版行业标准化工作的主要任务是在全行业开展标准的制定、修订、宣传、实施，运用标准化手段促进新闻出版行业的技术进步，提升新闻出版行业产品质量和服务质量。"},{"i":5,"n":"第五条","txt":"标准化是新闻出版行业科学发展的重要基础性工作，各级出版行政主管部门要加强对新闻出版行业标准化工作的领导和管理，并纳入新闻出版行业各级发展规划、计划和财政预算。"},{"i":6,"n":"第六条","txt":"新闻出版行业各单位不得无标准生产，应依法执行强制性标准，积极采用推荐性标准；鼓励研究国际标准和国外先进标准，结合我国国情和产业发展的需要，积极采用，制定相关标准。"},{"i":7,"n":"第七条","txt":"新闻出版广电总局统一管理新闻出版行业标准化工作，履行下列职责： （一）贯彻执行国家标准化工作的方针、政策和法律法规，制定、颁布新闻出版行业标准化工作相关规定，负责新闻出版行业标准化工作的宏观管理； （二）审批发布新闻出版行业标准化工作规划和工作计划； （三）负责新闻出版领域国家标准的申报； （四）负责新闻出版领域行业标准的批准发布，并报国家标准化主管部门备案； （五）受国家标准化主管部门委托，管理新闻出版领域的全国专业标准化技术委员会； （六）批准成立新闻出版领域的行业专业标准化技术委员会； （七）批准成立新闻出版领域标准注册管理机构； （八）审议、决定新闻出版行业标准化工作的其他重大事项。"},{"i":8,"n":"第八条","txt":"新闻出版广电总局标准化主管部门具体负责管理新闻出版行业标准化工作，履行下列职责： （一）负责标准化工作在新闻出版行业的贯彻实施，组织起草新闻出版行业标准化工作的相关规定，起草、实施新闻出版行业标准化工作规划和工作计划，建立和完善新闻出版行业标准化体系； （二）负责新闻出版行业标准化工作的日常管理与监督，负责与其他行业标准化工作的协调； （三）组织起草新闻出版领域国家标准； （四）审核和批准行业标准立项； （五）负责组织新闻出版领域相关标准的制定、修订、复审工作； （六）负责行业标准发布前的审核； （七）开展行业标准的动态维护和标准符合性测试与评估工作； （八）负责新闻出版领域的标准宣传、培训、实施，对标准贯彻实施情况进行监督检查； （九）组建和管理新闻出版专业标准化技术委员会，并指导其开展相关标准化工作； （十）组建和管理新闻出版领域标准注册管理机构； （十一）组织协调参加国际标准化组"},{"i":9,"n":"第九条","txt":"新闻出版广电总局有关业务部门履行下列职责： （一）贯彻执行有关标准化工作的方针、政策和法律法规； （二）在本部门业务范围内负责提出制定、修订标准的立项建议； （三）在本部门业务范围内负责标准的贯彻实施及监督检查； （四）协助新闻出版广电总局标准化主管部门开展标准化宣传、培训工作。"},{"i":10,"n":"第十条","txt":"各省、自治区、直辖市人民政府出版行政主管部门履行下列职责： （一）贯彻执行有关标准化工作的方针、政策和法律法规； （二）提出制定、修订标准的立项建议； （三）在本行政区域内负责标准的贯彻实施及监督检查； （四）对本行政区域内各新闻出版单位及相关行业协会、学术团体的标准化工作进行指导； （五）在本行政区域内协助开展新闻出版标准化宣传、培训工作。"},{"i":11,"n":"第十一条","txt":"新闻出版专业标准化技术委员会包括新闻出版领域的全国专业标准化技术委员会及行业专业标准化技术委员会，是由新闻出版广电总局归口管理的在本专业领域内从事全国性标准化工作的组织机构，按技术归口管理原则划分工作范围，履行下列职责： （一）贯彻执行有关标准化工作的方针、政策和法律法规； （二）研究起草本专业标准化工作规划，建立健全标准体系； （三）分析本专业领域的标准化工作需求，广泛征集标准立项建议，提出本专业领域的标准制定、修订计划项目； （四）按照各级标准化主管部门批准的标准制定、修订计划，组织本专业领域标准的制定和修订工作； （五）负责对组织起草的标准的专业内容和文本质量进行审查； （六）组织对本专业领域的标准进行复审； （七）组织开展标准宣传、培训、对外交流工作，协助开展对标准贯彻实施情况的检查工作，提供相关技术服务； （八）承办新闻出版广电总局标准化主管部门委托的其他工作。"},{"i":12,"n":"第十二条","txt":"新闻出版领域行业标准的制定、修订与发布应本着公开透明、科学合理、技术先进、协调配套、切实可行和符合经济社会发展需要的原则进行。 新闻出版领域国家标准的制定、修订与发布应遵循《国家标准管理办法》。"},{"i":13,"n":"第十三条","txt":"任何单位和个人均可向技术归口的新闻出版专业标准化技术委员会提出标准立项建议，所提立项建议没有技术归口管理的新闻出版专业标准化技术委员会时，可以向新闻出版广电总局标准化主管部门直接提出，由新闻出版广电总局标准化主管部门指定新闻出版专业标准化技术委员会负责接收。 立项建议应符合以下条件： （一）在新闻出版领域内，有制定基础、通用、方法、产品、技术、管理等各类标准以规范生产与管理的需求； （二）因现行标准不适用而应予以修订。"},{"i":14,"n":"第十四条","txt":"新闻出版领域行业标准制定、修订实行年度立项制度。新闻出版专业标准化技术委员会对立项建议进行论证通过后，于每年5月31日前向新闻出版广电总局标准化主管部门报送下一年度标准立项申请，申请立项应提供如下材料： （一）标准项目建议书； （二）标准草案或框架； （三）项目立项专家论证意见； （四）其他必要材料。"},{"i":15,"n":"第十五条","txt":"新闻出版广电总局标准化主管部门于每年7月31日前完成年度立项申请的审查，确定项目名称、项目归口管理的新闻出版专业标准化技术委员会、项目承担方等，并形成下一年度的新闻出版领域行业标准制定、修订计划，经公示后由新闻出版广电总局下达。"},{"i":16,"n":"第十六条","txt":"新闻出版广电总局标准化主管部门对列入新闻出版领域行业标准制定、修订计划中的标准制定、修订项目给予适当经费补贴。补贴经费的使用，须按新闻出版广电总局相关经费管理办法的规定专款专用。鼓励有条件的企业参与标准的制定、修订工作。"},{"i":17,"n":"第十七条","txt":"新闻出版领域行业标准制定、修订计划执行过程中，必要时可以对计划项目进行增补、调整或撤销。"},{"i":18,"n":"第十八条","txt":"项目承担方应在计划确定的时限内完成标准的起草工作。标准的起草应在广泛调研、深入研究、充分协调和试验验证的基础上，按照标准编写规则提出标准征求意见稿，并广泛征求意见。"},{"i":19,"n":"第十九条","txt":"项目承担方向项目归口管理的新闻出版专业标准化技术委员会秘书处提交项目送审材料，由秘书处对送审材料进行审核，确定能否提交审查，如未达到审查要求应退回项目承担方修改完善。 送审材料包括： （一）标准送审稿； （二）编制说明及有关附件； （三）征求意见汇总处理表及标准征求意见稿。"},{"i":20,"n":"第二十条","txt":"标准的审查由项目归口管理的新闻出版专业标准化技术委员会组织进行，由委员会秘书处召开专家审查会，对标准送审稿提出初步审查意见；初步审查通过后，由全体委员以会议审查或函审方式完成标准审查。"},{"i":21,"n":"第二十一条","txt":"标准的报批由项目归口管理的新闻出版专业标准化技术委员会向新闻出版广电总局标准化主管部门提出申请，应提交如下材料： （一）标准申报单； （二）标准报批稿； （三）编制说明及有关附件； （四）征求意见汇总处理表及标准送审稿； （五）审查会议纪要或函审结论表。"},{"i":22,"n":"第二十二条","txt":"新闻出版领域行业标准报批稿经新闻出版广电总局标准化主管部门审核通过后，统一编号，由新闻出版广电总局批准发布，并向国家标准化主管部门备案。"},{"i":23,"n":"第二十三条","txt":"新闻出版领域行业标准由新闻出版广电总局授权出版单位出版，相关费用从项目经费中支出。"},{"i":24,"n":"第二十四条","txt":"新闻出版领域行业标准由新闻出版广电总局负责解释。"},{"i":25,"n":"第二十五条","txt":"新闻出版领域强制性行业标准的代号为CY；推荐性行业标准的代号为CY/T；行业标准化指导性技术文件的代号为CY/Z。"},{"i":26,"n":"第二十六条","txt":"新闻出版领域标准实施后，新闻出版专业标准化技术委员会应根据新闻出版产业发展形势，结合新闻出版行业科学技术的发展及管理的需要适时组织复审，并形成复审报告，报新闻出版广电总局审批发布。复审周期一般不超过五年。"},{"i":27,"n":"第二十七条","txt":"对只有通过动态维护方式才能有效实施的标准，新闻出版广电总局在批准发布时指定其动态维护机构，由该机构组织技术专家负责该标准的动态维护。"},{"i":28,"n":"第二十八条","txt":"新闻出版行业标准批准发布后，任何单位或个人发现个别技术内容有问题，必须作少量修改或增减时，可以向新闻出版专业标准化委员会提出修改建议，由该标准化技术委员会审核认定后提交标准修改单，报新闻出版广电总局标准化主管部门审核并做出相应决定。"},{"i":29,"n":"第二十九条","txt":"新闻出版广电总局标准化主管部门应在标准发布后组织标准的宣传和贯彻，并对标准的实施情况进行监督检查。"},{"i":30,"n":"第三十条","txt":"新闻出版广电总局和各省、自治区、直辖市人民政府出版行政主管部门设立的质量检验机构，要密切配合标准的贯彻实施工作，依据相关标准对新闻出版领域企业提供的产品和服务进行检验。"},{"i":31,"n":"第三十一条","txt":"新闻出版专业标准化技术委员会应协助各级政府相关机构及质量检验机构开展标准的宣传和实施的监督检查工作。"},{"i":32,"n":"第三十二条","txt":"任何单位和个人在新闻出版领域开展生产、经营等活动中，应依法执行强制性标准，积极采用推荐性标准和行业标准化指导性技术文件。任何单位开展的生产和服务活动，应当执行相应的企业标准或项目标准、工程标准。 禁止生产、销售和进口不符合强制性标准的产品。"},{"i":33,"n":"第三十三条","txt":"新闻出版领域各类产品未达到相关强制性标准要求的，不得进入流通领域；凡未通过标准检验和标准符合性测试认证的产品不得参评相关奖励。"},{"i":34,"n":"第三十四条","txt":"标准属于科技成果，对技术水平高和取得显著效益的新闻出版领域的国家标准或行业标准，应纳入新闻出版领域相关科技奖励范围。"},{"i":35,"n":"第三十五条","txt":"违反本办法的，由出版行政主管部门责令改正，视情节轻重依法作出警告、三万元以下罚款的行政处罚。其中，提供的产品或服务不符合强制性标准的，由出版行政主管部门责令停止生产或服务。法律、行政法规另有规定的除外。 出版物质量不符合有关标准的，根据《出版管理条例》第六十七条的规定，由出版行政主管部门责令改正，给予警告；情节严重的，责令限期停业整顿或者由原发证机关吊销许可证。"},{"i":36,"n":"第三十六条","txt":"标准化主管部门、质量检验机构和标准测试工作机构的工作人员，因失职、渎职造成不良后果或重大损失的，由有关主管部门给予行政处分，构成犯罪的依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"在中华人民共和国境内从事版权领域标准化活动，参照适用本办法。"},{"i":38,"n":"第三十八条","txt":"本办法自2014年2月1日起施行，新闻出版署于2001年1月6日发布的《新闻出版行业标准化管理办法》同时废止。"}],"xinwenchubanxukezhengguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强新闻出版许可证（以下简称许可证）管理，规范新闻出版市场秩序，维护公民、法人和其他组织的合法权益，根据《中华人民共和国行政许可法》《出版管理条例》《音像制品管理条例》《印刷业管理条例》等相关法律、法规制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称许可证，是指新闻出版行政部门根据公民、法人或其他组织的申请，经依法审查，准予其从事新闻出版活动的行政许可证件。 许可证的设立、设计、印刷、制作、发放、使用、换发、补发、变更、注销等管理适用本办法。"},{"i":3,"n":"第三条","txt":"新闻出版行政部门在许可证管理中应当遵循依法、公开、规范、便民的原则。 无法律法规依据，不得以任何名义和形式向行政相对人收取涉及许可证的相关费用。"},{"i":4,"n":"第四条","txt":"国家新闻出版广电总局负责全国新闻出版许可证监督检查、统一备案和信息公示等职责；地方新闻出版行政部门负责本辖区许可证的监督检查职责。 各级新闻出版行政部门负责对所发放、注销、吊销的许可证在政府网站或经批准公开发行的报纸上进行公示。"},{"i":5,"n":"第五条","txt":"许可证设立，是指对依法设定的行政许可项目，决定以颁发许可证的形式作为许可证件。 许可证设立，必须以法律法规设定的行政许可为依据。"},{"i":6,"n":"第六条","txt":"许可证设计，是指对许可证的登记项目和样式进行的设计。设计许可证时须规定其有效期限。 国家新闻出版广电总局负责各类许可证的设立与设计。"},{"i":7,"n":"第七条","txt":"许可证印刷，是指按照许可证的设计样式，印刷不含登记内容的纸质许可证或复制不含登记内容的电子许可证。 许可证的印刷原则上由实施行政许可的新闻出版行政部门负责，根据实际情况也可由上级新闻出版行政部门统一印刷。"},{"i":8,"n":"第八条","txt":"许可证制作，是指空白许可证的内容填写、盖章、封装等。 许可证须由新闻出版行政部门依法作出行政许可批准决定或按本办法及有关规定履行补发、换发手续后制作。 许可证的许可登记项目内容必须与行政许可决定内容相一致。许可证不得交由行政相对人自行填写或由其他机构代为填写。 许可证登记事项发生变更的，由办理变更登记的新闻出版行政部门在许可证相应位置加盖变更专用章。 许可证加盖实施行政许可的或办理变更登记的新闻出版行政部门公章或变更专用章后，正本、副本具有同等的法律效力，其他任何部门或单位不得在许可证上加盖公章。"},{"i":9,"n":"第九条","txt":"许可证发放，是指将许可证送达行政相对人。 许可证原则上由实施行政许可的新闻出版行政部门发放。为方便行政相对人，也可由实施行政许可的新闻出版行政部门依法委托下级新闻出版行政部门代为发放。 新闻出版行政部门应当自作出行政许可批准决定之日起10个工作日内，将许可证送达行政相对人。 委托发放许可证的，下级新闻出版行政部门应自收到行政许可批准决定和许可证后4个工作日内送达行政相对人，并不得要求行政相对人另行办理许可证申领手续。"},{"i":10,"n":"第十条","txt":"许可证持证者应按照许可证所载明的业务范围和期限从事新闻出版活动。"},{"i":11,"n":"第十一条","txt":"许可证不得伪造、涂改、冒用，或者以买卖、租借等任何形式转让。"},{"i":12,"n":"第十二条","txt":"许可证有效期满即失效。持证者需要延续依法取得的许可证的，应当在该许可证有效期限届满30日前，向原发证机关提出换发许可证申请。"},{"i":13,"n":"第十三条","txt":"许可证发生损坏、丢失的，持证人应向原发证机关申请补发新证。申请时须将损坏的许可证原件缴还原发证机关。发证机关应当自收到补发许可证申请后5个工作日内，注销旧证，发放新证。"},{"i":14,"n":"第十四条","txt":"换发新的许可证时，应同时收回旧证。除国家新闻出版广电总局直接换发的许可证外，其余旧证按属地管理原则由属地许可证换发部门统一登记销毁，并于销毁后1个月内将换发、销毁情况逐级报上级新闻出版行政部门备案。"},{"i":15,"n":"第十五条","txt":"许可证登记的许可事项发生变更的，实施行政许可的新闻出版行政部门应根据持证者提出的许可申请，履行审批程序，按审批权限在变更记录页上办理变更登记或由原发证机关换发新证。"},{"i":16,"n":"第十六条","txt":"许可证登记的非许可事项发生变更的，实施行政许可或受委托的新闻出版行政部门根据持证者提出的变更申请，原则上应现场即时完成许可证副本变更记录页的变更登记或由原发证机关换发新证，为行政相对人提供便捷高效的服务。"},{"i":17,"n":"第十七条","txt":"实行年度核验制度的行政许可，许可证在年度核验合格并加盖核验章后继续使用。"},{"i":18,"n":"第十八条","txt":"有《行政许可法》第七十条规定情形的，由实施行政许可的新闻出版行政部门在1个月内注销许可证并公示。"},{"i":19,"n":"第十九条","txt":"国家实行统一的许可证信息化管理。国家新闻出版广电总局负责“全国新闻出版许可证信息管理系统”的总体设计、建设指导以及应用协调等工作，实行许可证信息的全国联网、集中公示和有效管理。"},{"i":20,"n":"第二十条","txt":"地方各级新闻出版行政部门按要求做好“全国新闻出版许可证信息管理系统”的衔接、应用工作，严格履行信息采集、报送等职责。"},{"i":21,"n":"第二十一条","txt":"新闻出版行政部门在条件具备时制作发放电子许可证。电子许可证与纸质许可证具有同等的法律效力。"},{"i":22,"n":"第二十二条","txt":"新闻出版行政部门有下列行为之一的，依据《行政许可法》第六十九条、第七十四条，由其上级行政机关或者监察机关责令纠正违法违规行为，撤销行政许可，注销所发放的许可证并予以通报批评；情节严重的，追究部门主要领导和直接责任人员的行政责任： （一）无法定行政许可依据或超越权限设立许可证的； （二）未经法定行政许可，擅自制作、发放许可证的； （三）违规在许可证上加盖公章的； （四）擅自改变许可证样式、登记项目并制作、发放许可证的。"},{"i":23,"n":"第二十三条","txt":"新闻出版行政部门有下列行为之一的，由其上级行政机关或者监察机关责令改正并通报批评： （一）由行政相对人或其他机构代为填写许可证内容的； （二）不按行政许可决定填写许可证内容的； （三）发放许可证时要求行政相对人另行办理申领手续的； （四）未按规定及时发放许可证的； （五）未按规定逐级报备废旧许可证销毁情况的。"},{"i":24,"n":"第二十四条","txt":"违法违规收取涉及许可证有关费用的，依据《行政许可法》第七十五条，由其上级行政机关或者监察机关追究有关领导和直接责任人员的行政责任，监督退还所收取的费用并通报批评；情节严重的，移交有关部门查处。"},{"i":25,"n":"第二十五条","txt":"新闻出版行政部门工作人员在涉及许可证的有关工作中，利用职务获取不当利益的，依据《出版管理条例》第六十条规定处罚。"},{"i":26,"n":"第二十六条","txt":"行政相对人有下列行为之一的，依据《行政许可法》《出版管理条例》《音像制品管理条例》《印刷业管理条例》和有关部门规章的规定处罚；没有相应规定的，由新闻出版行政部门责令改正，情节严重的，并处警告或3万元以下罚款： （一）许可证登记事项发生改变，未依法依规进行变更登记的； （二）涂改、出卖、租借或者以其他形式非法转让许可证的； （三）以欺骗、贿赂等不正当手段取得许可证的； （四）未按许可证载明的业务范围从事新闻出版活动的。"},{"i":27,"n":"第二十七条","txt":"《新闻记者证》等有关人员资格证书不适用本办法。"},{"i":28,"n":"第二十八条","txt":"省级新闻出版行政部门可根据本地区实际制定实施办法。"},{"i":29,"n":"第二十九条","txt":"电子许可证和“全国新闻出版许可证信息管理系统”的管理办法由国家新闻出版广电总局另行制定。"},{"i":30,"n":"第三十条","txt":"地方性法规设定行政许可的许可证的设立、设计、印刷、制作、发放、变更登记事项、注销等，可参照本办法进行管理。"},{"i":31,"n":"第三十一条","txt":"本办法自2016年3月1日起施行。"}],"xinwendanweizhudifangjigouguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范新闻单位驻地方机构（以下称驻地方机构）的新闻采编活动，加强驻地方机构的管理，促进新闻事业健康有序发展，根据国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称驻地方机构，是指依法批准的新闻单位设立的从事新闻采编活动的派出机构。 本办法适用于下列新闻单位派出的驻地方机构从事新闻采编活动的管理： （一）报纸出版单位、新闻性期刊出版单位； （二）通讯社； （三）广播电台、电视台、广播电视台； （四）新闻网站、网络广播电视台； （五）其他新闻单位。"},{"i":3,"n":"第三条","txt":"国务院新闻出版广电主管部门负责全国驻地方机构的监督管理，制定全国驻地方机构的设立规划，确定总量、布局、结构。 县级以上地方人民政府新闻出版广电主管部门负责本行政区域内驻地方机构的监督管理。 新闻单位负责其驻地方机构从事新闻采编等活动的日常管理，保障驻地方机构依法运行。"},{"i":4,"n":"第四条","txt":"驻地方机构及其人员从事新闻采编活动应当以人民为中心，坚持为人民服务、为社会主义服务，坚持正确舆论导向，弘扬社会主义核心价值观，弘扬民族优秀文化。"},{"i":5,"n":"第五条","txt":"驻地方机构及其人员从事新闻采编活动应当遵守法律法规，尊重社会公德，恪守职业道德，深入基层、深入群众、深入生活，确保新闻报道真实、全面、客观、公正。"},{"i":6,"n":"第六条","txt":"驻地方机构及其人员从事新闻采编等活动受法律保护。 任何单位和人员不得干扰、阻挠驻地方机构及其人员的正常工作，不得假冒、盗用驻地方机构名义开展活动。"},{"i":7,"n":"第七条","txt":"国家对设立驻地方机构实行许可制度，未经批准不得设立，任何单位和人员不得以驻地方机构名义从事新闻采编活动。 新闻单位不得以派驻地记者方式代替设立驻地方机构从事新闻采编活动。"},{"i":8,"n":"第八条","txt":"本办法第二条规定的新闻单位设立驻地方机构应当符合国务院新闻出版广电主管部门对驻地方机构总量、布局、结构的规划，并具备下列条件： （一）在派驻地确有新闻采编需要； （二）有健全的驻地方机构人员、财务、新闻采编活动等管理制度； （三）有指导、管理驻地方机构的条件和能力； （四）驻地方机构负责人具有新闻、出版、播音主持等专业的中级以上职称或者有5年以上新闻采编、新闻管理工作经历； （五）驻地方机构有符合业务需要的持有新闻记者证的新闻采编人员； （六）驻地方机构有满足业务需要的固定工作场所和经费； （七）国家规定的其他条件。"},{"i":9,"n":"第九条","txt":"申请设立驻地方机构的报纸出版单位，仅限于每周出版四期以上的报纸出版单位，不包括教学辅导类报纸、文摘类报纸、高等学校校报等出版单位。 申请设立驻地方机构的新闻网站，仅限于中央主要新闻单位所办中央重点新闻网站。 申请设立驻地方机构的新闻性期刊出版单位、广播电台、电视台、广播电视台、网络广播电视台，应当经国务院新闻出版广电主管部门认定。"},{"i":10,"n":"第十条","txt":"新闻单位在同一城市只能设立一个驻地方机构。 报业集团、期刊集团或者有多家子报子刊的新闻单位应当以集团或者新闻单位名义设立驻地方机构，其下属新闻单位不得再单独设立驻地方机构。"},{"i":11,"n":"第十一条","txt":"新闻单位设立驻地方机构，经其主管单位审核同意后，向驻地方机构所在地省、自治区、直辖市新闻出版广电主管部门提出申请。其中，中央主要新闻单位设立驻地方机构，须先经国务院新闻出版广电主管部门审核同意。 中央重点新闻网站设立驻地方机构，经驻地方机构所在地省、自治区、直辖市网信主管部门审核，并经国家网信主管部门审查同意后，向所在地省、自治区、直辖市新闻出版广电主管部门提出申请。"},{"i":12,"n":"第十二条","txt":"新闻单位设立驻地方机构，应提交申请书及下列材料： （一）驻地方机构负责人、新闻采编人员等的基本情况及其从业资格证明； （二）符合本办法规定的驻地方机构人员编制或者劳动合同、聘用合同等证明； （三）驻地方机构经费来源的证明； （四）驻地方机构工作场所的证明； （五）主管单位同意设立驻地方机构的证明； （六）报纸出版单位出具报纸刊期的证明； （七）新闻性期刊出版单位、广播电台、电视台、广播电视台、网络广播电视台出具国务院新闻出版广电主管部门认定的证明； （八）中央重点新闻网站出具国家网信主管部门审查同意的证明。"},{"i":13,"n":"第十三条","txt":"省、自治区、直辖市新闻出版广电主管部门自受理申请之日起20日内，作出批准或者不批准的决定。批准的，发放新闻单位驻地方机构许可证；不批准的，应当说明理由。"},{"i":14,"n":"第十四条","txt":"驻地方机构名称由新闻单位名称和驻地方机构所在行政区域及单位名称组成。"},{"i":15,"n":"第十五条","txt":"驻地方机构的登记地址、联系方式、负责人、新闻采编人员等发生变更，驻地方机构应当在变更后90日内到所在地省、自治区、直辖市新闻出版广电主管部门办理变更登记手续。"},{"i":16,"n":"第十六条","txt":"新闻单位终止其驻地方机构业务活动，应当在30日内到所在地省、自治区、直辖市新闻出版广电主管部门办理注销登记手续，交回新闻单位驻地方机构许可证。"},{"i":17,"n":"第十七条","txt":"新闻单位驻地方机构许可证由国务院新闻出版广电主管部门统一印制，有效期6年。"},{"i":18,"n":"第十八条","txt":"新闻单位应当在取得新闻单位驻地方机构许可证后30日内派遣新闻采编人员等到驻地方机构开展工作。"},{"i":19,"n":"第十九条","txt":"新闻单位应当建立健全新闻线索集中管理和统一安排采访制度，规范驻地方机构的新闻采编活动。"},{"i":20,"n":"第二十条","txt":"新闻单位应当建立规范的驻地方机构人员用工制度，签订劳动合同或者聘用合同，保障员工的薪酬、社会保障等各项权益。"},{"i":21,"n":"第二十一条","txt":"新闻单位应当确保驻地方机构正常开展工作所需经费，不得向驻地方机构及其人员下达经营创收指标、摊派经营任务、收取管理费等。"},{"i":22,"n":"第二十二条","txt":"新闻单位应当建立健全驻地方机构人员培训和在职教育制度，提升从业人员素质。"},{"i":23,"n":"第二十三条","txt":"新闻单位应当建立健全驻地方机构负责人任期、轮岗、审计、约谈、问责等内部管理制度，对出现违法违规问题造成恶劣影响的，要撤换驻地方机构负责人并依法依规追究责任。"},{"i":24,"n":"第二十四条","txt":"新闻单位应当建立健全巡视检查制度，定期开展巡视检查，强化对驻地方机构的日常管理。"},{"i":25,"n":"第二十五条","txt":"新闻单位应当建立健全社会监督机制，公示驻地方机构及其负责人、新闻采编人员名单，接受社会监督。"},{"i":26,"n":"第二十六条","txt":"新闻单位、驻地方机构及其人员不得以承包、出租、出借、合作等任何形式非法转让驻地方机构的名称、证照、新闻业务等。"},{"i":27,"n":"第二十七条","txt":"驻地方机构应当在批准范围内从事与新闻单位业务范围相一致的新闻采编活动。 驻地方机构及其人员不得从事广告、出版物发行、开办经营实体等与新闻采编业务无关的活动。"},{"i":28,"n":"第二十八条","txt":"驻地方机构负责人应当落实国家有关新闻采编的管理规定，对本机构的新闻采编工作全面负责。 驻地方机构应当建立新闻采编工作记录制度、自查评估制度。"},{"i":29,"n":"第二十九条","txt":"驻地方机构及其人员不得有下列违法违规和违反职业道德的行为： （一）编发虚假报道； （二）有偿新闻、有偿不闻、新闻敲诈等； （三）利用职务影响和职务便利要求采访、报道对象及相关单位和人员做广告、订报刊、提供赞助等； （四）其他谋取不正当利益的行为。"},{"i":30,"n":"第三十条","txt":"驻地方机构不得以任何名义设立分支机构、聘用人员，不得与党政机关混合设立，党政机关工作人员不得在驻地方机构兼职。 驻地方机构负责人原则上不得同时在两个以上驻地方机构任职。"},{"i":31,"n":"第三十一条","txt":"国务院新闻出版广电主管部门负责指导、协调地方新闻出版广电主管部门对全国驻地方机构的监督管理。 国务院新闻出版广电主管部门负责中央主要新闻单位和中央重点新闻网站驻地方机构执行本办法情况的监督抽查；负责督办、查处驻地方机构及其人员违反本办法的重大案件；负责依法将驻地方机构及其人员违反本办法受到行政处罚的情形记入新闻采编不良从业行为记录。"},{"i":32,"n":"第三十二条","txt":"省、自治区、直辖市新闻出版广电主管部门负责本行政区域内驻地方机构的日常监督管理。 省、自治区、直辖市新闻出版广电主管部门应当建立健全准入退出、综合评估、监督抽查、年度核验、信息通报和公告等制度，负责查处本行政区域内驻地方机构及其人员违反本办法的行为。 省、自治区、直辖市新闻出版广电主管部门应当向国务院新闻出版广电主管部门定期报告驻地方机构准入退出、综合评估、监督抽查、年度核验和公告等情况。"},{"i":33,"n":"第三十三条","txt":"地方各级新闻出版广电主管部门应当建立健全社会监督机制，受理对违反本办法行为的投诉、举报，并及时核实、处理、答复。"},{"i":34,"n":"第三十四条","txt":"国务院新闻出版广电主管部门发现中央主要新闻单位和中央重点新闻网站驻地方机构有违反本办法行为的，可以对新闻单位相关负责人进行约谈，向有关部门提出处理建议。 省、自治区、直辖市新闻出版广电主管部门发现本行政区域内驻地方机构有违反本办法行为的，可以对新闻单位相关负责人，或者驻地方机构负责人进行约谈，向有关部门提出处理建议。"},{"i":35,"n":"第三十五条","txt":"省、自治区、直辖市新闻出版广电主管部门应当与网信主管部门建立协作机制，通报本行政区域内中央重点新闻网站驻地方机构准入退出、变更备案、年度核验、案件查处等信息。"},{"i":36,"n":"第三十六条","txt":"新闻单位的主管单位应当督促所属新闻单位及其驻地方机构执行本办法的各项管理规定，及时发现并纠正所属新闻单位、驻地方机构及其人员的违法行为，并依法追究所属新闻单位主要负责人和直接责任人的责任。"},{"i":37,"n":"第三十七条","txt":"省、自治区、直辖市新闻出版广电主管部门每两年对本行政区域内驻地方机构统一组织年度核验，重点核查驻地方机构下列内容： （一）新闻采编工作情况； （二）负责人、持有新闻记者证的新闻采编人员等变更情况； （三）是否存在违反本办法的行为及其处理情况。"},{"i":38,"n":"第三十八条","txt":"驻地方机构应当按时将下列材料报省、自治区、直辖市新闻出版广电主管部门进行年度核验： （一）驻地方机构年度工作总结报告； （二）驻地方机构年度主要新闻报道目录或者证明其新闻采编业绩的有关材料； （三）新闻单位对驻地方机构的年度评估报告； （四）其他必需的有关材料。 中央重点新闻网站驻地方机构还应当提供省、自治区、直辖市网信主管部门提出的审核意见。"},{"i":39,"n":"第三十九条","txt":"省、自治区、直辖市新闻出版广电主管部门应当及时向社会公告年度核验合格的驻地方机构名录；在年度核验中发现驻地方机构及其人员有违法行为的，应当依法处理；对不再具备行政许可法定条件的，应当责令限期改正，未按期改正的，应当依法撤销行政许可。"},{"i":40,"n":"第四十条","txt":"新闻出版广电主管部门或者其他有关部门工作人员有下列情形之一，尚不构成犯罪的，依法给予处分： （一）利用职务便利收受他人财物或者其他好处的； （二）违反本办法规定进行审批活动的； （三）不履行监督职责的； （四）发现违法行为不予查处的； （五）干扰、阻挠驻地方机构及其人员正常的新闻采编活动、妨碍舆论监督的； （六）其他违反本办法规定滥用职权、玩忽职守、徇私舞弊的情形。"},{"i":41,"n":"第四十一条","txt":"驻地方机构出现下列情形之一的，由国务院新闻出版广电主管部门或者省、自治区、直辖市新闻出版广电主管部门责令新闻单位限期改正；新闻单位未按期改正的，由省、自治区、直辖市新闻出版广电主管部门撤销其新闻单位驻地方机构许可证： （一）驻地方机构不具备本办法第八条、第九条规定的许可条件的； （二）违反本办法第十八条，未在法定期限内开展工作的。"},{"i":42,"n":"第四十二条","txt":"新闻单位及其驻地方机构有下列行为之一的，国务院新闻出版广电主管部门或者省、自治区、直辖市新闻出版广电主管部门可以采取通报批评、责令公开检讨、责令整改等行政措施，情节严重的，可以给予警告，可以并处3万元以下罚款： （一）违反本办法第十五条、第十六条，未在法定期限内办理有关手续的； （二）违反本办法第十九条、第二十条、第二十二条、第二十三条、第二十四条、第二十五条，未按规定开展工作、落实有关责任的； （三）违反本办法第二十八条，驻地方机构负责人未按规定落实有关责任或者未建立有关制度的； （四）违反本办法第三十八条，未按规定参加年度核验的。"},{"i":43,"n":"第四十三条","txt":"新闻单位及其驻地方机构有下列行为之一的，国务院新闻出版广电主管部门或者省、自治区、直辖市新闻出版广电主管部门可以采取通报批评、责令公开检讨、责令整改等行政措施，可以给予警告，可以并处3万元以下罚款，情节严重的，撤销其新闻单位驻地方机构许可证： （一）违反本办法第二十一条，向驻地方机构及其人员下达经营创收指标、摊派经营任务、收取管理费的； （二）违反本办法第二十六条，非法转让驻地方机构的名称、证照、新闻业务等的； （三）违反本办法第二十七条、第二十九条，从事与新闻采编业务无关的活动或者从事违法违规和违反职业道德行为的； （四）违反本办法第三十条，违规设立分支机构、聘用人员，与党政机关混合设立，党政机关工作人员在驻地方机构兼职的。"},{"i":44,"n":"第四十四条","txt":"违反本办法第六条、第七条，擅自设立驻地方机构或者采取假冒、盗用等方式以驻地方机构或者驻地记者名义开展活动的，由省、自治区、直辖市新闻出版广电主管部门予以取缔，可以并处3万元以下罚款，没收违法所得。"},{"i":45,"n":"第四十五条","txt":"本办法施行前已经设立的驻地方机构，自本办法施行之日起6个月内，由新闻单位持原批准文件到驻地方机构所在地省、自治区、直辖市新闻出版广电主管部门换发新闻单位驻地方机构许可证。"},{"i":46,"n":"第四十六条","txt":"本办法自2017年6月1日起施行。2009年8月6日原新闻出版总署颁布的《报刊记者站管理办法》同时废止。"}],"xinwenjizhezhengguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范新闻记者证的管理，保障新闻记者的正常采访活动，维护新闻记者和社会公众的合法权益，根据有关法规和国务院决定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于新闻记者证的申领、核发、使用和管理。 在中华人民共和国境内从事新闻采编活动，须持有新闻出版总署核发的新闻记者证。"},{"i":3,"n":"第三条","txt":"新闻记者证是新闻记者职务身份的有效证明，是境内新闻记者从事新闻采编活动的唯一合法证件，由新闻出版总署依法统一印制并核发。 境内新闻机构使用统一样式的新闻记者证。"},{"i":4,"n":"第四条","txt":"本办法所称新闻记者，是指新闻机构编制内或者经正式聘用，专职从事新闻采编岗位工作，并持有新闻记者证的采编人员。 本办法所称新闻机构，是指经国家有关行政部门依法批准设立的境内报纸出版单位、新闻性期刊出版单位、通讯社、广播电台、电视台、新闻电影制片厂等具有新闻采编业务的单位。其中，报纸、新闻性期刊出版单位由国务院新闻出版行政部门认定；广播、电影、电视新闻机构的认定，以国务院广播电影电视行政部门的有关批准文件为依据。"},{"i":5,"n":"第五条","txt":"新闻记者持新闻记者证依法从事新闻采访活动受法律保护。各级人民政府及其职能部门、工作人员应为合法的新闻采访活动提供必要的便利和保障。 任何组织或者个人不得干扰、阻挠新闻机构及其新闻记者合法的采访活动。"},{"i":6,"n":"第六条","txt":"新闻记者证由新闻出版总署统一编号，并签印新闻出版总署印章、新闻记者证核发专用章、新闻记者证年度核验标签和本新闻机构（或者主办单位）钢印方为有效。 其他任何单位或者个人不得制作、仿制、发放、销售新闻记者证，不得制作、发放、销售专供采访使用的其他证件。"},{"i":7,"n":"第七条","txt":"新闻出版总署负责全国新闻记者证的核发工作，省、自治区、直辖市新闻出版行政部门负责审核本行政区域新闻机构的新闻记者证。"},{"i":8,"n":"第八条","txt":"新闻记者证由新闻机构向新闻出版行政部门申请领取。申领新闻记者证须由新闻机构如实填写并提交《领取新闻记者证登记表》、《领取新闻记者证人员情况表》以及每个申领人的身份证、毕业证、从业资格证（培训合格证）、劳动合同复印件等申报材料。"},{"i":9,"n":"第九条","txt":"新闻机构中领取新闻记者证的人员须同时具备下列条件： （一）遵守国家法律、法规和新闻工作者职业道德； （二）具备大学专科以上学历并获得国务院有关部门认定的新闻采编从业资格； （三）在新闻机构编制内从事新闻采编工作的人员，或者经新闻机构正式聘用从事新闻采编岗位工作且具有一年以上新闻采编工作经历的人员。 本条所称“经新闻机构正式聘用”，是指新闻采编人员与其所在新闻机构签有劳动合同。"},{"i":10,"n":"第十条","txt":"下列人员不发新闻记者证： （一）新闻机构中党务、行政、后勤、经营、广告、工程技术等非采编岗位的工作人员； （二）新闻机构以外的工作人员，包括为新闻单位提供稿件或者节目的通讯员、特约撰稿人，专职或兼职为新闻机构提供新闻信息的其他人员; （三）教学辅导类报纸、高等学校校报工作人员以及没有新闻采访业务的期刊编辑人员； （四）有不良从业记录的人员、被新闻出版行政部门吊销新闻记者证并在处罚期限内的人员或者受过刑事处罚的人员。"},{"i":11,"n":"第十一条","txt":"中央单位所办新闻机构经主管部门审核所属新闻机构采编人员资格条件后，向新闻出版总署申领新闻记者证，由新闻出版总署批准后发放新闻记者证。"},{"i":12,"n":"第十二条","txt":"省和省以下单位所办新闻机构经主管部门审核所属新闻机构采编人员资格条件后，向所在地省、自治区、直辖市新闻出版行政部门申领新闻记者证，由省、自治区、直辖市新闻出版行政部门审核并报新闻出版总署批准后，发放新闻记者证。 其中，地、市、州、盟所属新闻机构申领新闻记者证须经地、市、州、盟新闻出版行政部门审核后，报省、自治区、直辖市新闻出版行政部门。"},{"i":13,"n":"第十三条","txt":"记者站的新闻采编人员资格条件经设立该记者站的新闻机构审核，主管部门同意后，向记者站登记地省、自治区、直辖市新闻出版行政部门申领新闻记者证，由省、自治区、直辖市新闻出版行政部门审核并报新闻出版总署批准后，发放新闻记者证。 在地、市、州、盟设立的记者站，申领新闻记者证应报当地新闻出版行政部门逐级审核后，报省、自治区、直辖市新闻出版行政部门。 新闻机构记者站的新闻记者证应注明新闻机构及记者站名称。"},{"i":14,"n":"第十四条","txt":"解放军总政治部宣传部新闻出版局负责解放军和武警部队（不含边防、消防、警卫部队）新闻机构新闻记者证的审核发放工作，并向新闻出版总署备案。"},{"i":15,"n":"第十五条","txt":"除解放军和武警部队（不含边防、消防、警卫部队）系统外，新闻记者证申领、审核、发放和注销工作统一通过新闻出版总署的“全国新闻记者证管理及核验网络系统”进行。"},{"i":16,"n":"第十六条","txt":"新闻采编人员从事新闻采访工作必须持有新闻记者证，并应在新闻采访中主动向采访对象出示。 新闻机构中尚未领取新闻记者证的采编人员，必须在本新闻机构持有新闻记者证的记者带领下开展采访工作，不得单独从事新闻采访活动。"},{"i":17,"n":"第十七条","txt":"新闻机构非采编岗位工作人员、非新闻机构以及其他社会组织或者个人不得假借新闻机构或者假冒新闻记者进行新闻采访活动。"},{"i":18,"n":"第十八条","txt":"新闻记者使用新闻记者证从事新闻采访活动，应遵守法律规定和新闻职业道德，确保新闻报道真实、全面、客观、公正，不得编发虚假报道，不得刊播虚假新闻，不得徇私隐匿应报道的新闻事实。"},{"i":19,"n":"第十九条","txt":"新闻采访活动是新闻记者的职务行为，新闻记者证只限本人使用，不得转借或者涂改，不得用于非职务活动。 新闻记者不得从事与记者职务有关的有偿服务、中介活动或者兼职、取酬，不得借新闻采访工作从事广告、发行、赞助等经营活动，不得创办或者参股广告类公司，不得借新闻采访活动牟取不正当利益，不得借舆论监督进行敲诈勒索、打击报复等滥用新闻采访权利的行为。"},{"i":20,"n":"第二十条","txt":"新闻记者与新闻机构解除劳动关系、调离本新闻机构或者采编岗位，应在离岗前主动交回新闻记者证，新闻机构应立即通过“全国新闻记者证管理及核验网络系统”申请注销其新闻记者证，并及时将收回的新闻记者证交由新闻出版行政部门销毁。"},{"i":21,"n":"第二十一条","txt":"新闻记者证因污损、残破等各种原因无法继续使用，由新闻机构持原证到发证机关更换新证，原新闻记者证编号保留使用。"},{"i":22,"n":"第二十二条","txt":"新闻记者证遗失后，持证人须立即向新闻机构报告，新闻机构须立即办理注销手续，并在新闻出版总署或者省、自治区、直辖市新闻出版行政部门指定的媒体上刊登遗失公告。 需要重新补办新闻记者证的，可在刊登公告一周后到发证机关申请补领新证，原新闻记者证编号同时作废。"},{"i":23,"n":"第二十三条","txt":"新闻机构撤销，其原已申领的新闻记者证同时注销。该新闻机构的主管单位负责收回作废的新闻记者证，交由发证机关销毁。"},{"i":24,"n":"第二十四条","txt":"采访国内、国际重大活动，活动主办单位可以制作一次性临时采访证件，临时采访证件的发放范围必须为新闻记者证的合法持有人，并随新闻记者证一同使用。"},{"i":25,"n":"第二十五条","txt":"新闻记者证每五年统一换发一次。新闻记者证换发的具体办法由新闻出版总署另行制定。"},{"i":26,"n":"第二十六条","txt":"新闻出版总署和各省、自治区、直辖市新闻出版行政部门以及解放军总政治部宣传部新闻出版局负责对新闻记者证的发放、使用和年度核验等工作进行监督管理。 各级新闻出版行政部门负责对新闻记者在本行政区域内的新闻采编活动进行监督管理。 新闻出版行政部门根据调查掌握的违法事实，建立不良从业人员档案，并适时公开。"},{"i":27,"n":"第二十七条","txt":"新闻机构的主管单位须履行对所属新闻机构新闻记者证的申领审核和规范使用的管理责任，加强对所属新闻机构及其新闻记者开展新闻采编活动的监督管理。"},{"i":28,"n":"第二十八条","txt":"新闻机构须履行对所属新闻采编人员资格条件审核及新闻记者证申领、发放、使用和管理责任，对新闻记者的采访活动进行监督管理，对有违法行为的新闻记者应及时调查处理。 新闻机构应建立健全新闻记者持证上岗培训和在岗培训制度，建立健全用工制度和社会保障制度，及时为符合条件的采编人员申领新闻记者证。 新闻机构不得聘用存在搞虚假报道、有偿新闻、利用新闻报道谋取不正当利益、违法使用新闻记者证等不良从业记录的人员。"},{"i":29,"n":"第二十九条","txt":"新闻机构每年应定期公示新闻记者证持有人名单和新申领新闻记者证人员名单，在其所属媒体上公布“全国新闻记者证管理及核验网络系统”的网址和举报电话，方便社会公众核验新闻记者证，并接受监督。"},{"i":30,"n":"第三十条","txt":"被采访人以及社会公众有权对新闻记者的新闻采访活动予以监督，可以通过“全国新闻记者证管理及核验网络系统”等途径核验新闻记者证、核实记者身份，并对新闻记者的违法行为予以举报。"},{"i":31,"n":"第三十一条","txt":"新闻记者涉嫌违法被有关部门立案调查的，新闻出版总署可以视其涉嫌违法的情形，通过“全国新闻记者证管理及核验网络系统”中止其新闻记者证使用，并根据不同情形依法处理。"},{"i":32,"n":"第三十二条","txt":"新闻记者证实行年度核验制度，由新闻出版总署和各省、自治区、直辖市新闻出版行政部门以及解放军总政治部宣传部新闻出版局分别负责中央新闻机构、地方新闻机构和解放军及武警部队（不含边防、消防、警卫部队）新闻机构新闻记者证的年度核验工作。 新闻记者证年度核验每年1月开始，3月15日前结束，各省、自治区、直辖市新闻出版行政部门和解放军总政治部宣传部新闻出版局须在3月31日前，将年度核验报告报新闻出版总署。 新闻机构未按规定进行新闻记者证年度核验的，由发证机关注销其全部新闻记者证。"},{"i":33,"n":"第三十三条","txt":"新闻记者证年度核验工作由新闻机构自查，填写《新闻记者证年度核验表》，经主管单位审核后，报新闻出版行政部门依法核验。年度核验的主要内容是： （一）检查持证人员是否仍具备持有新闻记者证的所有条件； （二）检查持证人员本年度内是否出现违法行为； （三）检查持证人员的登记信息是否变更。 通过年度核验的新闻记者证，由新闻出版行政部门核发年度核验标签，并粘贴到新闻记者证年度核验位置，新闻记者证的有效期以年度核验标签的时间为准。未通过年度核验的新闻记者证，由发证机关注销，不得继续使用。"},{"i":34,"n":"第三十四条","txt":"新闻机构及其工作人员违反本办法的，新闻出版行政部门视其情节轻重，可采取下列行政措施： （一）通报批评； （二）责令公开检讨； （三）责令改正； （四）中止新闻记者证使用； （五）责成主管单位、主办单位监督整改。 本条所列行政措施可以并用。"},{"i":35,"n":"第三十五条","txt":"新闻机构工作人员有以下行为之一的，由新闻出版总署或者省、自治区、直辖市新闻出版行政部门给予警告，并处3万元以下罚款，情节严重的，吊销其新闻记者证，构成犯罪的，依法追究刑事责任： （一）违反本办法第十七条，从事有关活动的； （二）违反本办法第十八条，编发虚假报道的； （三）违反本办法第十九条，转借、涂改新闻记者证或者利用职务便利从事不当活动的； （四）违反本办法第二十条，未在离岗前交回新闻记者证的。"},{"i":36,"n":"第三十六条","txt":"新闻机构有以下行为之一的，由新闻出版总署或者省、自治区、直辖市新闻出版行政部门没收违法所得，给予警告，并处3万元以下罚款，可以暂停核发该新闻机构新闻记者证，并建议其主管单位、主办单位对其负责人给予处分： （一）违反本办法第六条，擅自制作、仿制、发放、销售新闻记者证或者擅自制作、发放、销售采访证件的； （二）违反本办法第八条，提交虚假申报材料的； （三）未按照本办法第九条、第十条，严格审核采编人员资格或者擅自扩大发证范围的； （四）违反本办法第十六条，新闻机构内未持有新闻记者证的人员从事新闻采访活动的； （五）违反本办法第二十条，未及时注销新闻记者证的； （六）违反本办法第二十二条，未及时办理注销手续的； （七）违反本办法第二十八条，未履行监管责任、未及时为符合条件的采编人员申领新闻记者证的或者违规聘用有关人员的； （八）违反本办法第二十九条，未公示或公布有关信息的； （九）违反本办法第"},{"i":37,"n":"第三十七条","txt":"社会组织或者个人有以下行为之一的，由新闻出版行政部门联合有关部门共同查处，没收违法所得，给予警告，并处3万元以下罚款，构成犯罪的，依法追究刑事责任： （一）擅自制作、仿制、发放、销售新闻记者证或者擅自制作、发放、销售采访证件的； （二）假借新闻机构、假冒新闻记者从事新闻采访活动的； （三）以新闻采访为名开展各类活动或者谋取利益的。"},{"i":38,"n":"第三十八条","txt":"新闻记者因违法活动被吊销新闻记者证的，5年内不得重新申领新闻记者证，被追究刑事责任的，终身不得申领新闻记者证。"},{"i":39,"n":"第三十九条","txt":"国外及香港、澳门、台湾新闻机构的人员在境内从事新闻采访活动，不适用本办法。"},{"i":40,"n":"第四十条","txt":"本办法自2009年10月15日起施行。2005年1月10日新闻出版总署颁布的《新闻记者证管理办法》同时废止，本办法生效前颁布的与本办法不一致的其它规定不再执行。"}],"qikanchubanguanliguiding":[{"i":1,"n":"第一条","txt":"为了促进我国期刊业的繁荣和发展，规范期刊出版活动，加强期刊出版管理，根据国务院《出版管理条例》及相关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事期刊出版活动，适用本规定。 期刊由依法设立的期刊出版单位出版。期刊出版单位出版期刊，必须经新闻出版总署批准，持有国内统一连续出版物号，领取《期刊出版许可证》。 本规定所称期刊又称杂志，是指有固定名称，用卷、期或者年、季、月顺序编号，按照一定周期出版的成册连续出版物。 本规定所称期刊出版单位，是指依照国家有关规定设立，经新闻出版总署批准并履行登记注册手续的期刊社。法人出版期刊不设立期刊社的，其设立的期刊编辑部视为期刊出版单位。"},{"i":3,"n":"第三条","txt":"期刊出版必须坚持马克思列宁主义、毛泽东思想、邓小平理论和“三个代表”重要思想，坚持正确的舆论导向和出版方向，坚持把社会效益放在首位、社会效益和经济效益相统一的原则，传播和积累有益于提高民族素质、经济发展和社会进步的科学技术和文化知识，弘扬中华民族优秀文化，促进国际文化交流，丰富人民群众的精神文化生活。"},{"i":4,"n":"第四条","txt":"期刊发行分公开发行和内部发行。 内部发行的期刊只能在境内按指定范围发行，不得在社会上公开发行、陈列。"},{"i":5,"n":"第五条","txt":"新闻出版总署负责全国期刊出版活动的监督管理工作，制定并实施全国期刊出版的总量、结构、布局的规划，建立健全期刊出版质量评估制度、期刊年度核验制度以及期刊出版退出机制等监督管理制度。 地方各级新闻出版行政部门负责本行政区域内的期刊出版活动的监督管理工作。"},{"i":6,"n":"第六条","txt":"期刊出版单位负责期刊的编辑、出版等期刊出版活动。 期刊出版单位合法的出版活动受法律保护。任何组织和个人不得非法干扰、阻止、破坏期刊的出版。"},{"i":7,"n":"第七条","txt":"新闻出版总署对为我国期刊业繁荣和发展做出突出贡献的期刊出版单位及个人实施奖励。"},{"i":8,"n":"第八条","txt":"期刊出版行业的社会团体按照其章程，在新闻出版行政部门的指导下，实行自律管理。"},{"i":9,"n":"第九条","txt":"创办期刊、设立期刊出版单位，应当具备下列条件： （一）有确定的、不与已有期刊重复的名称； （二）有期刊出版单位的名称、章程； （三）有符合新闻出版总署认定条件的主管、主办单位； （四）有确定的期刊出版业务范围； （五）有30万元以上的注册资本； （六）有适应期刊出版活动需要的组织机构和符合国家规定资格条件的编辑专业人员； （七）有与主办单位在同一行政区域的固定的工作场所； （八）有确定的法定代表人或者主要负责人，该法定代表人或者主要负责人必须是在境内长久居住的中国公民； （九）法律、行政法规规定的其他条件。 除前款所列条件外，还须符合国家对期刊及期刊出版单位总量、结构、布局的总体规划。"},{"i":10,"n":"第十条","txt":"中央在京单位创办期刊并设立期刊出版单位，经主管单位审核同意后，由主办单位报新闻出版总署审批。 中国人民解放军和中国人民武装警察部队系统创办期刊并设立期刊出版单位，由中国人民解放军总政治部宣传部新闻出版局审核同意后报新闻出版总署审批。 其他单位创办期刊并设立期刊出版单位，经主管单位审核同意后，由主办单位向所在地省、自治区、直辖市新闻出版行政部门提出申请，省、自治区、直辖市新闻出版行政部门审核同意后，报新闻出版总署审批。"},{"i":11,"n":"第十一条","txt":"两个以上主办单位合办期刊，须确定一个主要主办单位，并由主要主办单位提出申请。 期刊的主要主办单位应为其主管单位的隶属单位。期刊出版单位和主要主办单位须在同一行政区域。"},{"i":12,"n":"第十二条","txt":"创办期刊、设立期刊出版单位，由期刊出版单位的主办单位提出申请，并提交以下材料： （一）按要求填写的《期刊出版申请表》； （二）主管单位、主办单位的有关资质证明材料； （三）拟任出版单位法定代表人或主要负责人简历、身份证明文件及国家有关部门颁发的职业资格证书； （四）编辑出版人员的职业资格证书； （五）办刊资金来源、数额及相关的证明文件； （六）期刊出版单位的章程； （七）工作场所使用证明； （八）期刊出版可行性论证报告。"},{"i":13,"n":"第十三条","txt":"新闻出版总署应当自收到创办期刊、设立期刊出版单位的申请之日起90日内，作出批准或者不批准的决定，并直接或者由省、自治区、直辖市新闻出版行政部门书面通知主办单位；不批准的，应当说明理由。"},{"i":14,"n":"第十四条","txt":"期刊主办单位应当自收到新闻出版总署批准决定之日起60日内办理注册登记手续： （一）持批准文件到所在地省、自治区、直辖市新闻出版行政部门领取《期刊出版登记表》，填写一式五份，经期刊主管单位审核签章后，报所在地省、自治区、直辖市新闻出版行政部门，省、自治区、直辖市新闻出版行政部门应在15日内，将《期刊出版登记表》报送新闻出版总署备案； （二）公开发行的期刊，可以向ISSN中国国家中心申领国际标准连续出版物号，并向新闻出版总署条码中心申领条形码； （三）省、自治区、直辖市新闻出版行政部门对《期刊出版登记表》审核无误后，在10日内向主办单位发放《期刊出版许可证》； （四）期刊出版单位持《期刊出版许可证》到工商行政管理部门办理登记手续，依法领取营业执照。 《期刊出版登记表》由期刊出版单位、主办单位、主管单位及所在地省、自治区、直辖市新闻出版行政部门各留存一份。"},{"i":15,"n":"第十五条","txt":"期刊主办单位自收到新闻出版总署的批准文件之日起60日内未办理注册登记手续，批准文件自行失效，登记机关不再受理登记，期刊主办单位须把有关批准文件缴回新闻出版总署。 期刊出版单位自登记之日起满90日未出版期刊的，由新闻出版总署撤销《期刊出版许可证》，并由原登记的新闻出版行政部门注销登记。 因不可抗力或者其他正当理由发生前款所列情形的，期刊出版单位可以向原登记的新闻出版行政部门申请延期。"},{"i":16,"n":"第十六条","txt":"期刊社应当具备法人条件，经核准登记后，取得法人资格，以其全部法人财产独立承担民事责任。 期刊编辑部不具有法人资格，其民事责任由其主办单位承担。"},{"i":17,"n":"第十七条","txt":"期刊出版单位变更名称、合并或者分立、改变资本结构，出版新的期刊，依照本规定第十条至第十四条的规定办理审批、登记手续。"},{"i":18,"n":"第十八条","txt":"期刊变更名称、主办单位或主管单位、业务范围、刊期的，依照本规定第十条至第十四条的规定办理审批、登记手续。 期刊变更登记地，经主管、主办单位同意后，由期刊出版单位到新登记地省、自治区、直辖市新闻出版行政部门办理登记手续。 期刊变更刊期，新闻出版总署可以委托省、自治区、直辖市新闻出版行政部门审批。 本规定所称期刊业务范围包括办刊宗旨、文种。"},{"i":19,"n":"第十九条","txt":"期刊出版单位变更期刊开本、法定代表人或者主要负责人、在同一登记地内变更地址，经其主办单位审核同意后，由期刊出版单位在15日内向所在地省、自治区、直辖市新闻出版行政部门备案。"},{"i":20,"n":"第二十条","txt":"期刊休刊，期刊出版单位须向所在地省、自治区、直辖市新闻出版行政部门备案并说明休刊理由和期限。 期刊休刊时间不得超过一年。休刊超过一年的，由新闻出版总署撤销《期刊出版许可证》，所在地省、自治区、直辖市新闻出版行政部门注销登记。"},{"i":21,"n":"第二十一条","txt":"期刊出版单位终止期刊出版活动的，经主管单位同意后，由其主办单位向所在地省、自治区、直辖市新闻出版行政部门办理注销登记，并由省、自治区、直辖市新闻出版行政部门报新闻出版总署备案。"},{"i":22,"n":"第二十二条","txt":"期刊注销登记，以同一名称设立的期刊出版单位须与期刊同时注销，并到原登记的工商行政管理部门办理注销登记。 注销登记的期刊和期刊出版单位不得再以该名称从事出版、经营活动。"},{"i":23,"n":"第二十三条","txt":"中央期刊出版单位组建期刊集团，由新闻出版总署批准；地方期刊出版单位组建期刊集团，向所在地省、自治区、直辖市新闻出版行政部门提出申请，经审核同意后，报新闻出版总署批准。"},{"i":24,"n":"第二十四条","txt":"期刊出版实行编辑责任制度，保障期刊刊载内容符合国家法律、法规的规定。"},{"i":25,"n":"第二十五条","txt":"期刊不得刊载《出版管理条例》和其他有关法律、法规以及国家规定的禁止内容。"},{"i":26,"n":"第二十六条","txt":"期刊刊载的内容不真实、不公正，致使公民、法人或者其他组织的合法权益受到侵害的，期刊出版单位应当公开更正，消除影响，并依法承担其他民事责任。 期刊刊载的内容不真实、不公正，致使公民、法人或者其他组织的合法权益受到侵害的，当事人有权要求期刊出版单位更正或者答辩，期刊出版单位应当在其最近出版的一期期刊上予以发表；拒绝发表的，当事人可以向人民法院提出诉讼。 期刊刊载的内容不真实、不公正，损害公共利益的，新闻出版总署或者省、自治区、直辖市新闻出版行政部门可以责令该期刊出版单位更正。"},{"i":27,"n":"第二十七条","txt":"期刊刊载涉及国家安全、社会安定等重大选题的内容，须按照重大选题备案管理规定办理备案手续。"},{"i":28,"n":"第二十八条","txt":"公开发行的期刊不得转载、摘编内部发行出版物的内容。 期刊转载、摘编互联网上的内容，必须按照有关规定对其内容进行核实，并在刊发的明显位置标明下载文件网址、下载日期等。"},{"i":29,"n":"第二十九条","txt":"期刊出版单位与境外出版机构开展合作出版项目，须经新闻出版总署批准，具体办法另行规定。"},{"i":30,"n":"第三十条","txt":"期刊出版质量须符合国家标准和行业标准。期刊使用语言文字须符合国家有关规定。"},{"i":31,"n":"第三十一条","txt":"期刊须在封底或版权页上刊载以下版本记录：期刊名称、主管单位、主办单位、出版单位、印刷单位、发行单位、出版日期、总编辑（主编）姓名、发行范围、定价、国内统一连续出版物号、广告经营许可证号等。 领取国际标准连续出版物号的期刊须同时刊印国际标准连续出版物号。"},{"i":32,"n":"第三十二条","txt":"期刊须在封面的明显位置刊载期刊名称和年、月、期、卷等顺序编号，不得以总期号代替年、月、期号。 期刊封面其他文字标识不得明显于刊名。 期刊的外文刊名须是中文刊名的直译。外文期刊封面上必须同时刊印中文刊名；少数民族文种期刊封面上必须同时刊印汉语刊名。"},{"i":33,"n":"第三十三条","txt":"一个国内统一连续出版物号只能对应出版一种期刊，不得用同一国内统一连续出版物号出版不同版本的期刊。 出版不同版本的期刊，须按创办新期刊办理审批手续。"},{"i":34,"n":"第三十四条","txt":"期刊可以在正常刊期之外出版增刊。每种期刊每年可以出版两期增刊。 期刊出版单位出版增刊，应当经其主管单位审核同意后，由主办单位报所在地省、自治区、直辖市新闻出版行政部门备案。备案文件应当说明拟出增刊的出版理由、出版时间、文章编目、期数、页码、印数、印刷单位等；所在地省、自治区、直辖市新闻出版行政部门备案后，发给备案证明文件，配发增刊备案号。 增刊内容必须符合正刊的业务范围，开本和发行范围必须与正刊一致；增刊除刊印本规定第三十一条所列版本纪录外，还须刊印增刊备案号，并在封面刊印正刊名称和注明“增刊”。"},{"i":35,"n":"第三十五条","txt":"期刊合订本须按原期刊出版顺序装订，不得对期刊内容另行编排，并在其封面明显位置标明期刊名称及“合订本”字样。 期刊因内容违法被新闻出版行政部门给予行政处罚的，该期期刊的相关篇目不得收入合订本。 被注销登记的期刊，不得制作合订本。"},{"i":36,"n":"第三十六条","txt":"期刊出版单位不得出卖、出租、转让本单位名称及所出版期刊的刊号、名称、版面，不得转借、转让、出租和出卖《期刊出版许可证》。"},{"i":37,"n":"第三十七条","txt":"期刊出版单位利用其期刊开展广告业务，必须遵守广告法律规定，发布广告须依法查验有关证明文件，核实广告内容，不得刊登有害的、虚假的等违法广告。 期刊的广告经营者限于在合法授权范围内开展广告经营、代理业务，不得参与期刊的采访、编辑等出版活动。"},{"i":38,"n":"第三十八条","txt":"期刊采编业务与经营业务必须严格分开。 禁止以采编报道相威胁，以要求被报道对象做广告、提供赞助、加入理事会等损害被报道对象利益的行为牟取不正当利益。 期刊不得刊登任何形式的有偿新闻。"},{"i":39,"n":"第三十九条","txt":"期刊出版单位的新闻采编人员从事新闻采访活动，必须持有新闻出版总署统一核发的新闻记者证，并遵守新闻出版总署《新闻记者证管理办法》的有关规定。"},{"i":40,"n":"第四十条","txt":"具有新闻采编业务的期刊出版单位在登记地以外的地区设立记者站，参照新闻出版总署《报社记者站管理办法》审批、管理。其他期刊出版单位一律不得设立记者站。 期刊出版单位是否具有新闻采编业务由新闻出版总署认定。"},{"i":41,"n":"第四十一条","txt":"期刊出版单位不得以不正当竞争行为或者方式开展经营活动，不得利用权力摊派发行期刊。"},{"i":42,"n":"第四十二条","txt":"期刊出版单位须遵守国家统计法规，依法向新闻出版行政部门报送统计资料。 期刊出版单位应配合国家认定的出版物发行数据调查机构进行期刊发行数据调查，提供真实的期刊发行数据。"},{"i":43,"n":"第四十三条","txt":"期刊出版单位须在每期期刊出版30日内，分别向新闻出版总署、中国版本图书馆、国家图书馆以及所在地省、自治区、直辖市新闻出版行政部门缴送样刊3本。"},{"i":44,"n":"第四十四条","txt":"期刊出版活动的监督管理实行属地原则。 省、自治区、直辖市新闻出版行政部门依法负责对本行政区域期刊和期刊出版单位的登记、年度核验、质量评估、行政处罚等工作，对本行政区域的期刊出版活动进行监督管理。 其他地方新闻出版行政部门依法对本行政区域内期刊出版单位及其期刊出版活动进行监督管理。"},{"i":45,"n":"第四十五条","txt":"期刊出版管理实施期刊出版事后审读制度、期刊出版质量评估制度、期刊年度核验制度和期刊出版从业人员资格管理制度。 期刊出版单位应当按照新闻出版总署的规定，将从事期刊出版活动的情况向新闻出版行政部门提出书面报告。"},{"i":46,"n":"第四十六条","txt":"新闻出版总署负责全国期刊审读工作。地方各级新闻出版行政部门负责对本行政区域内出版的期刊进行审读。下级新闻出版行政部门要定期向上一级新闻出版行政部门提交审读报告。 主管单位须对其主管的期刊进行审读，定期向所在地新闻出版行政部门报送审读报告。 期刊出版单位应建立期刊阅评制度，定期写出阅评报告。新闻出版行政部门根据管理工作的需要，可以随时调阅、检查期刊出版单位的阅评报告。"},{"i":47,"n":"第四十七条","txt":"新闻出版总署制定期刊出版质量综合评估标准体系，对期刊出版质量进行全面评估。 经期刊出版质量综合评估，期刊出版质量未达到规定标准或者不能维持正常出版活动的，由新闻出版总署撤销《期刊出版许可证》，所在地省、自治区、直辖市新闻出版行政部门注销登记。"},{"i":48,"n":"第四十八条","txt":"省、自治区、直辖市新闻出版行政部门负责对本行政区域的期刊实施年度核验。年度核验内容包括期刊出版单位及其所出版期刊登记项目、出版质量、遵纪守法情况等。"},{"i":49,"n":"第四十九条","txt":"年度核验按照以下程序进行： （一）期刊出版单位提出年度自检报告，填写由新闻出版总署统一印制的《期刊登记项目年度核验表》，经期刊主办单位、主管单位审核盖章后，连同本年度出版的样刊报省、自治区、直辖市新闻出版行政部门； （二）省、自治区、直辖市新闻出版行政部门对期刊出版单位自检报告、《期刊登记项目年度核验表》及样刊进行审核查验； （三）经核验符合规定标准的，省、自治区、直辖市新闻出版行政部门在《期刊出版许可证》上加盖年度核验章；《期刊出版许可证》上加盖年度核验章即为通过年度核验，期刊出版单位可以继续从事期刊出版活动； （四）省、自治区、直辖市新闻出版行政部门在完成期刊年度核验工作30日内向新闻出版总署提交期刊年度核验工作报告。"},{"i":50,"n":"第五十条","txt":"有下列情形之一的，暂缓年度核验： （一）正在限期停业整顿的； （二）经审核发现有违法情况应予处罚的； （三）主管单位、主办单位未履行管理责任，导致期刊出版管理混乱的； （四）存在其他违法嫌疑需要进一步核查的。 暂缓年度核验的期限由省、自治区、直辖市新闻出版行政部门确定，报新闻出版总署备案。缓验期满，按本规定第四十八条、第四十九条重新办理年度核验。"},{"i":51,"n":"第五十一条","txt":"期刊有下列情形之一的，不予通过年度核验： （一）违法行为被查处后拒不改正或者没有明显整改效果的； （二）期刊出版质量长期达不到规定标准的； （三）经营恶化已经资不抵债的； （四）已经不具备本规定第九条规定条件的。 不予通过年度核验的，由新闻出版总署撤销《期刊出版许可证》，所在地省、自治区、直辖市新闻出版行政部门注销登记。 未通过年度核验的，期刊出版单位自第二年起停止出版该期刊。"},{"i":52,"n":"第五十二条","txt":"《期刊出版许可证》加盖年度核验章后方可继续使用。有关部门在办理期刊出版、印刷、发行等手续时，对未加盖年度核验章的《期刊出版许可证》不予采用。 不按规定参加年度核验的期刊出版单位，经催告仍未参加年度核验的，由新闻出版总署撤销《期刊出版许可证》，所在地省、自治区、直辖市新闻出版行政部门注销登记。"},{"i":53,"n":"第五十三条","txt":"年度核验结果，核验机关可以向社会公布。"},{"i":54,"n":"第五十四条","txt":"期刊出版从业人员，应具备国家规定的新闻出版职业资格条件。"},{"i":55,"n":"第五十五条","txt":"期刊出版单位的社长、总编辑须符合国家规定的任职资格和条件。 期刊出版单位的社长、总编辑须参加新闻出版行政部门组织的岗位培训。 期刊出版单位的新任社长、总编辑须经过岗位培训合格后才能上岗。"},{"i":56,"n":"第五十六条","txt":"期刊出版单位违反本规定的，新闻出版行政部门视其情节轻重，可以采取下列行政措施： （一）下达警示通知书； （二）通报批评； （三）责令公开检讨； （四）责令改正； （五）责令停止印制、发行期刊； （六）责令收回期刊； （七）责成主办单位、主管单位监督期刊出版单位整改。 警示通知书由新闻出版总署制定统一格式，由新闻出版总署或者省、自治区、直辖市新闻出版行政部门下达给违法的期刊出版单位，并抄送违法期刊出版单位的主办单位及其主管单位。 本条所列行政措施可以并用。"},{"i":57,"n":"第五十七条","txt":"未经批准，擅自设立期刊出版单位，或者擅自从事期刊出版业务，假冒期刊出版单位名称或者伪造、假冒期刊名称出版期刊的，依照《出版管理条例》第六十一条处罚。 期刊出版单位未履行备案手续擅自出版增刊、擅自与境外出版机构开展合作出版项目的，按前款处罚。"},{"i":58,"n":"第五十八条","txt":"出版含有《出版管理条例》和其他有关法律、法规以及国家规定禁载内容期刊的，依照《出版管理条例》第六十二条处罚。"},{"i":59,"n":"第五十九条","txt":"期刊出版单位违反本规定第三十六条的，依照《出版管理条例》第六十六条处罚。 期刊出版单位允许或者默认广告经营者参与期刊采访、编辑等出版活动的，按前款处罚。"},{"i":60,"n":"第六十条","txt":"期刊出版单位有下列行为之一的，依照《出版管理条例》第六十七条处罚： （一）期刊变更名称、主办单位或主管单位、业务范围、刊期，未依照本规定办理审批手续的； （二）期刊出版单位变更名称、合并或分立、改变资本结构、出版新的期刊，未依照本规定办理审批手续的； （三）期刊出版单位未将涉及国家安全、社会安定等方面的重大选题备案的； （四）期刊出版单位未依照本规定缴送样刊的。"},{"i":61,"n":"第六十一条","txt":"期刊出版单位违反本规定第四条第二款的，依照新闻出版总署《出版物市场管理规定》第四十八条处罚。"},{"i":62,"n":"第六十二条","txt":"期刊出版单位有下列行为之一的，由新闻出版总署或者省、自治区、直辖市新闻出版行政部门给予警告，并处3万元以下罚款： （一）期刊出版单位变更期刊开本、法定代表人或者主要负责人、在同一登记地内变更地址，未按本规定第十九条报送备案的； （二）期刊休刊未按本规定第二十条报送备案的； （三）刊载损害公共利益的虚假或者失实报道，拒不执行新闻出版行政部门更正命令的； （四）公开发行的期刊转载、摘编内部发行出版物内容的； （五）期刊转载、摘编互联网上的内容，违反本规定第二十八条第二款的； （六）未按照本规定第三十一条刊载期刊版本记录的； （七）违反本规定第三十二条关于期刊封面标识的规定的； （八）违反本规定第三十三条，“一号多刊”的； （九）出版增刊违反本规定第三十四条第三款的； （十）违反本规定第三十五条制作期刊合订本的； （十一）刊登有偿新闻或者违反本规定第三十八条其他规定的； （十二）违反本规定第"},{"i":63,"n":"第六十三条","txt":"期刊出版单位新闻采编人员违反新闻记者证的有关规定，依照新闻出版总署《新闻记者证管理办法》的规定处罚。"},{"i":64,"n":"第六十四条","txt":"期刊出版单位违反记者站的有关规定，依照新闻出版总署《报社记者站管理办法》的规定处罚。"},{"i":65,"n":"第六十五条","txt":"对期刊出版单位做出行政处罚，新闻出版行政部门应告知其主办单位和主管单位，可以通过媒体向社会公布。 对期刊出版单位做出行政处罚，新闻出版行政部门可以建议其主办单位或者主管单位对直接责任人和主要负责人予以行政处分或者调离岗位。"},{"i":66,"n":"第六十六条","txt":"本规定施行后，新闻出版署《期刊管理暂行规定》和《〈期刊管理暂行规定〉行政处罚实施办法》同时废止，此前新闻出版行政部门对期刊出版活动的其他规定，凡与本规定不一致的，以本规定为准。"},{"i":67,"n":"第六十七条","txt":"本规定自2005年12月1日起施行。"}],"dianzichubanwuchubanguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对电子出版物出版活动的管理，促进电子出版事业的健康发展与繁荣，根据国务院《出版管理条例》、《国务院对确需保留的行政审批项目设定行政许可的决定》和有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事电子出版物的制作、出版、进口活动，适用本规定。 本规定所称电子出版物，是指以数字代码方式，将有知识性、思想性内容的信息编辑加工后存储在固定物理形态的磁、光、电等介质上，通过电子阅读、显示、播放设备读取使用的大众传播媒体，包括只读光盘（CD-ROM、DVD-ROM等）、一次写入光盘（CD-R、DVD-R等）、可擦写光盘（CD-RW、DVD-RW等）、软磁盘、硬磁盘、集成电路卡等，以及新闻出版总署认定的其他媒体形态。"},{"i":3,"n":"第三条","txt":"电子出版物不得含有《出版管理条例》第二十六条、第二十七条禁止的内容。"},{"i":4,"n":"第四条","txt":"新闻出版总署负责全国电子出版物出版活动的监督管理工作。 县级以上地方新闻出版行政部门负责本行政区域内电子出版物出版活动的监督管理工作。"},{"i":5,"n":"第五条","txt":"国家对电子出版物出版活动实行许可制度；未经许可，任何单位和个人不得从事电子出版物的出版活动。"},{"i":6,"n":"第六条","txt":"设立电子出版物出版单位，应当具备下列条件： （一）有电子出版物出版单位的名称、章程； （二）有符合新闻出版总署认定条件的主管、主办单位； （三）有确定的电子出版物出版业务范围； （四）有适应业务范围需要的设备和工作场所； （五）有适应业务范围需要的组织机构，有2人以上具有中级以上出版专业职业资格； （六）法律、行政法规规定的其他条件。 除依照前款所列条件外，还应当符合国家关于电子出版物出版单位总量、结构、布局的规划。"},{"i":7,"n":"第七条","txt":"设立电子出版物出版单位，经其主管单位同意后，由主办单位向所在地省、自治区、直辖市新闻出版行政部门提出申请；经省、自治区、直辖市新闻出版行政部门审核同意后，报新闻出版总署审批。"},{"i":8,"n":"第八条","txt":"申请设立电子出版物出版单位，应当提交下列材料： （一）按要求填写的申请表，应当载明出版单位的名称、地址、资本结构、资金来源及数额，出版单位的主管、主办单位的名称和地址等内容； （二）主办单位、主管单位的有关资质证明材料； （三）出版单位章程； （四）法定代表人或者主要负责人及本规定第六条要求的有关人员的资格证明和身份证明； （五）可行性论证报告； （六）注册资本数额、来源及性质证明； （七）工作场所使用证明。"},{"i":9,"n":"第九条","txt":"新闻出版总署自受理设立电子出版物出版单位的申请之日起90日内，作出批准或者不批准的决定，直接或者由省、自治区、直辖市新闻出版行政部门书面通知主办单位；不批准的，应当说明理由。"},{"i":10,"n":"第十条","txt":"设立电子出版物出版单位的主办单位应当自收到批准决定之日起60日内，向所在地省、自治区、直辖市新闻出版行政部门登记，领取新闻出版总署颁发的《电子出版物出版许可证》。 电子出版物出版单位持《电子出版物出版许可证》向所在地工商行政管理部门登记，依法领取营业执照。"},{"i":11,"n":"第十一条","txt":"电子出版物出版单位自登记之日起满180日未从事出版活动的，由省、自治区、直辖市新闻出版行政部门注销登记，收回《电子出版物出版许可证》，并报新闻出版总署备案。 因不可抗力或者其他正当理由发生前款所列情形的，电子出版物出版单位可以向省、自治区、直辖市新闻出版行政部门申请延期。"},{"i":12,"n":"第十二条","txt":"电子出版物出版单位变更名称、主办单位或者主管单位、业务范围、资本结构，合并或者分立，须依照本规定第七条、第八条的规定重新办理审批手续，并到原登记的工商行政管理部门办理相应的登记手续。 电子出版物出版单位变更地址、法定代表人或者主要负责人的，应当经其主管、主办单位同意，向所在地省、自治区、直辖市新闻出版行政部门申请变更登记后，到原登记的工商行政管理部门办理变更登记。 省、自治区、直辖市新闻出版行政部门须将有关变更登记事项报新闻出版总署备案。"},{"i":13,"n":"第十三条","txt":"电子出版物出版单位终止出版活动的，应当向所在地省、自治区、直辖市新闻出版行政部门办理注销登记手续，并到原登记的工商行政管理部门办理注销登记。 省、自治区、直辖市新闻出版行政部门应将有关注销登记报新闻出版总署备案。"},{"i":14,"n":"第十四条","txt":"申请出版连续型电子出版物，经主管单位同意后，由主办单位向所在地省、自治区、直辖市新闻出版行政部门提出申请；经省、自治区、直辖市新闻出版行政部门审核同意后，报新闻出版总署审批。 本规定所称连续型电子出版物，是指有固定名称，用卷、期、册或者年、月顺序编号，按照一定周期出版的电子出版物。"},{"i":15,"n":"第十五条","txt":"申请出版连续型电子出版物，应当提交下列材料： （一）申请书，应当载明连续型电子出版物的名称、刊期、媒体形态、业务范围、读者对象、栏目设置、文种等； （二）主管单位的审核意见。 申请出版配报纸、期刊的连续型电子出版物，还须报送报纸、期刊样本。"},{"i":16,"n":"第十六条","txt":"经批准出版的连续型电子出版物，新增或者改变连续型电子出版物的名称、刊期与出版范围的，须按照本规定第十四条、第十五条办理审批手续。"},{"i":17,"n":"第十七条","txt":"出版行政部门对从事电子出版物制作的单位实行备案制管理。电子出版物制作单位应当于单位设立登记以及有关变更登记之日起30日内，将单位名称、地址、法定代表人或者主要负责人的姓名及营业执照复印件、法定代表人或主要负责人身份证明报所在地省、自治区、直辖市新闻出版行政部门备案。 本规定所称电子出版物制作，是指通过创作、加工、设计等方式，提供用于出版、复制、发行的电子出版物节目源的经营活动。"},{"i":18,"n":"第十八条","txt":"电子出版物出版单位实行编辑责任制度，保障电子出版物的内容符合有关法规、规章规定。"},{"i":19,"n":"第十九条","txt":"电子出版物出版单位应于每年12月1日前将下一年度的出版计划报所在地省、自治区、直辖市新闻出版行政部门，省、自治区、直辖市新闻出版行政部门审核同意后报新闻出版总署备案。"},{"i":20,"n":"第二十条","txt":"电子出版物出版实行重大选题备案制度。涉及国家安全、社会安定等方面重大选题，涉及重大革命题材和重大历史题材的选题，应当按照新闻出版总署有关选题备案的规定办理备案手续；未经备案的重大选题，不得出版。"},{"i":21,"n":"第二十一条","txt":"出版电子出版物，必须按规定使用中国标准书号。同一内容，不同载体形态、格式的电子出版物，应当分别使用不同的中国标准书号。 出版连续型电子出版物，必须按规定使用国内统一连续出版物号，不得使用中国标准书号出版连续型电子出版物。"},{"i":22,"n":"第二十二条","txt":"电子出版物出版单位不得以任何形式向任何单位或者个人转让、出租、出售本单位的名称、电子出版物中国标准书号、国内统一连续出版物号。"},{"i":23,"n":"第二十三条","txt":"电子出版物应当符合国家的技术、质量标准和规范要求。 出版电子出版物，须在电子出版物载体的印刷标识面或其装帧的显著位置载明电子出版物制作、出版单位的名称，中国标准书号或国内统一连续出版物号及条码，著作权人名称以及出版日期等其他有关事项。"},{"i":24,"n":"第二十四条","txt":"电子出版物出版单位申请出版境外著作权人授权的电子出版物，须向所在地省、自治区、直辖市新闻出版行政部门提出申请；所在地省、自治区、直辖市新闻出版行政部门审核同意后，报新闻出版总署审批。"},{"i":25,"n":"第二十五条","txt":"申请出版境外著作权人授权的电子出版物，应当提交下列材料： （一）申请书，应当载明电子出版物名称、内容简介、授权方名称、授权方基本情况介绍等； （二）申请单位的审读报告； （三）样品及必要的内容资料； （四）申请单位所在地省、自治区、直辖市著作权行政管理部门的著作权合同登记证明文件。 出版境外著作权人授权的电子游戏出版物还须提交游戏主要人物和主要场景图片资料、代理机构营业执照、发行合同及发行机构批发许可证、游戏文字脚本全文等材料。"},{"i":26,"n":"第二十六条","txt":"新闻出版总署自受理出版境外著作权人授权电子出版物申请之日起，20日内作出批准或者不批准的决定；不批准的，应当说明理由。 审批出版境外著作权人授权电子出版物，应当组织专家评审，并应当符合国家总量、结构、布局规划。"},{"i":27,"n":"第二十七条","txt":"境外著作权人授权的电子出版物，须在电子出版物载体的印刷标识面或其装帧的显著位置载明引进出版批准文号和著作权授权合同登记证号。"},{"i":28,"n":"第二十八条","txt":"已经批准出版的境外著作权人授权的电子出版物，若出版升级版本，须按照本规定第二十五条提交申请材料，报所在地省、自治区、直辖市新闻出版行政部门审批。"},{"i":29,"n":"第二十九条","txt":"出版境外著作权人授权的电子游戏测试盘及境外互联网游戏作品客户端程序光盘，须按照本规定第二十五条提交申请材料，报所在地省、自治区、直辖市新闻出版行政部门审批。"},{"i":30,"n":"第三十条","txt":"电子出版物出版单位与境外机构合作出版电子出版物，须经主管单位同意后，将选题报所在地省、自治区、直辖市新闻出版行政部门审核；省、自治区、直辖市新闻出版行政部门审核同意后，报新闻出版总署审批。 新闻出版总署自受理合作出版电子出版物选题申请之日起20日内，作出批准或者不批准的决定；不批准的，应当说明理由。"},{"i":31,"n":"第三十一条","txt":"电子出版物出版单位申请与境外机构合作出版电子出版物，应当提交下列材料： （一）申请书，应当载明合作出版的电子出版物的名称、载体形态、内容简介、合作双方名称、基本情况、合作方式等，并附拟合作出版的电子出版物的有关文字内容、图片等材料； （二）合作意向书； （三）主管单位的审核意见。"},{"i":32,"n":"第三十二条","txt":"电子出版物出版单位与境外机构合作出版电子出版物，应在该电子出版物出版30日内将样盘报送新闻出版总署备案。"},{"i":33,"n":"第三十三条","txt":"出版单位配合本版出版物出版电子出版物，向所在地省、自治区、直辖市新闻出版行政部门提出申请，省、自治区、直辖市新闻出版行政部门审核同意的，发放电子出版物中国标准书号和复制委托书，并报新闻出版总署备案。"},{"i":34,"n":"第三十四条","txt":"出版单位申请配合本版出版物出版电子出版物，应提交申请书及本版出版物、拟出版电子出版物样品。 申请书应当载明配合本版出版物出版的电子出版物的名称、制作单位、主要内容、出版时间、复制数量和载体形式等内容。"},{"i":35,"n":"第三十五条","txt":"电子出版物发行前，出版单位应当向国家图书馆、中国版本图书馆和新闻出版总署免费送交样品。"},{"i":36,"n":"第三十六条","txt":"电子出版物出版单位的从业人员，应当具备国家规定的出版专业职业资格条件。 电子出版物出版单位的社长、总编辑须符合国家规定的任职资格和条件。 电子出版物出版单位的社长、总编辑须参加新闻出版行政部门组织的岗位培训，取得岗位培训合格证书后才能上岗。"},{"i":37,"n":"第三十七条","txt":"电子出版物出版单位须遵守国家统计规定，依法向新闻出版行政部门报送统计资料。"},{"i":38,"n":"第三十八条","txt":"进口电子出版物成品，须由新闻出版总署批准的电子出版物进口经营单位提出申请；所在地省、自治区、直辖市新闻出版行政部门审核同意后，报新闻出版总署审批。"},{"i":39,"n":"第三十九条","txt":"申请进口电子出版物，应当提交下列材料： （一）申请书，应当载明进口电子出版物的名称、内容简介、出版者名称、地址、进口数量等； （二）主管单位审核意见； （三）申请单位关于进口电子出版物的审读报告； （四）进口电子出版物的样品及必要的内容资料。"},{"i":40,"n":"第四十条","txt":"新闻出版总署自受理进口电子出版物申请之日起20日内，作出批准或者不批准的决定；不批准的，应当说明理由。 审批进口电子出版物，应当组织专家评审，并应当符合国家总量、结构、布局规划。"},{"i":41,"n":"第四十一条","txt":"进口电子出版物的外包装上应贴有标识，载明批准进口文号及用中文注明的出版者名称、地址、著作权人名称、出版日期等有关事项。"},{"i":42,"n":"第四十二条","txt":"委托复制电子出版物非卖品，须向委托方或受托方所在地省、自治区、直辖市新闻出版行政部门提出申请，申请书应写明电子出版物非卖品的使用目的、名称、内容、发送对象、复制数量、载体形式等，并附样品。 电子出版物非卖品内容限于公益宣传、企事业单位业务宣传、交流、商品介绍等，不得定价，不得销售、变相销售或与其他商品搭配销售。"},{"i":43,"n":"第四十三条","txt":"省、自治区、直辖市新闻出版行政部门应当自受理委托复制电子出版物非卖品申请之日起20日内，作出批准或者不批准的决定，批准的，发给电子出版物复制委托书；不批准的，应当说明理由。"},{"i":44,"n":"第四十四条","txt":"电子出版物非卖品载体的印刷标识面及其装帧的显著位置应当注明电子出版物非卖品统一编号，编号分为四段：第一段为方括号内的各省、自治区、直辖市简称，第二段为“电子出版物非卖品”字样，第三段为圆括号内的年度，第四段为顺序编号。"},{"i":45,"n":"第四十五条","txt":"电子出版物、电子出版物非卖品应当委托经新闻出版总署批准设立的复制单位复制。"},{"i":46,"n":"第四十六条","txt":"委托复制电子出版物和电子出版物非卖品，必须使用复制委托书，并遵守国家关于复制委托书的管理规定。 复制委托书由新闻出版总署统一印制。"},{"i":47,"n":"第四十七条","txt":"委托复制电子出版物、电子出版物非卖品的单位，应当保证开具的复制委托书内容真实、准确、完整，并须将开具的复制委托书直接交送复制单位。 委托复制电子出版物、电子出版物非卖品的单位不得以任何形式向任何单位或者个人转让、出售本单位的复制委托书。"},{"i":48,"n":"第四十八条","txt":"委托复制电子出版物的单位，自电子出版物完成复制之日起30日内，须向所在地省、自治区、直辖市新闻出版行政部门上交本单位及复制单位签章的复制委托书第二联及样品。 委托复制电子出版物的单位须将电子出版物复制委托书第四联保存2年备查。"},{"i":49,"n":"第四十九条","txt":"委托复制电子出版物、电子出版物非卖品的单位，经批准获得电子出版物复制委托书之日起90日内未使用的，须向发放该委托书的省、自治区、直辖市新闻出版行政部门交回复制委托书。"},{"i":50,"n":"第五十条","txt":"电子出版物出版单位实行年度核验制度，年度核验每两年进行一次。省、自治区、直辖市新闻出版行政部门负责对本行政区域内的电子出版物出版单位实施年度核验。核验内容包括电子出版物出版单位的登记项目、设立条件、出版经营情况、遵纪守法情况、内部管理情况等。"},{"i":51,"n":"第五十一条","txt":"电子出版物出版单位进行年度核验，应提交以下材料： （一）电子出版物出版单位年度核验登记表； （二）电子出版物出版单位两年的总结报告，应当包括执行出版法规的情况、出版业绩、资产变化等内容； （三）两年出版的电子出版物出版目录； （四）《电子出版物出版许可证》的复印件。"},{"i":52,"n":"第五十二条","txt":"电子出版物出版单位年度核验程序为： （一）电子出版物出版单位应于核验年度的1月15日前向所在地省、自治区、直辖市新闻出版行政部门提交年度核验材料； （二）各省、自治区、直辖市新闻出版行政部门对本行政区域内电子出版物出版单位的设立条件、开展业务及执行法规等情况进行全面审核，并于该年度的2月底前完成年度核验工作；对符合年度核验要求的单位予以登记，并换发《电子出版物出版许可证》； （三）各省、自治区、直辖市新闻出版行政部门应于核验年度的3月20日前将年度核验情况及有关书面材料报新闻出版总署备案。"},{"i":53,"n":"第五十三条","txt":"电子出版物出版单位有下列情形之一的，暂缓年度核验： （一）不具备本规定第六条规定条件的； （二）因违反出版管理法规，正在限期停业整顿的； （三）经审核发现有违法行为应予处罚的； （四）曾违反出版管理法规受到行政处罚，未认真整改，仍存在违法问题的； （五）长期不能正常开展电子出版物出版活动的。 暂缓年度核验的期限由省、自治区、直辖市新闻出版行政部门确定，最长不得超过3个月。暂缓期间，省、自治区、直辖市新闻出版行政部门应当督促、指导电子出版物出版单位进行整改。暂缓年度核验期满，对达到年度核验要求的电子出版物出版单位予以登记；仍未达到年度核验要求的电子出版物出版单位，由所在地省、自治区、直辖市新闻出版行政部门提出注销登记意见，新闻出版总署撤销《电子出版物出版许可证》，所在地省、自治区、直辖市新闻出版行政部门办理注销登记。"},{"i":54,"n":"第五十四条","txt":"不按规定参加年度核验的电子出版物出版单位，经书面催告仍未参加年度核验的，由所在地省、自治区、直辖市新闻出版行政部门提出注销登记意见，新闻出版总署撤销《电子出版物出版许可证》，所在地省、自治区、直辖市新闻出版行政部门办理注销登记。"},{"i":55,"n":"第五十五条","txt":"出版连续型电子出版物的单位按照本章规定参加年度核验。"},{"i":56,"n":"第五十六条","txt":"电子出版物出版单位违反本规定的，新闻出版总署或者省、自治区、直辖市新闻出版行政部门可以采取下列行政措施： （一）下达警示通知书； （二）通报批评； （三）责令公开检讨； （四）责令改正； （五）责令停止复制、发行电子出版物； （六）责令收回电子出版物； （七）责成主办单位、主管单位监督电子出版物出版单位整改。 警示通知书由新闻出版总署制定统一格式，由新闻出版总署或者省、自治区、直辖市新闻出版行政部门下达给违法的电子出版物出版单位，并抄送违法电子出版物出版单位的主办单位及其主管单位。 本条所列行政措施可以并用。"},{"i":57,"n":"第五十七条","txt":"未经批准，擅自设立电子出版物出版单位，擅自从事电子出版物出版业务，伪造、假冒电子出版物出版单位或者连续型电子出版物名称、电子出版物专用中国标准书号出版电子出版物的，按照《出版管理条例》第五十五条处罚。 图书、报纸、期刊、音像等出版单位未经批准，配合本版出版物出版电子出版物的，属于擅自从事电子出版物出版业务，按照前款处罚。"},{"i":58,"n":"第五十八条","txt":"从事电子出版物制作、出版业务，有下列行为之一的，按照《出版管理条例》第五十六条处罚： （一）制作、出版含有《出版管理条例》第二十六条、第二十七条禁止内容的电子出版物的； （二）明知或者应知他人出版含有《出版管理条例》第二十六条、第二十七条禁止内容的电子出版物而向其出售、出租或者以其他形式转让本出版单位的名称、电子出版物专用中国标准书号、国内统一连续出版物号、条码及电子出版物复制委托书的。"},{"i":59,"n":"第五十九条","txt":"电子出版物出版单位出租、出借、出售或者以其他任何形式转让本单位的名称、电子出版物专用中国标准书号、国内统一连续出版物号的，按照《出版管理条例》第六十条处罚。"},{"i":60,"n":"第六十条","txt":"有下列行为之一的，按照《出版管理条例》第六十一条处罚： （一）电子出版物出版单位变更名称、主办单位或者主管单位、业务范围、资本结构，合并或者分立，电子出版物出版单位变更地址、法定代表人或者主要负责人，未依照本规定的要求办理审批、变更登记手续的； （二）经批准出版的连续型电子出版物，新增或者改变连续型电子出版物的名称、刊期与出版范围，未办理审批手续的； （三）电子出版物出版单位未按规定履行年度出版计划和重大选题备案的； （四）出版单位未按照有关规定送交电子出版物样品的； （五）电子出版物进口经营单位违反本规定第三十八条未经批准进口电子出版物的。"},{"i":61,"n":"第六十一条","txt":"电子出版物出版单位未依法向新闻出版行政部门报送统计资料的，依据新闻出版总署、国家统计局联合颁布的《新闻出版统计管理办法》处罚。"},{"i":62,"n":"第六十二条","txt":"有下列行为之一的，由新闻出版行政部门责令改正，给予警告，可并处三万元以下罚款： （一）电子出版物制作单位违反本规定第十七条，未办理备案手续的； （二）电子出版物出版单位违反本规定第二十一条，未按规定使用中国标准书号或者国内统一连续出版物号的； （三）电子出版物出版单位出版的电子出版物不符合国家的技术、质量标准和规范要求的，或者未按本规定第二十三条载明有关事项的； （四）电子出版物出版单位出版境外著作权人授权的电子出版物，违反本规定第二十四条、第二十七条、第二十八条、第二十九条有关规定的； （五）电子出版物出版单位与境外机构合作出版电子出版物，未按本规定第三十条办理选题审批手续的，未按本规定第三十二条将样盘报送备案的； （六）电子出版物进口经营单位违反本规定第四十一条的； （七）委托复制电子出版物非卖品违反本规定第四十二条的有关规定，或者未按第四十四条标明电子出版物非卖品统一编号的； （"},{"i":63,"n":"第六十三条","txt":"本规定自2008年4月15日起施行，新闻出版署1997年12月30日颁布的《电子出版物管理规定》同时废止，此前新闻出版行政部门对电子出版物制作、出版、进口活动的其他规定，凡与本规定不一致的，以本规定为准。"}],"wangluochubanfuwuguanliguiding":[{"i":1,"n":"第一条","txt":"为了规范网络出版服务秩序，促进网络出版服务业健康有序发展，根据《出版管理条例》、《互联网信息服务管理办法》及相关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事网络出版服务，适用本规定。 本规定所称网络出版服务，是指通过信息网络向公众提供网络出版物。 本规定所称网络出版物，是指通过信息网络向公众提供的，具有编辑、制作、加工等出版特征的数字化作品，范围主要包括： （一）文学、艺术、科学等领域内具有知识性、思想性的文字、图片、地图、游戏、动漫、音视频读物等原创数字化作品； （二）与已出版的图书、报纸、期刊、音像制品、电子出版物等内容相一致的数字化作品； （三）将上述作品通过选择、编排、汇集等方式形成的网络文献数据库等数字化作品； （四）国家新闻出版广电总局认定的其他类型的数字化作品。 网络出版服务的具体业务分类另行制定。"},{"i":3,"n":"第三条","txt":"从事网络出版服务，应当遵守宪法和有关法律、法规，坚持为人民服务、为社会主义服务的方向，坚持社会主义先进文化的前进方向，弘扬社会主义核心价值观，传播和积累一切有益于提高民族素质、推动经济发展、促进社会进步的思想道德、科学技术和文化知识，满足人民群众日益增长的精神文化需要。"},{"i":4,"n":"第四条","txt":"国家新闻出版广电总局作为网络出版服务的行业主管部门，负责全国网络出版服务的前置审批和监督管理工作。工业和信息化部作为互联网行业主管部门，依据职责对全国网络出版服务实施相应的监督管理。 地方人民政府各级出版行政主管部门和各省级电信主管部门依据各自职责对本行政区域内网络出版服务及接入服务实施相应的监督管理工作并做好配合工作。"},{"i":5,"n":"第五条","txt":"出版行政主管部门根据已经取得的违法嫌疑证据或者举报，对涉嫌违法从事网络出版服务的行为进行查处时，可以检查与涉嫌违法行为有关的物品和经营场所；对有证据证明是与违法行为有关的物品，可以查封或者扣押。"},{"i":6,"n":"第六条","txt":"国家鼓励图书、音像、电子、报纸、期刊出版单位从事网络出版服务，加快与新媒体的融合发展。 国家鼓励组建网络出版服务行业协会，按照章程，在出版行政主管部门的指导下制定行业自律规范，倡导网络文明，传播健康有益内容，抵制不良有害内容。"},{"i":7,"n":"第七条","txt":"从事网络出版服务，必须依法经过出版行政主管部门批准，取得《网络出版服务许可证》。"},{"i":8,"n":"第八条","txt":"图书、音像、电子、报纸、期刊出版单位从事网络出版服务，应当具备以下条件： （一）有确定的从事网络出版业务的网站域名、智能终端应用程序等出版平台； （二）有确定的网络出版服务范围； （三）有从事网络出版服务所需的必要的技术设备，相关服务器和存储设备必须存放在中华人民共和国境内。"},{"i":9,"n":"第九条","txt":"其他单位从事网络出版服务，除第八条所列条件外，还应当具备以下条件： （一）有确定的、不与其他出版单位相重复的，从事网络出版服务主体的名称及章程； （二）有符合国家规定的法定代表人和主要负责人，法定代表人必须是在境内长久居住的具有完全行为能力的中国公民，法定代表人和主要负责人至少1人应当具有中级以上出版专业技术人员职业资格； （三）除法定代表人和主要负责人外，有适应网络出版服务范围需要的8名以上具有国家新闻出版广电总局认可的出版及相关专业技术职业资格的专职编辑出版人员，其中具有中级以上职业资格的人员不得少于3名； （四）有从事网络出版服务所需的内容审校制度； （五）有固定的工作场所； （六）法律、行政法规和国家新闻出版广电总局规定的其他条件。"},{"i":10,"n":"第十条","txt":"中外合资经营、中外合作经营和外资经营的单位不得从事网络出版服务。 网络出版服务单位与境内中外合资经营、中外合作经营、外资经营企业或境外组织及个人进行网络出版服务业务的项目合作，应当事前报国家新闻出版广电总局审批。"},{"i":11,"n":"第十一条","txt":"申请从事网络出版服务，应当向所在地省、自治区、直辖市出版行政主管部门提出申请，经审核同意后，报国家新闻出版广电总局审批。国家新闻出版广电总局应当自受理申请之日起60日内，作出批准或者不予批准的决定。不批准的，应当说明理由。"},{"i":12,"n":"第十二条","txt":"从事网络出版服务的申报材料，应该包括下列内容： （一）《网络出版服务许可证申请表》； （二）单位章程及资本来源性质证明； （三）网络出版服务可行性分析报告，包括资金使用、产品规划、技术条件、设备配备、机构设置、人员配备、市场分析、风险评估、版权保护措施等； （四）法定代表人和主要负责人的简历、住址、身份证明文件; （五）编辑出版等相关专业技术人员的国家认可的职业资格证明和主要从业经历及培训证明； （六）工作场所使用证明； （七）网站域名注册证明、相关服务器存放在中华人民共和国境内的承诺。 本规定第八条所列单位从事网络出版服务的，仅提交前款（一）、（六）、（七）项规定的材料。"},{"i":13,"n":"第十三条","txt":"设立网络出版服务单位的申请者应自收到批准决定之日起30日内办理注册登记手续： （一）持批准文件到所在地省、自治区、直辖市出版行政主管部门领取并填写《网络出版服务许可登记表》； （二）省、自治区、直辖市出版行政主管部门对《网络出版服务许可登记表》审核无误后，在10日内向申请者发放《网络出版服务许可证》； （三）《网络出版服务许可登记表》一式三份，由申请者和省、自治区、直辖市出版行政主管部门各存一份，另一份由省、自治区、直辖市出版行政主管部门在15日内报送国家新闻出版广电总局备案。"},{"i":14,"n":"第十四条","txt":"《网络出版服务许可证》有效期为5年。有效期届满，需继续从事网络出版服务活动的，应于有效期届满60日前按本规定第十一条的程序提出申请。出版行政主管部门应当在该许可有效期届满前作出是否准予延续的决定。批准的，换发《网络出版服务许可证》。"},{"i":15,"n":"第十五条","txt":"网络出版服务经批准后，申请者应持批准文件、《网络出版服务许可证》到所在地省、自治区、直辖市电信主管部门办理相关手续。"},{"i":16,"n":"第十六条","txt":"网络出版服务单位变更《网络出版服务许可证》许可登记事项、资本结构，合并或者分立，设立分支机构的，应依据本规定第十一条办理审批手续，并应持批准文件到所在地省、自治区、直辖市电信主管部门办理相关手续。"},{"i":17,"n":"第十七条","txt":"网络出版服务单位中止网络出版服务的，应当向所在地省、自治区、直辖市出版行政主管部门备案，并说明理由和期限；网络出版服务单位中止网络出版服务不得超过180日。 网络出版服务单位终止网络出版服务的，应当自终止网络出版服务之日起30日内，向所在地省、自治区、直辖市出版行政主管部门办理注销手续后到省、自治区、直辖市电信主管部门办理相关手续。省、自治区、直辖市出版行政主管部门将相关信息报国家新闻出版广电总局备案。"},{"i":18,"n":"第十八条","txt":"网络出版服务单位自登记之日起满180日未开展网络出版服务的，由原登记的出版行政主管部门注销登记，并报国家新闻出版广电总局备案。同时，通报相关省、自治区、直辖市电信主管部门。 因不可抗力或者其他正当理由发生上述所列情形的，网络出版服务单位可以向原登记的出版行政主管部门申请延期。"},{"i":19,"n":"第十九条","txt":"网络出版服务单位应当在其网站首页上标明出版行政主管部门核发的《网络出版服务许可证》编号。 互联网相关服务提供者在为网络出版服务单位提供人工干预搜索排名、广告、推广等服务时，应当查验服务对象的《网络出版服务许可证》及业务范围。"},{"i":20,"n":"第二十条","txt":"网络出版服务单位应当按照批准的业务范围从事网络出版服务，不得超出批准的业务范围从事网络出版服务。"},{"i":21,"n":"第二十一条","txt":"网络出版服务单位不得转借、出租、出卖《网络出版服务许可证》或以任何形式转让网络出版服务许可。 网络出版服务单位允许其他网络信息服务提供者以其名义提供网络出版服务，属于前款所称禁止行为。"},{"i":22,"n":"第二十二条","txt":"网络出版服务单位实行特殊管理股制度，具体办法由国家新闻出版广电总局另行制定。"},{"i":23,"n":"第二十三条","txt":"网络出版服务单位实行编辑责任制度，保障网络出版物内容合法。 网络出版服务单位实行出版物内容审核责任制度、责任编辑制度、责任校对制度等管理制度，保障网络出版物出版质量。 在网络上出版其他出版单位已在境内合法出版的作品且不改变原出版物内容的，须在网络出版物的相应页面显著标明原出版单位名称以及书号、刊号、网络出版物号或者网址信息。"},{"i":24,"n":"第二十四条","txt":"网络出版物不得含有以下内容： （一）反对宪法确定的基本原则的； （二）危害国家统一、主权和领土完整的； （三）泄露国家秘密、危害国家安全或者损害国家荣誉和利益的； （四）煽动民族仇恨、民族歧视，破坏民族团结，或者侵害民族风俗、习惯的； （五）宣扬邪教、迷信的； （六）散布谣言，扰乱社会秩序，破坏社会稳定的； （七）宣扬淫秽、色情、赌博、暴力或者教唆犯罪的； （八）侮辱或者诽谤他人，侵害他人合法权益的； （九）危害社会公德或者民族优秀文化传统的； （十）有法律、行政法规和国家规定禁止的其他内容的。"},{"i":25,"n":"第二十五条","txt":"为保护未成年人合法权益，网络出版物不得含有诱发未成年人模仿违反社会公德和违法犯罪行为的内容，不得含有恐怖、残酷等妨害未成年人身心健康的内容，不得含有披露未成年人个人隐私的内容。"},{"i":26,"n":"第二十六条","txt":"网络出版服务单位出版涉及国家安全、社会安定等方面重大选题的内容，应当按照国家新闻出版广电总局有关重大选题备案管理的规定办理备案手续。未经备案的重大选题内容，不得出版。"},{"i":27,"n":"第二十七条","txt":"网络游戏上网出版前，必须向所在地省、自治区、直辖市出版行政主管部门提出申请，经审核同意后，报国家新闻出版广电总局审批。"},{"i":28,"n":"第二十八条","txt":"网络出版物的内容不真实或不公正，致使公民、法人或者其他组织合法权益受到侵害的，相关网络出版服务单位应当停止侵权，公开更正，消除影响，并依法承担其他民事责任。"},{"i":29,"n":"第二十九条","txt":"国家对网络出版物实行标识管理，具体办法由国家新闻出版广电总局另行制定。"},{"i":30,"n":"第三十条","txt":"网络出版物必须符合国家的有关规定和标准要求，保证出版物质量。 网络出版物使用语言文字，必须符合国家法律规定和有关标准规范。"},{"i":31,"n":"第三十一条","txt":"网络出版服务单位应当按照国家有关规定或技术标准，配备应用必要的设备和系统，建立健全各项管理制度，保障信息安全、内容合法，并为出版行政主管部门依法履行监督管理职责提供技术支持。"},{"i":32,"n":"第三十二条","txt":"网络出版服务单位在网络上提供境外出版物，应当取得著作权合法授权。其中，出版境外著作权人授权的网络游戏，须按本规定第二十七条办理审批手续。"},{"i":33,"n":"第三十三条","txt":"网络出版服务单位发现其出版的网络出版物含有本规定第二十四条、第二十五条所列内容的，应当立即删除，保存有关记录，并向所在地县级以上出版行政主管部门报告。"},{"i":34,"n":"第三十四条","txt":"网络出版服务单位应记录所出版作品的内容及其时间、网址或者域名，记录应当保存60日，并在国家有关部门依法查询时，予以提供。"},{"i":35,"n":"第三十五条","txt":"网络出版服务单位须遵守国家统计规定，依法向出版行政主管部门报送统计资料。"},{"i":36,"n":"第三十六条","txt":"网络出版服务的监督管理实行属地管理原则。 各地出版行政主管部门应当加强对本行政区域内的网络出版服务单位及其出版活动的日常监督管理，履行下列职责： （一）对网络出版服务单位进行行业监管，对网络出版服务单位违反本规定的情况进行查处并报告上级出版行政主管部门； （二）对网络出版服务进行监管，对违反本规定的行为进行查处并报告上级出版行政主管部门； （三）对网络出版物内容和质量进行监管，定期组织内容审读和质量检查，并将结果向上级出版行政主管部门报告； （四）对网络出版从业人员进行管理，定期组织岗位、业务培训和考核； （五）配合上级出版行政主管部门、协调相关部门、指导下级出版行政主管部门开展工作。"},{"i":37,"n":"第三十七条","txt":"出版行政主管部门应当加强监管队伍和机构建设，采取必要的技术手段对网络出版服务进行管理。出版行政主管部门依法履行监督检查等执法职责时，网络出版服务单位应当予以配合，不得拒绝、阻挠。 各省、自治区、直辖市出版行政主管部门应当定期将本行政区域内的网络出版服务监督管理情况向国家新闻出版广电总局提交书面报告。"},{"i":38,"n":"第三十八条","txt":"网络出版服务单位实行年度核验制度，年度核验每年进行一次。省、自治区、直辖市出版行政主管部门负责对本行政区域内的网络出版服务单位实施年度核验并将有关情况报国家新闻出版广电总局备案。年度核验内容包括网络出版服务单位的设立条件、登记项目、出版经营情况、出版质量、遵守法律规范、内部管理情况等。"},{"i":39,"n":"第三十九条","txt":"年度核验按照以下程序进行： （一）网络出版服务单位提交年度自检报告，内容包括：本年度政策法律执行情况，奖惩情况，网站出版、管理、运营绩效情况，网络出版物目录，对年度核验期内的违法违规行为的整改情况，编辑出版人员培训管理情况等；并填写由国家新闻出版广电总局统一印制的《网络出版服务年度核验登记表》，与年度自检报告一并报所在地省、自治区、直辖市出版行政主管部门； （二）省、自治区、直辖市出版行政主管部门对本行政区域内的网络出版服务单位的设立条件、登记项目、开展业务及执行法规等情况进行全面审核，并在收到网络出版服务单位的年度自检报告和《网络出版服务年度核验登记表》等年度核验材料的45日内完成全面审核查验工作。对符合年度核验要求的网络出版服务单位予以登记，并在其《网络出版服务许可证》上加盖年度核验章； （三）省、自治区、直辖市出版行政主管部门应于完成全面审核查验工作的15日内将年度核验情况及有关"},{"i":40,"n":"第四十条","txt":"有下列情形之一的，暂缓年度核验： （一）正在停业整顿的； （二）违反出版法规规章，应予处罚的； （三）未按要求执行出版行政主管部门相关管理规定的； （四）内部管理混乱，无正当理由未开展实质性网络出版服务活动的； （五）存在侵犯著作权等其他违法嫌疑需要进一步核查的。 暂缓年度核验的期限由省、自治区、直辖市出版行政主管部门确定，报国家新闻出版广电总局备案，最长不得超过180日。暂缓年度核验期间，须停止网络出版服务。 暂缓核验期满，按本规定重新办理年度核验手续。"},{"i":41,"n":"第四十一条","txt":"已经不具备本规定第八条、第九条规定条件的，责令限期改正；逾期仍未改正的，不予通过年度核验，由国家新闻出版广电总局撤销《网络出版服务许可证》，所在地省、自治区、直辖市出版行政主管部门注销登记，并通知当地电信主管部门依法处理。"},{"i":42,"n":"第四十二条","txt":"省、自治区、直辖市出版行政主管部门可根据实际情况，对本行政区域内的年度核验事项进行调整，相关情况报国家新闻出版广电总局备案。"},{"i":43,"n":"第四十三条","txt":"省、自治区、直辖市出版行政主管部门可以向社会公布年度核验结果。"},{"i":44,"n":"第四十四条","txt":"从事网络出版服务的编辑出版等相关专业技术人员及其负责人应当符合国家关于编辑出版等相关专业技术人员职业资格管理的有关规定。 网络出版服务单位的法定代表人或主要负责人应按照有关规定参加出版行政主管部门组织的岗位培训，并取得国家新闻出版广电总局统一印制的《岗位培训合格证书》。未按规定参加岗位培训或培训后未取得《岗位培训合格证书》的，不得继续担任法定代表人或主要负责人。"},{"i":45,"n":"第四十五条","txt":"国家制定有关政策，保障、促进网络出版服务业的发展与繁荣。鼓励宣传科学真理、传播先进文化、倡导科学精神、塑造美好心灵、弘扬社会正气等有助于形成先进网络文化的网络出版服务，推动健康文化、优秀文化产品的数字化、网络化传播。 网络出版服务单位依法从事网络出版服务，任何组织和个人不得干扰、阻止和破坏。"},{"i":46,"n":"第四十六条","txt":"国家支持、鼓励下列优秀的、重点的网络出版物的出版： （一）对阐述、传播宪法确定的基本原则有重大作用的； （二）对弘扬社会主义核心价值观，进行爱国主义、集体主义、社会主义和民族团结教育以及弘扬社会公德、职业道德、家庭美德、个人品德有重要意义的； （三）对弘扬民族优秀文化，促进国际文化交流有重大作用的； （四）具有自主知识产权和优秀文化内涵的； （五）对推进文化创新，及时反映国内外新的科学文化成果有重大贡献的； （六）对促进公共文化服务有重大作用的； （七）专门以未成年人为对象、内容健康的或者其他有利于未成年人健康成长的； （八）其他具有重要思想价值、科学价值或者文化艺术价值的。"},{"i":47,"n":"第四十七条","txt":"对为发展、繁荣网络出版服务业作出重要贡献的单位和个人，按照国家有关规定给予奖励。"},{"i":48,"n":"第四十八条","txt":"国家保护网络出版物著作权人的合法权益。网络出版服务单位应当遵守《中华人民共和国著作权法》、《信息网络传播权保护条例》、《计算机软件保护条例》等著作权法律法规。"},{"i":49,"n":"第四十九条","txt":"对非法干扰、阻止和破坏网络出版物出版的行为，出版行政主管部门及其他有关部门，应当及时采取措施，予以制止。"},{"i":50,"n":"第五十条","txt":"网络出版服务单位违反本规定的，出版行政主管部门可以采取下列行政措施： （一）下达警示通知书； （二）通报批评、责令改正； （三）责令公开检讨； （四）责令删除违法内容。 警示通知书由国家新闻出版广电总局制定统一格式，由出版行政主管部门下达给相关网络出版服务单位。 本条所列的行政措施可以并用。"},{"i":51,"n":"第五十一条","txt":"未经批准，擅自从事网络出版服务，或者擅自上网出版网络游戏（含境外著作权人授权的网络游戏），根据《出版管理条例》第六十一条、《互联网信息服务管理办法》第十九条的规定，由出版行政主管部门、工商行政管理部门依照法定职权予以取缔，并由所在地省级电信主管部门依据有关部门的通知，按照《互联网信息服务管理办法》第十九条的规定给予责令关闭网站等处罚；已经触犯刑法的，依法追究刑事责任；尚不够刑事处罚的，删除全部相关网络出版物，没收违法所得和从事违法出版活动的主要设备、专用工具，违法经营额1万元以上的，并处违法经营额5倍以上10倍以下的罚款；违法经营额不足1万元的，可以处5万元以下的罚款；侵犯他人合法权益的，依法承担民事责任。"},{"i":52,"n":"第五十二条","txt":"出版、传播含有本规定第二十四条、第二十五条禁止内容的网络出版物的，根据《出版管理条例》第六十二条、《互联网信息服务管理办法》第二十条的规定，由出版行政主管部门责令删除相关内容并限期改正，没收违法所得，违法经营额1万元以上的，并处违法经营额5倍以上10倍以下罚款；违法经营额不足1万元的，可以处5万元以下罚款；情节严重的，责令限期停业整顿或者由国家新闻出版广电总局吊销《网络出版服务许可证》，由电信主管部门依据出版行政主管部门的通知吊销其电信业务经营许可或者责令关闭网站；构成犯罪的，依法追究刑事责任。 为从事本条第一款行为的网络出版服务单位提供人工干预搜索排名、广告、推广等相关服务的，由出版行政主管部门责令其停止提供相关服务。"},{"i":53,"n":"第五十三条","txt":"违反本规定第二十一条的，根据《出版管理条例》第六十六条的规定，由出版行政主管部门责令停止违法行为，给予警告，没收违法所得，违法经营额1万元以上的，并处违法经营额5倍以上10倍以下的罚款；违法经营额不足1万元的，可以处5万元以下的罚款；情节严重的，责令限期停业整顿或者由国家新闻出版广电总局吊销《网络出版服务许可证》。"},{"i":54,"n":"第五十四条","txt":"有下列行为之一的，根据《出版管理条例》第六十七条的规定，由出版行政主管部门责令改正，给予警告；情节严重的，责令限期停业整顿或者由国家新闻出版广电总局吊销《网络出版服务许可证》： （一）网络出版服务单位变更《网络出版服务许可证》登记事项、资本结构，超出批准的服务范围从事网络出版服务，合并或者分立，设立分支机构，未依据本规定办理审批手续的； （二）网络出版服务单位未按规定出版涉及重大选题出版物的； （三）网络出版服务单位擅自中止网络出版服务超过180日的； （四）网络出版物质量不符合有关规定和标准的。"},{"i":55,"n":"第五十五条","txt":"违反本规定第三十四条的，根据《互联网信息服务管理办法》第二十一条的规定，由省级电信主管部门责令改正；情节严重的，责令停业整顿或者暂时关闭网站。"},{"i":56,"n":"第五十六条","txt":"网络出版服务单位未依法向出版行政主管部门报送统计资料的，依据《新闻出版统计管理办法》处罚。"},{"i":57,"n":"第五十七条","txt":"网络出版服务单位违反本规定第二章规定，以欺骗或者贿赂等不正当手段取得许可的，由国家新闻出版广电总局撤销其相应许可。"},{"i":58,"n":"第五十八条","txt":"有下列行为之一的，由出版行政主管部门责令改正，予以警告，并处3万元以下罚款： （一）违反本规定第十条，擅自与境内外中外合资经营、中外合作经营和外资经营的企业进行涉及网络出版服务业务的合作的； （二）违反本规定第十九条，未标明有关许可信息或者未核验有关网站的《网络出版服务许可证》的； （三）违反本规定第二十三条，未按规定实行编辑责任制度等管理制度的； （四）违反本规定第三十一条，未按规定或标准配备应用有关系统、设备或未健全有关管理制度的； （五）未按本规定要求参加年度核验的； （六）违反本规定第四十四条，网络出版服务单位的法定代表人或主要负责人未取得《岗位培训合格证书》的； （七）违反出版行政主管部门关于网络出版其他管理规定的。"},{"i":59,"n":"第五十九条","txt":"网络出版服务单位违反本规定被处以吊销许可证行政处罚的，其法定代表人或者主要负责人自许可证被吊销之日起10年内不得担任网络出版服务单位的法定代表人或者主要负责人。 从事网络出版服务的编辑出版等相关专业技术人员及其负责人违反本规定，情节严重的，由原发证机关吊销其资格证书。"},{"i":60,"n":"第六十条","txt":"本规定所称出版物内容审核责任制度、责任编辑制度、责任校对制度等管理制度，参照《图书质量保障体系》的有关规定执行。"},{"i":61,"n":"第六十一条","txt":"本规定自2016年3月10日起施行。原国家新闻出版总署、信息产业部2002年6月27日颁布的《互联网出版管理暂行规定》同时废止。"}],"dinghudinggoujinkouchubanwuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了满足国内单位和个人、在华外国机构、外商投资企业外籍人士和港、澳、台人士对进口出版物的阅读需求，加强对进口出版物的管理，根据《出版管理条例》和有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中国境内订户订购进口出版物适用本办法。 本办法所称进口出版物，是指由出版物进口经营单位进口的，在外国以及在中国香港特别行政区、澳门特别行政区和台湾地区出版的图书、报纸（含过期报纸）、期刊（含过期期刊）、电子出版物等。 本办法所称出版物进口经营单位，是指依照《出版管理条例》设立的从事出版物进口业务的单位。 本办法所称订户，是指通过出版物进口经营单位订购进口出版物的国内单位和个人、在华外国机构、外商投资企业和在华长期工作、学习、生活的外籍人士以及港、澳、台人士。 本办法所称订购，是指订户为满足本单位或者本人的阅读需求，向出版物进口经营单位预订购买进口出版物。"},{"i":3,"n":"第三条","txt":"进口出版物分为限定发行范围的和非限定发行范围的两类，国家对其发行实行分类管理。 进口限定发行范围的报纸、期刊、图书、电子出版物等实行订户订购、分类供应的发行方式；非限定发行范围的进口报纸、期刊实行自愿订户订购和市场销售相结合的发行方式；非限定发行范围的进口图书、电子出版物等实行市场销售的发行方式。 限定发行范围的进口报纸、期刊、图书、电子出版物的种类由新闻出版总署确定。"},{"i":4,"n":"第四条","txt":"订户订购进口出版物由出版物进口经营单位经营。其中，订户订购限定发行范围的进口报纸、期刊、图书、电子出版物的业务，须由新闻出版总署指定的出版物进口经营单位经营。 未经新闻出版总署批准，任何单位和个人不得从事订户订购进口出版物的经营活动。 出版物进口经营单位委托非出版物进口经营单位代理征订或者代理配送进口出版物，须事先报新闻出版总署同意。"},{"i":5,"n":"第五条","txt":"国内单位订户订购非限定发行范围的进口报纸、期刊，持单位订购申请书，直接到新闻出版总署批准的报纸、期刊进口经营单位办理订购手续。国内个人订户应通过所在单位办理订购手续。"},{"i":6,"n":"第六条","txt":"可以订购限定发行范围的进口报纸、期刊、图书和电子出版物的国内单位订户由新闻出版总署确定。"},{"i":7,"n":"第七条","txt":"国内单位订户订购限定发行范围的进口报纸、期刊、图书、电子出版物等，中央单位订户由所属中央各部委审批；地方单位订户经所在地省、自治区、直辖市新闻出版行政部门审核后报送同级党委宣传部审批。获得批准的订户持单位订购申请书和有关批准文件,到新闻出版总署指定的出版物进口经营单位办理订购手续。 国内单位订户订购限定发行范围的进口报纸、期刊、图书、电子出版物等，应制定相应的使用管理办法。"},{"i":8,"n":"第八条","txt":"在华外国机构、外商投资企业和在华长期工作、学习、生活的外籍人士和港、澳、台人士订购进口报纸、期刊，应持单位订购申请书或者本人身份证明，到新闻出版总署批准或者指定的报纸、期刊进口经营单位办理订购手续。"},{"i":9,"n":"第九条","txt":"出版物进口经营单位负责对订购限定发行范围的进口报纸、期刊、图书、电子出版物的订户进行审核，并将审核后的订户名单、拟订购进口报纸、期刊、图书、电子出版物的品种和数量报送新闻出版总署批准。出版物进口经营单位依照批准后的订户名单及进口报纸、期刊、图书、电子出版物的品种和数量供应订户。"},{"i":10,"n":"第十条","txt":"未经批准，擅自从事进口出版物的订户订购业务，按照《出版管理条例》第六十一条处罚。 违反本办法其他规定的，由新闻出版行政部门责令改正，给予警告；情节严重的，并处3万元以下的罚款。"},{"i":11,"n":"第十一条","txt":"本办法自公布之日起施行。新闻出版总署2004年12月31日颁布的《订户订购进口出版物管理办法》同时废止。"}],"sheliwaishangtouziyinshuaqiyezanxingguiding":[{"i":1,"n":"第一条","txt":"为进一步适应改革开放的需要，加强对外商投资印刷企业的管理，促进我国印刷业的健康发展，根据《中华人民共和国中外合资经营企业法》、《中华人民共和国中外合作经营企业法》、《中华人民共和国外资企业法》、《印刷业管理条例》等有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于在中国境内设立外商投资印刷企业。 本规定所称外商投资印刷企业，是指外国机构、公司、企业（以下简称外方投资者）按照平等互利的原则和中国公司、企业共同投资设立的中外合营（包括合资、合作）印刷企业和外方投资者投资设立的外资印刷企业。"},{"i":3,"n":"第三条","txt":"国家允许设立从事出版物、包装装潢印刷品、其他印刷品印刷经营活动的中外合营印刷企业，允许设立从事包装装潢印刷品印刷，经营活动的外资印刷企业。"},{"i":4,"n":"第四条","txt":"外商投资印刷企业从事印刷经营活动，应当遵守中国法律、法规，接受印刷业管理部门的监督管理，不得损害社会公共利益。 外商投资印刷企业的正当经营活动及投资各方的合法权益受中国法律的保护。"},{"i":5,"n":"第五条","txt":"中方投资者以国有资产参与投资（包括作价出资或作为合作条件），须经其相应主管部门批准，并按照国有资产评估管理的有关规定对拟投入的国有资产进行评估。"},{"i":6,"n":"第六条","txt":"设立外商投资印刷企业，应当具备下列条件： （一）申请设立外商投资印刷企业的中、外方投资者应当是能够独立承担民事责任的法人，并具有直接或间接从事印刷经营管理的经验。 （二）外方投资者应当符合下列要求之一： 1.能够提供国际先进的印刷经营管理模式及经验； 2.能够提供国际领先水平的印刷技术和设备； 3.能够提供较为雄厚的资金。 （三）申请设立外商投资印刷企业的形式为有限责任公司。 （四）从事出版物、其他印刷品印刷经营活动的中外合营印刷企业，合营中方投资者应当控股或占主导地位。其中，从事出版物印刷经营活动的中外合营印刷企业的董事长应当由中方担任，董事会成员中方应当多于外方。 （五）经营期限一般不超过30年。 审批设立外商投资印刷企业，除依照前款规定外，还应当符合国家有关印刷企业总量、结构和布局的规划。"},{"i":7,"n":"第七条","txt":"设立外商投资印刷企业，应先向所在地省级新闻出版行政部门提出申请，并提交下列申请文件： （一）设立外商投资印刷企业申请书。 （二）各方投资者法定代表人签署的项目建议书及项目可行性研究报告。项目建议书应当载明下列事项： 1.各方投资者的名称、住所； 2.申请设立外商投资印刷企业的名称、法定代表人、住所、经营范围、注册资本及投资总额； 3.各方投资者的出资方式和出资额。 （三）各方投资者的注册登记证明（复印件）、法定代表人身份证明（复印件）。 （四）国有资产管理部门对拟投入国有资产的评估报告确认文件。 省级新闻出版行政部门自收到规定的全部文件之日起10个工作日内提出初审意见，报送新闻出版总署审批。"},{"i":8,"n":"第八条","txt":"报送新闻出版总署审批，省级新闻出版行政部门需提交下列文件： （一）申请人申请设立文件。 （二）省级新闻出版行政部门的初审意见。 （三）法律、法规和新闻出版总署规定的其他文件。 新闻出版总署应自收到规定的全部文件之日起30个工作日内作出批准或者不批准的书面决定。"},{"i":9,"n":"第九条","txt":"申请人获得新闻出版总署批准文件后，按照有关法律、法规向所在地省、自治区、直辖市、计划单列市外经贸行政部门提出申请，并提交下列文件： （一）申请人申请设立文件及新闻出版总署的批准文件。 （二）由各方投资者法定代表人或其授权的代表签署的外商投资印刷企业的合同、章程。 （三）拟设立外商投资印刷企业的董事会成员名单及各方投资者董事委派书。 （四）工商行政管理部门出具的企业名称预先核准通知书。 （五）法律、法规和外经贸行政部门规定的其他材料。 省、自治区、直辖市、计划单列市外经贸行政部门对投资总额在3000万美元以下，拟从事包装装潢印刷品印刷经营活动的外商投资印刷企业进行审批。应自收到规定的全部文件之日起30个工作日内作出批准或者不批准的书面决定。批准设立申请的，发给《外商投资企业批准证书》，并报对外贸易经济合作部（以下简称外经贸部）备案。 对拟从事出版物、其他印刷品印刷经营活动的中外合营印刷企"},{"i":10,"n":"第十条","txt":"报送外经贸部审批，省、自治区、直辖市、计划单列市外经贸行政部门需提交下列文件： （一）申请人申请设立文件。 （二）省、自治区、直辖市、计划单列市外经贸行政部门的初审意见。 （三）法律、法规和外经贸部规定的其他文件。 外经贸部应自收到规定的全部文件之日起30个工作日内作出批准或者不批准的书面决定。批准设立申请的，发给《外商投资企业批准证书》。"},{"i":11,"n":"第十一条","txt":"获得批准设立的申请人，持新闻出版总署的批准文件及《外商投资企业批准证书》到省级新闻出版行政部门申领《印刷经营许可证》，并按照《印刷业管理条例》的有关规定申领《特种行业许可证》和营业执照。"},{"i":12,"n":"第十二条","txt":"外商投资印刷企业不得设置分支机构。"},{"i":13,"n":"第十三条","txt":"已设立的中外合营印刷企业申请兼营或者变更从事出版物、包装装潢印刷品或者其他印刷品印刷经营活动的，或者已设立的外商投资印刷企业兼并其他印刷业经营者，或者因合并、分立而设立新的印刷业经营者，应经新闻出版总署批准后，再报外经贸部门批准，并依法办理相应的注册登记变更手续。 其他事项变更，按现行有关规定报原审批部门批准，并办理相应的注册登记变更手续。对于企业变更名称、法定代表人或者负责人、住所或者经营场所、股权比例等主要登记事项，或者终止印刷经营活动等，并报新闻出版总署备案。"},{"i":14,"n":"第十四条","txt":"外商投资印刷企业经营期限届满，因特殊情况确需延长经营期限的，应当在经营期限届满的180天前提出申请，并报送原审批机关审批。"},{"i":15,"n":"第十五条","txt":"经批准设立的外商投资印刷企业，应当在审批机关规定的期限内办理完有关登记注册手续；逾期未能完成的，经审批机关核准后，可以撤销该外商投资项目。"},{"i":16,"n":"第十六条","txt":"县级以上新闻出版行政部门对未经批准，擅自设立并从事印刷经营活动的外商投资印刷企业，依照《印刷业管理条例》进行处罚。 各级新闻出版及外经贸行政部门违反本规定，擅自批准设立或者变更不符合条件的外商投资印刷企业的，依照《印刷业管理条例》追究有关负责人及责任人的责任。"},{"i":17,"n":"第十七条","txt":"香港特别行政区、澳门特别行政区、台湾地区的投资者在大陆投资兴办印刷企业的，参照本规定执行。"},{"i":18,"n":"第十八条","txt":"1997年5月1日施行的《印刷业管理条例》实施前，经有关部门批准设立的外商投资印刷企业，经新闻出版总署审核同意后到省级新闻出版行政部门换领《印刷经营许可证》，其中，从事出版物印刷经营活动的外商投资企业申请扩大投资规模及延长经营期限的，须符合本规定第六条的要求；1997年5月1日后依据《印刷业管理条例》的规定批准设立的外商投资印刷企业，应当自本规定施行之日起180天内，到省级新闻出版行政部门换领《印刷经营许可证》。"},{"i":19,"n":"第十九条","txt":"本规定由新闻出版总署和外经贸部负责解释。"},{"i":20,"n":"第二十条","txt":"本规定自发布之日起施行。 关于《设立外商投资印刷企业暂行规定》的补充规定 （2008年11月12日新闻出版总署、商务部令第38号公布） 为促进香港、澳门与内地建立更紧密经贸关系、鼓励香港、澳门服务提供者在内地设立商业企业，根据国务院批准的《〈内地与香港关于建立更紧密经贸关系的安排〉补充协议五》及《〈内地与澳门关于建立更紧密经贸关系的安排〉补充协议五》，现就《设立外商投资印刷企业暂行规定》（新闻出版总署、对外贸易经济合作部令2002年第16号）中有关香港和澳门服务提供者投资印刷领域问题做出如下补充规定： 一、对香港、澳门服务提供者在内地设立从事包装装潢印刷品的印刷企业的最低注册资本要求，比照内地企业实行。 二、本规定中的香港、澳门服务提供者应分别符合《内地与香港关于建立更紧密经贸关系的安排》及《内地与澳门建立更紧密经贸关系的安排》中关于“服务提供者”定义及相关规定的要求。 三、香港、澳门"}],"yinxiangzhipinchubanguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强音像制品出版的管理，促进我国音像出版事业的健康发展与繁荣，根据《出版管理条例》、《音像制品管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事音像制品出版活动，适用本规定。 本规定所称音像制品是指录有内容的录音带（AT）、录像带（VT）、激光唱盘（CD）、数码激光视盘（VCD）及高密度光盘（DVD）等。"},{"i":3,"n":"第三条","txt":"任何组织和个人不得出版含有《音像制品管理条例》第三条第二款禁止内容的音像制品。"},{"i":4,"n":"第四条","txt":"新闻出版总署负责全国音像制品出版的监督管理工作。县级以上地方人民政府负责出版管理的行政部门（以下简称出版行政部门）负责本行政区域内音像制品出版的监督管理工作。 音像出版单位的主管机关、主办单位应当按照出版法律、法规和规章，对音像出版单位的出版活动履行管理职责。"},{"i":5,"n":"第五条","txt":"国家对出版音像制品，实行许可制度；未经许可，任何单位和个人不得从事音像制品的出版活动。 音像制品出版的许可证件和批准文件，不得出租、出借、出售或者以其他任何形式转让。"},{"i":6,"n":"第六条","txt":"音像出版行业的社会团体按照其章程，在出版行政部门的指导下，实行自律管理。"},{"i":7,"n":"第七条","txt":"设立音像出版单位，应当具备下列条件： （一）有音像出版单位的名称、章程； （二）有符合新闻出版总署认定的主办单位及其主管机关； （三）有确定的业务范围； （四）有适应业务范围需要的组织机构和取得国家出版专业技术人员资格的编辑人员，其人数不得少于10人，其中从事音像出版业务2年以上并具有中级以上出版专业技术人员职业资格的不得少于5人； （五）有30万元以上的注册资本； （六）有适应业务范围需要的设备和工作场所； （七）法律、行政法规规定的其他条件。 审批设立音像出版单位，除依照前款所列条件外，还应当符合国家关于音像出版单位总量、布局和结构的规划。"},{"i":8,"n":"第八条","txt":"申请设立音像出版单位，由主办单位向所在地省、自治区、直辖市人民政府出版行政部门提出申请；省、自治区、直辖市人民政府出版行政部门自受理申请之日起20日内提出审核意见，连同申请材料报新闻出版总署审批。"},{"i":9,"n":"第九条","txt":"设立音像出版单位的申请书应当载明下列事项： （一）音像出版单位的名称、地址； （二）音像出版单位的主办单位及其主管机关的名称、地址； （三）音像出版单位的法定代表人或者主要负责人及音像出版专业人员的姓名、住址、资格证明文件； （四）音像出版单位的注册资本数额、来源及性质证明； （五）音像出版单位工作场所使用证明文件。 申请书应当附具出版单位的章程和设立出版单位的主办单位及主管机关的有关证明材料。"},{"i":10,"n":"第十条","txt":"新闻出版总署应当自收到申请书之日起60日内作出批准或者不批准的决定，并由省、自治区、直辖市人民政府出版行政部门书面通知主办单位；不批准的，应当说明理由。"},{"i":11,"n":"第十一条","txt":"设立音像出版单位的主办单位应当自收到批准决定之日起60日内，向所在地省、自治区、直辖市人民政府出版行政部门登记，领取《音像制品出版许可证》（以下简称出版许可证）。音像出版单位经登记后，持出版许可证到工商行政管理部门登记，依法领取营业执照。 音像出版单位自登记之日起满180日未从事出版活动的，由原登记的出版行政部门注销登记，并报新闻出版总署备案。因不可抗力或者其他正当理由发生前款所列情形的，向出版行政部门申请延期。"},{"i":12,"n":"第十二条","txt":"音像出版单位变更名称、主办单位或者主管机关、业务范围，或者兼并其他音像出版单位，或者因合并、分立而设立新的音像出版单位的，应当依照本规定第七条至第十条的规定办理审批手续，并到原登记的工商行政管理部门办理相应的登记手续。"},{"i":13,"n":"第十三条","txt":"音像出版单位变更地址、法定代表人或者主要负责人，或者终止音像出版经营活动的，应当到原登记的工商行政管理部门办理变更登记或者注销登记，并在30日内向新闻出版总署备案。"},{"i":14,"n":"第十四条","txt":"音像出版单位的法定代表人或者主要负责人应当具有中级以上出版专业技术人员职业资格，具有从事音像出版业务3年以上的经历，并应通过新闻出版总署或省、自治区、直辖市人民政府出版行政部门组织的岗位培训，获得《岗位培训合格证书》。"},{"i":15,"n":"第十五条","txt":"音像出版单位中从事编辑、出版、校对等专业技术工作的人员，必须通过国家出版专业技术人员职业资格考试，取得规定级别的出版专业职业资格，持相应的《中华人民共和国出版专业技术人员职业资格证书》上岗。"},{"i":16,"n":"第十六条","txt":"音像出版单位不得超出出版许可证确定的业务范围从事音像制品的出版活动。"},{"i":17,"n":"第十七条","txt":"音像出版单位应当按照国家标准及其他有关规定标识、使用《中国标准音像制品编码》（以下简称版号）。 版号由新闻出版总署负责管理和调控，由省、自治区、直辖市人民政府出版行政部门发放。"},{"i":18,"n":"第十八条","txt":"音像出版单位实行编辑责任制度，保障音像制品刊载的内容合法。"},{"i":19,"n":"第十九条","txt":"音像出版单位实行年度出版计划备案制度，出版计划的内容应包括选题名称、制作单位、主创人员、类别、载体、内容提要、节目长度、计划出版时间。出版计划报送的程序为： （一）本年度上一年的12月20日以前报送本年度出版计划；本年度3月1日—20日、9月1日—20日报送本年度出版调整计划。 （二）出版计划及出版调整计划，须经所在地省、自治区、直辖市人民政府出版行政部门审核。 （三）省、自治区、直辖市人民政府出版行政部门应当自受理出版计划报送申请之日起20日内，向音像出版单位回复审核意见，并报新闻出版总署备案。"},{"i":20,"n":"第二十条","txt":"音像出版单位出版涉及国家安全、社会安定等方面的重大选题，应当依照重大选题备案的有关规定报新闻出版总署备案。未经备案的重大选题，不得出版。"},{"i":21,"n":"第二十一条","txt":"图书出版社、报社、期刊社、电子出版物出版社，出版配合本版出版物的音像制品，须向所在地省、自治区、直辖市人民政府出版行政部门提交申请书和样本。"},{"i":22,"n":"第二十二条","txt":"出版配合本版出版物的音像制品申请书，须写明本版出版物的名称、制作单位；主创人员、主要内容、出版时间、节目长度；复制数量和载体形式等内容。"},{"i":23,"n":"第二十三条","txt":"出版单位所在地省、自治区、直辖市人民政府出版行政部门，应当自受理申请之日起20日内对其申请书和样本进行审核。审核同意的，配发版号，发放复制委托书，并报新闻出版总署备案；审核不同意的，应当说明理由。"},{"i":24,"n":"第二十四条","txt":"经批准出版的配合本版出版物音像制品，其名称须与本版出版物一致，并须与本版出版物统一配套销售，不得单独定价销售。"},{"i":25,"n":"第二十五条","txt":"音像出版单位及经批准出版配合本版出版物音像制品的其他出版单位，应在其出版的音像制品及其包装的明显位置，标明出版单位的名称、地址和音像制品的版号；出版时间、责任编辑、著作权人和条形码。出版进口的音像制品，还应当标明进口批准文号。"},{"i":26,"n":"第二十六条","txt":"音像出版单位不得向任何单位或者个人出租、出借、出售或者以其他任何形式转让本单位的名称，不得向任何单位或者个人出售或者以其他形式出售或转让本单位版号。"},{"i":27,"n":"第二十七条","txt":"任何单位和个人不得以购买、租用、借用、擅自使用音像出版单位的名称或者以购买、伪造版号等形式从事音像制品出版活动。"},{"i":28,"n":"第二十八条","txt":"音像出版单位不得委托未取得《音像制品制作许可证》的单位制作音像制品。"},{"i":29,"n":"第二十九条","txt":"音像出版单位、经批准出版配合本版出版物音像制品的出版单位，应自音像制品出版之日起30日内，分别向国家图书馆、中国版本图书馆和新闻出版总署免费送交样本。"},{"i":30,"n":"第三十条","txt":"用于无偿赠送、发放及业务交流的音像制品属于音像非卖品，不得定价，不得销售或变相销售，不得收取任何费用。"},{"i":31,"n":"第三十一条","txt":"复制单位接受委托复制音像制品非卖品的，应当验证委托单位或者个人的身份证明和其出具的音像制品非卖品复制委托书，并要求委托方提供非卖品使用目的、名称、制作单位、主要内容、发送对象、复制数量、节目长度和载体形式等信息。"},{"i":32,"n":"第三十二条","txt":"委托复制音像制品非卖品的单位或者个人须在音像制品非卖品包装和盘（带）显著位置标注“音像非卖品”字样。"},{"i":33,"n":"第三十三条","txt":"委托复制音像制品，须使用复制委托书。 音像出版单位及其他委托复制单位，必须遵守国家关于复制委托书的管理规定。 复制委托书由新闻出版总署统一印制。"},{"i":34,"n":"第三十四条","txt":"复制委托书由音像出版单位及其他委托复制单位向所在地省、自治区、直辖市人民政府出版行政部门领取。"},{"i":35,"n":"第三十五条","txt":"出版单位及其他委托复制单位应当按照规定开具或填写复制委托书，并将复制委托书直接交送复制单位。 出版单位及其他委托复制单位须保证复制委托书内容真实、准确、完整。 出版单位及其他委托复制单位不得以任何形式向任何单位或者个人出售或者转让复制委托书。"},{"i":36,"n":"第三十六条","txt":"音像出版单位及其他委托复制单位，须确定专人管理复制委托书并建立使用记录。复制委托书使用记录的内容包括开具时间、音像制品及具体节目名称、相对应的版号、管理人员签名。 复制委托书使用记录保存期为两年。"},{"i":37,"n":"第三十七条","txt":"音像出版单位及其他委托复制单位，自音像制品完成复制之日起30日内，向所在地省、自治区、直辖市人民政府出版行政部门上交由本单位及复制单位签章的复制委托书第二联及音像制品样品。"},{"i":38,"n":"第三十八条","txt":"申请出版配合本版出版物音像制品或音像非卖品的单位，自获得批准之日起90日内未能出版的，须向所在地省、自治区、直辖市人民政府出版行政部门交回复制委托书。"},{"i":39,"n":"第三十九条","txt":"音像出版单位出版的音像制品、其他出版单位出版的配合本版出版物音像制品、音像非卖品须委托依法设立的复制单位复制。"},{"i":40,"n":"第四十条","txt":"音像出版单位实行审核登记制度，审核登记每两年进行一次。"},{"i":41,"n":"第四十一条","txt":"申请审核登记的音像出版单位应提交以下材料： （一）《音像出版单位审核登记表》； （二）音像制品出版业务情况报告，应当包括：执行出版管理的法律、法规和规章的情况，出版经营情况，人员、场所、设施情况； （三）两年内出版的音像制品登记表； （四）出版许可证的复印件。"},{"i":42,"n":"第四十二条","txt":"音像出版单位应于审核登记年度1月15日前向所在地省、自治区、直辖市人民政府出版行政部门申请年度审核登记并提交相应材料。各省、自治区、直辖市人民政府出版行政部门对本行政区域内申请登记的音像出版单位进行审核，并于同年2月底前完成审核登记工作。"},{"i":43,"n":"第四十三条","txt":"对符合下列条件的音像出版单位，省、自治区、直辖市人民政府出版行政部门予以登记： （一）符合本规定第七条的规定； （二）两年内无违反出版管理法律、法规和规章的情形； （三）两年内出版音像制品不少于10种。"},{"i":44,"n":"第四十四条","txt":"对不符合前条所列条件之一的音像出版单位，省、自治区、直辖市人民政府出版行政部门予以暂缓登记。 暂缓登记的期限为3个月。省、自治区、直辖市人民政府出版行政部门应当责令暂缓登记的出版单位在此期限内进行整顿，达到本规定第七条的规定条件。 在暂缓登记的期限届满前，省、自治区、直辖市人民政府出版行政部门应对暂缓登记的出版单位进行审查，对于达到本规定第七条的规定条件的，予以登记。对于未达到本规定第七条的规定条件的，提出注销登记意见报新闻出版总署批准。对注销登记的出版单位，由所在地省、自治区、直辖市人民政府出版行政部门缴回其出版许可证。"},{"i":45,"n":"第四十五条","txt":"各省、自治区、直辖市人民政府出版行政部门应于同年3月20日前将审核登记情况及有关材料复印件汇总后报新闻出版总署备案。"},{"i":46,"n":"第四十六条","txt":"未经批准，擅自设立音像制品出版单位，擅自从事音像制品出版业务的，依照《音像制品管理条例》第三十九条处罚。"},{"i":47,"n":"第四十七条","txt":"出版含有《音像制品管理条例》第三条第二款禁止内容的音像制品，依照《音像制品管理条例》第四十条处罚。"},{"i":48,"n":"第四十八条","txt":"出版音像制品的单位有下列行为之一的，依照《音像制品管理条例》第四十二条处罚： （一）向其他单位、个人出租、出借、出售或者以其他任何形式转让本单位的名称、音像制品出版的许可证件或者批准文件，出售或者以其他任何形式转让本单位的版号或者复制委托书的； （二）委托未取得《音像制品制作许可证》的单位制作音像制品，或者委托非依法设立的复制单位复制音像制品的。"},{"i":49,"n":"第四十九条","txt":"出版音像制品的单位有下列行为之一的，依照《音像制品管理条例》第四十四条处罚： （一）未按规定将年度出版计划和涉及国家安全、社会安定等方面的重大选题报新闻出版总署备案的； （二）变更名称、主办单位或者主管机关、地址、法定代表人或者主要负责人、业务范围等，未依照本规定第十二条、第十三条办理审批、备案手续的； （三）未在其出版的音像制品及其包装的明显位置标明本规定所规定的项目的； （四）未依照规定期限送交音像制品样本的。"},{"i":50,"n":"第五十条","txt":"有下列行为之一的，由出版行政部门责令停止违法行为，给予警告，并处3万元以下的罚款： （一）其他出版单位配合本版出版物出版音像制品，其名称与本版出版物不一致或者单独定价销售的； （二）音像出版单位及其他委托复制单位，未按照本规定第三十六条规定的内容、期限留存备查材料的； （三）委托复制非卖品的单位销售或变相销售非卖品或者以非卖品收取费用的； （四）委托复制非卖品的单位未在非卖品包装和盘带显著位置注明非卖品编号的。"},{"i":51,"n":"第五十一条","txt":"音像制品的出版许可证由新闻出版总署统一印制。"},{"i":52,"n":"第五十二条","txt":"本规定有关行政许可的期限以工作日计算，不含法定节假日。"},{"i":53,"n":"第五十三条","txt":"本办法自2004年8月1日起施行，新闻出版署1996年2月1日发布的《音像制品出版管理办法》同时废止。"}],"yinxiangzhipinzhizuoguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强音像制品制作经营活动的管理，促进音像制品制作行业的发展和繁荣，根据国务院《音像制品管理条例》、《出版管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称音像制品制作是指通过录音、录像等技术手段，将声音、图像、文字等内容整理加工成音像制品节目源的活动。"},{"i":3,"n":"第三条","txt":"任何组织和个人不得制作含有《音像制品管理条例》第三条第二款禁止内容的音像制品。"},{"i":4,"n":"第四条","txt":"国家对从事音像制品制作经营活动实行许可制度；未经许可，任何单位和个人不得从事音像制品制作经营活动。 音像出版单位从事音像制品制作经营活动，无需再申请取得《音像制品制作许可证》。"},{"i":5,"n":"第五条","txt":"新闻出版总署负责对全国音像制品制作管理工作实施监督。 县级以上地方新闻出版行政部门负责本行政区域内音像制品制作的监督管理工作。"},{"i":6,"n":"第六条","txt":"申请从事音像制作业务应当具备下列条件： （一）有音像制作单位的名称、章程； （二）有适应业务范围需要的组织机构和音像制作专业技术人员，从事音像制作业务的专业技术人员不得少于5人； （三）有必要的技术设备； （四）有固定的经营场所； （五）法律、法规规定的其他条件。 审批从事音像制作业务，除依照前款所列条件外，还应符合本地区音像制作单位总量、布局和结构的规划。"},{"i":7,"n":"第七条","txt":"申请从事音像制作业务，由所在地省、自治区、直辖市新闻出版行政部门审批。省、自治区、直辖市新闻出版行政部门应当自受理申请之日起60日内作出批准或者不批准的决定，并通知申请人。批准的，发给《音像制品制作许可证》；不批准的，应当说明理由。"},{"i":8,"n":"第八条","txt":"申请从事音像制作业务，应当提交以下材料： （一）申请书，申请书应当载明单位名称、地址，制作业务范围，资金来源及数额，法定代表人或者主要负责人姓名、住址等内容； （二）单位章程； （三）专业技术人员的资历证明文件； （四）注册资本数额、来源及性质证明； （五）经营场所使用证明。"},{"i":9,"n":"第九条","txt":"音像制作单位变更名称、业务范围，或者兼并其他音像制作单位，或者因合并、分立而设立新的音像制作单位的，应当依照本办法第七条、第八条的规定办理审批手续。"},{"i":10,"n":"第十条","txt":"音像制作单位变更地址、法定代表人或者主要负责人，或者终止音像制作经营活动的，应当在10日内向所在地省、自治区、直辖市新闻出版行政部门备案。"},{"i":11,"n":"第十一条","txt":"自取得《音像制品制作许可证》6个月内未开展音像制品制作业务或者停业满1年的，由所在地省、自治区、直辖市新闻出版行政部门注销《音像制品制作许可证》。"},{"i":12,"n":"第十二条","txt":"音像制作单位的法定代表人或者主要负责人应当接受所在地地市以上新闻出版行政部门组织的岗位培训。"},{"i":13,"n":"第十三条","txt":"音像制作单位必须有健全的内部管理制度，并填写制作文档记录。制作文档记录须归档保存2年以备查验。 制作文档记录由新闻出版总署制定统一格式。"},{"i":14,"n":"第十四条","txt":"音像制作单位接受委托制作音像制品的，应当按照国家有关规定，与委托方订立制作委托合同，并验证委托方《营业执照》或者身份证明材料。 前款所涉及的合同、《营业执照》及身份证明材料复印件，音像制作单位应当归档保存2年以备查验。"},{"i":15,"n":"第十五条","txt":"音像制作单位未经授权，不得以任何形式将接受委托制作的音像制品提供给委托方以外的单位或者个人。"},{"i":16,"n":"第十六条","txt":"音像制作单位制作的音像制品，应当符合国家有关质量、技术标准和规定。"},{"i":17,"n":"第十七条","txt":"依法从事音像制作业务的单位有权在出版的音像制品及其包装上署名。其他单位或者个人不得以制作单位名义在音像制品上署名。"},{"i":18,"n":"第十八条","txt":"音像制作单位每2年履行一次年度核验手续。 省、自治区、直辖市新闻出版行政部门负责年度核验工作并制定具体办法。 省、自治区、直辖市新闻出版行政部门应在年度核验工作完成后30日内将年度核验情况报新闻出版总署。"},{"i":19,"n":"第十九条","txt":"音像制作单位须遵守国家统计规定，依法向新闻出版行政部门报送统计资料。"},{"i":20,"n":"第二十条","txt":"音像出版单位可以与香港特别行政区、澳门特别行政区、台湾地区或者外国的组织、个人合作制作音像制品（以下简称合作制作音像制品），但应由音像出版单位在制作完成后10日内向所在地省、自治区、直辖市新闻出版行政部门备案。"},{"i":21,"n":"第二十一条","txt":"合作制作音像制品应报送以下备案材料： （一）合作制作音像制品的名称、节目长度、载体形式及内容简介等； （二）合作双方的名称、基本情况、投资数额； （三）项目合作合同。"},{"i":22,"n":"第二十二条","txt":"未经批准，擅自从事音像制品制作经营活动的，依照《音像制品管理条例》第三十九条的规定处罚。 音像制作单位以外的单位或者个人以制作单位名义在音像制品上署名的，按照擅自从事音像制品制作经营活动处罚。"},{"i":23,"n":"第二十三条","txt":"制作明知或者应知含有《音像制品管理条例》第三条第二款禁止内容的音像制品的，依照《音像制品管理条例》第四十条的规定处罚。"},{"i":24,"n":"第二十四条","txt":"音像制作单位接受音像出版单位委托制作音像制品未依照本规定验证有关证明的，依照《音像制品管理条例》第四十二条的规定处罚。"},{"i":25,"n":"第二十五条","txt":"音像出版单位与香港特别行政区、澳门特别行政区、台湾地区或者外国的组织、个人合作制作音像制品，未按本规定报送备案的，依照《音像制品管理条例》第四十三条的规定处罚。"},{"i":26,"n":"第二十六条","txt":"音像制作单位有下列行为之一的，依照《音像制品管理条例》第四十四条的规定处罚： （一）变更名称、业务范围，或者兼并其他音像制作单位，或者因合并、分立而设立新的音像制作单位未依照本规定办理审批手续的； （二）变更地址、法定代表人或者主要负责人，或者终止制作经营活动，未依照本规定办理备案手续的。"},{"i":27,"n":"第二十七条","txt":"音像制作单位有下列行为之一的，由出版行政部门责令改正，给予警告；情节严重的，并处3万元以下的罚款： （一）法定代表人或者主要负责人未按本规定参加岗位培训的； （二）未按本规定填写制作或者归档保存制作文档记录的； （三）接受非出版单位委托制作音像制品，未依照本规定验证委托单位的有关证明文件的或者未依照本规定留存备查材料的； （四）未经授权将委托制作的音像制品提供给委托方以外的单位或者个人的； （五）制作的音像制品不符合国家有关质量、技术标准和规定的； （六）未依照有关规定参加年度核验的。"},{"i":28,"n":"第二十八条","txt":"音像制作单位未依法向新闻出版行政部门报送统计资料的，依据新闻出版总署、国家统计局联合颁布的《新闻出版统计管理办法》处罚。"},{"i":29,"n":"第二十九条","txt":"《音像制品制作许可证》由各省、自治区、直辖市新闻出版行政部门根据新闻出版总署制定的样式印制。"},{"i":30,"n":"第三十条","txt":"在本规定施行前已经取得《音像制品制作许可证》的音像制作单位，在经营期限届满前可继续从事音像制作业务；经营期限届满，需延长经营期限的，应当依照本规定重新办理审批手续。"},{"i":31,"n":"第三十一条","txt":"本规定自2008年4月15日起施行。 关于《音像制品制作管理规定》的补充规定 （2010年11月23日中华人民共和国新闻出版总署令第47号公布，自2011年1月1日起施行） 为促进香港、澳门与内地建立更紧密经贸关系，鼓励香港、澳门服务提供者在内地设立商业企业，根据国务院批准的《〈内地与香港关于建立更紧密经贸关系的安排〉补充协议七》及《〈内地与澳门关于建立更紧密经贸关系的安排〉补充协议七》，现就《音像制品制作管理规定》（新闻出版总署令第35号）做出如下补充规定： 一、允许香港、澳门服务提供者在内地设立独资、合资或合作企业，从事音像制品制作业务。 二、本规定中的香港、澳门服务提供者应分别符合《内地与香港关于建立更紧密经贸关系的安排》及《内地与澳门建立更紧密经贸关系的安排》中关于“服务提供者”定义及相关规定的要求。 三、香港、澳门服务提供者在内地投资音像制品制作企业的其他事项，按照《音像制品"}],"yinxiangzhipinjinkouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对音像制品进口的管理，促进国际文化交流与合作，丰富人民群众的文化生活，根据《音像制品管理条例》及国家有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称音像制品，是指录有内容的录音带、录像带、唱片、激光唱盘、激光视盘等。"},{"i":3,"n":"第三条","txt":"凡从外国进口音像制品成品和进口用于出版及其他用途的音像制品，适用本办法。 前款所称出版，包括利用信息网络出版。 音像制品用于广播电视播放的，适用广播电视法律、行政法规。"},{"i":4,"n":"第四条","txt":"新闻出版总署负责全国音像制品进口的监督管理和内容审查等工作。 县级以上地方人民政府新闻出版行政部门依照本办法负责本行政区域内的进口音像制品的监督管理工作。 各级海关在其职责范围内负责音像制品进口的监督管理工作。"},{"i":5,"n":"第五条","txt":"音像制品进口经营活动应当遵守宪法和有关法律、法规，坚持为人民服务和为社会主义服务的方向，传播有益于经济发展和社会进步的思想、道德、科学技术和文化知识。"},{"i":6,"n":"第六条","txt":"国家禁止进口有下列内容的音像制品： （一）反对宪法确定的基本原则的； （二）危害国家统一、主权和领土完整的； （三）泄漏国家秘密、危害国家安全或者损害国家荣誉和利益的； （四）煽动民族仇恨、民族歧视，破坏民族团结，或者侵害民族风俗、习惯的； （五）宣扬邪教、迷信的； （六）扰乱社会秩序，破坏社会稳定的； （七）宣扬淫秽、赌博、暴力或者教唆犯罪的； （八）侮辱或者诽谤他人，侵害他人合法权益的； （九）危害社会公德或者民族优秀文化传统的； （十）有法律、行政法规和国家规定禁止的其他内容的。"},{"i":7,"n":"第七条","txt":"国家对设立音像制品成品进口单位实行许可制度。"},{"i":8,"n":"第八条","txt":"音像制品成品进口业务由新闻出版总署批准的音像制品成品进口单位经营；未经批准，任何单位或者个人不得从事音像制品成品进口业务。"},{"i":9,"n":"第九条","txt":"设立音像制品成品进口经营单位，应当具备以下条件： （一）有音像制品进口经营单位的名称、章程； （二）有符合新闻出版总署认定条件的主办单位及其主管机关； （三）有确定的业务范围； （四）具有进口音像制品内容初审能力； （五）有与音像制品进口业务相适应的资金； （六）有固定的经营场所； （七）法律、行政法规和国家规定的其他条件。"},{"i":10,"n":"第十条","txt":"设立音像制品成品进口经营单位，应当向新闻出版总署提出申请，经审查批准，取得新闻出版总署核发的音像制品进口经营许可证件后，持证到工商行政管理部门依法领取营业执照。 设立音像制品进口经营单位，还应当依照对外贸易法律、行政法规的规定办理相应手续。"},{"i":11,"n":"第十一条","txt":"图书馆、音像资料馆、科研机构、学校等单位进口供研究、教学参考的音像制品成品，应当委托新闻出版总署批准的音像制品成品进口经营单位办理进口审批手续。"},{"i":12,"n":"第十二条","txt":"音像出版单位可以在批准的出版业务范围内从事进口音像制品的出版业务。"},{"i":13,"n":"第十三条","txt":"国家对进口音像制品实行许可管理制度，应在进口前报新闻出版总署进行内容审查，审查批准取得许可文件后方可进口。"},{"i":14,"n":"第十四条","txt":"新闻出版总署设立音像制品内容审查委员会，负责审查进口音像制品的内容。委员会下设办公室，负责进口音像制品内容审查的日常工作。"},{"i":15,"n":"第十五条","txt":"进口音像制品成品，由音像制品成品进口经营单位向新闻出版总署提出申请并报送以下文件和材料： （一）进口录音或录像制品报审表； （二）进口协议草案或订单； （三）节目样片、中外文歌词； （四）内容审查所需的其他材料。"},{"i":16,"n":"第十六条","txt":"进口用于出版的音像制品，应当向新闻出版总署提出申请并报送以下文件和材料： （一）进口录音或录像制品报审表； （二）版权贸易协议中外文文本草案，原始版权证明书，版权授权书和国家版权局的登记文件； （三）节目样片； （四）中外文曲目、歌词或对白； （五）内容审查所需的其他材料。"},{"i":17,"n":"第十七条","txt":"进口用于展览、展示的音像制品，由展览、展示活动主办单位提出申请，并将音像制品目录和样片报新闻出版总署进行内容审查。海关按暂时进口货物管理。"},{"i":18,"n":"第十八条","txt":"进口单位不得擅自更改报送新闻出版总署进行内容审查样片原有的名称和内容。"},{"i":19,"n":"第十九条","txt":"新闻出版总署自受理进口音像制品申请之日起30日内作出批准或者不批准的决定。批准的，发给进口音像制品批准单；不批准的，应当说明理由。 进口音像制品批准单内容不得更改，如需修改，应重新办理。进口音像制品批准单一次报关使用有效，不得累计使用。其中，属于音像制品成品的，批准单当年有效；属于用于出版的音像制品的，批准单有效期限为1年。"},{"i":20,"n":"第二十条","txt":"未经审查批准进口的音像制品，任何单位和个人不得出版、复制、批发、零售、出租和营业性放映。"},{"i":21,"n":"第二十一条","txt":"任何单位和个人不得将供研究、教学参考或者用于展览、展示的进口音像制品进行经营性复制、批发、零售、出租和营业性放映。 用于展览、展示的进口音像制品确需在境内销售、赠送的，在销售、赠送前，必须依照本办法按成品进口重新办理批准手续。"},{"i":22,"n":"第二十二条","txt":"进口单位与外方签订的音像制品进口协议或者合同应当符合中国法律、法规的规定。"},{"i":23,"n":"第二十三条","txt":"出版进口音像制品，应当符合新闻出版总署批准文件要求，不得擅自变更节目名称和增删节目内容，要使用经批准的中文节目名称；外语节目应当在音像制品及封面包装上标明中外文名称；出版进口音像制品必须在音像制品及其包装的明显位置标明国家版权局的登记文号和新闻出版总署进口批准文号；利用信息网络出版进口音像制品必须在相关节目页面标明以上信息。"},{"i":24,"n":"第二十四条","txt":"在经批准进口出版的音像制品版权授权期限内，音像制品进口经营单位不得进口该音像制品成品。"},{"i":25,"n":"第二十五条","txt":"出版进口音像制品使用的语言文字应当符合国家公布的语言文字规范。"},{"i":26,"n":"第二十六条","txt":"进口单位持新闻出版总署进口音像制品批准单向海关办理音像制品的进口报关手续。"},{"i":27,"n":"第二十七条","txt":"个人携带和邮寄音像制品进出境，应以自用、合理数量为限，并按照海关有关规定办理。"},{"i":28,"n":"第二十八条","txt":"随机器设备同时进口以及进口后随机器设备复出口的记录操作系统、设备说明、专用软件等内容的音像制品，不适用本办法，海关验核进口单位提供的合同、发票等有效单证验放。"},{"i":29,"n":"第二十九条","txt":"未经批准，擅自从事音像制品成品进口经营活动的，依照《音像制品管理条例》第三十九条的有关规定给予处罚。"},{"i":30,"n":"第三十条","txt":"有下列行为之一的，由县级以上新闻出版行政部门责令停止违法行为，给予警告，没收违法音像制品和违法所得；违法经营额1万元以上的，并处违法经营额5倍以上10倍以下的罚款；违法经营额不足1万元的，并处5万元以下罚款；情节严重的，并责令停业整顿或者由原发证机关吊销许可证： （一）出版未经新闻出版总署批准擅自进口的音像制品； （二）批发、零售、出租或者放映未经新闻出版总署批准进口的音像制品的； （三）批发、零售、出租、放映供研究、教学参考或者用于展览、展示的进口音像制品的。"},{"i":31,"n":"第三十一条","txt":"违反本办法，出版进口音像制品未标明本办法规定内容的，由省级以上新闻出版行政部门责令改正，给予警告，情节严重的，并责令停业整顿或者由原发证机关吊销许可证。"},{"i":32,"n":"第三十二条","txt":"违反本办法，有下列行为之一的，由省级以上新闻出版行政部门责令改正，给予警告，可并处3万元以下的罚款： （一）出版进口音像制品使用语言文字不符合国家公布的语言文字规范的； （二）出版进口音像制品，违反本办法擅自变更节目名称、增删节目内容的。 擅自增删经审查批准进口的音像制品内容导致其含有本办法第六条规定的禁止内容的，按照《音像制品管理条例》有关条款进行处罚。"},{"i":33,"n":"第三十三条","txt":"违反海关法及有关管理规定的，由海关依法处理。"},{"i":34,"n":"第三十四条","txt":"从中国香港特别行政区、澳门特别行政区和台湾地区进口音像制品，参照本办法执行。"},{"i":35,"n":"第三十五条","txt":"电子出版物的进口参照本办法执行。"},{"i":36,"n":"第三十六条","txt":"本办法由新闻出版总署负责解释。涉及海关业务的，由海关总署负责解释。"},{"i":37,"n":"第三十七条","txt":"本办法自公布之日起施行，2002年6月1日文化部、海关总署发布的《音像制品进口管理办法》同时废止。"}]};
